			version = 1,
			names = { ["area:17203"] = "Stormwind Harbor", ["area:2406"] = "Ranazjar Isle", ["area:2407"] = "Kormek's Hut", ["area:35"] = "Booty Bay", ["area:442"] = "Auberdine", ["area:460"] = "Sun Rock Retreat", ["area:465"] = "Charred Vale", ["area:596"] = "Kodo Graveyard", ["area:598"] = "Sar'theris Strand", ["area:599"] = "Thunder Axe Fortress", ["area:603"] = "Sargeron", ["area:608"] = "Nijel's Point", ["area:609"] = "Kolkar Village", ["item:13703"] = "Kodo Bone", ["item:13892"] = "Kodo Kombobulator", ["item:15878"] = "Rackmore's Silver Key", ["item:15881"] = "Rackmore's Golden Key", ["item:6067"] = "Centaur Ear", ["item:6767"] = "Tyranis' Pendant", ["npc:11438"] = "Bibbly F'utzbuckle", ["npc:11562"] = "Drysnap Crawler", ["npc:11596"] = "Smeed Scrabblescrew", ["npc:11863"] = "Azore Aldamort", ["npc:12369"] = "Lord Kragaru", ["npc:13019"] = "Burning Blade Seer", ["npc:4670"] = "Hatefury Rogue", ["npc:4671"] = "Hatefury Trickster", ["npc:4697"] = "Scorpashi Lasher", ["npc:4700"] = "Aged Kodo", ["npc:4702"] = "Ancient Kodo", ["npc:5396"] = "Captain Pentigast", ["npc:5638"] = "Kreldig Ungor", ["npc:5642"] = "Vahlarriel Demonslayer", ["npc:5643"] = "Tyranis Malem", ["npc:5644"] = "Dalinda Malem", ["npc:5752"] = "Corporal Melkins", ["object:176751"] = "Kodo Bones", ["object:177673"] = "Serpent Statue", ["object:177786"] = "Rackmore's Chest", ["object:177787"] = "Rackmore's Log", ["object:35251"] = "Karnitol's Chest", ["object:417353"] = "Extinguished Campfire", ["quest:5741"] = "Sceptre of Light", ["quest:79229"] = "Highway Robbery", ["quest:93224"] = "Carved Centaur Totems", ["zone:1443"] = "Desolace" },
			written = { ["Back south-east past {npc:11863}'s tower to the Burning Blade's fortress: {npc:5644} hides inside it."] = "Back south-east past Azore's tower to the Burning Blade's fortress: Dalinda hides inside it.", ["Back west up the hill to {npc:11863}'s tower with the sceptre, then south along the road to {area:2407}."] = "Back west up the hill to Azore's tower with the sceptre, then south along the road to Kormek's Hut.", ["Escort {npc:5644}"] = "Escort Dalinda", ["Her brother {npc:5643} (36) walks the fortress with the Burning Blade cultists (30-33): pull him alone. The {npc:13019} keeps the sceptre in the fortress's main building. {npc:5642} wants four of each kind of cultist on the way."] = "Her brother Tyranis (36) walks the fortress with the Burning Blade cultists (30-33): pull him alone. The Burning Blade Seer keeps the sceptre in the fortress's main building. Vahlarriel wants four of each kind of cultist on the way.", ["Lead {npc:5644} out of the fortress; she walks off once you are clear of it. {npc:5642} takes the turn-in at {area:608} at the end of the guide."] = "Lead Dalinda out of the fortress; she walks off once you are clear of it. Vahlarriel takes the turn-in at Nijel's Point at the end of the guide.", ["North-east from {npc:11596}'s camp to {area:609}, on the way back to {area:608}: every Kolkar drops Centaur Ears for {npc:5752} and {quest:93224} for {npc:5396}. The Magram south-east of {npc:11596}'s camp drop them too, but their village holds Necromancers (42-43) and Guardians (39-41): stay with the Kolkar (30-35)."] = "North-east from Smeed's camp to Kolkar Village, on the way back to Nijel's Point: every Kolkar drops Centaur Ears for Corporal Melkins and Carved Centaur Totems for Captain Pentigast. The Magram south-east of Smeed's camp drop them too, but their village holds Necromancers (42-43) and Guardians (39-41): stay with the Kolkar (30-35).", ["North-west from {area:609} back along the road to {area:608}: {npc:11438} waits at {area:2407}. He sends you after the robber to {area:35}, where the next guide ends: keep it."] = "North-west from Kolkar Village back along the road to Nijel's Point: Bibbly waits at Kormek's Hut. He sends you after the robber to Booty Bay, where the next guide ends: keep it.", ["The wrecked ship lies just south-west of {npc:11863}'s tower; its chest sits beside {object:177787}."] = "The wrecked ship lies just south-west of Azore's tower; its chest sits beside Rackmore's Log.", ["Use {npc:11596}'s {item:13892} on an Aged, Dying or {npc:4702}: it becomes a tamed kodo that follows you. Walk it back to {npc:11596}'s camp; there, talk to the kodo: that counts it and lets you tame the next. Five kodos, one at a time. Careful: the Ancient Kodos (36-37) hit hard: tame them, don't fight them."] = "Use Smeed's Kodo Kombobulator on an Aged, Dying or Ancient Kodo: it becomes a tamed kodo that follows you. Walk it back to Smeed's camp; there, talk to the kodo: that counts it and lets you tame the next. Five kodos, one at a time. Careful: the Ancient Kodos (36-37) hit hard: tame them, don't fight them.", ["West into the {area:596} first: {npc:11438}'s {object:176751} lie among the skeletons on its western side. Just north of them an {object:417353} starts {quest:79229}, also for {npc:11438}."] = "West into the Kodo Graveyard first: Bibbly's Kodo Bones lie among the skeletons on its western side. Just north of them an Extinguished Campfire starts Highway Robbery, also for Bibbly.", ["the tamed kodo, at {npc:11596}'s camp: talk to it, five times"] = "the tamed kodo, at Smeed's camp: talk to it, five times", ["{area:2407} stands by the road south of the fortress, on the way to {npc:11596}'s camp. {npc:11438} collects {object:176751}; they lie among the skeletons of the {area:596}, where {npc:11596}'s kodos are."] = "Kormek's Hut stands by the road south of the fortress, on the way to Smeed's camp. Bibbly collects Kodo Bones; they lie among the skeletons of the Kodo Graveyard, where Smeed's kodos are.", ["{npc:11596}'s camp is on the road south of {area:609}, by the {area:596}."] = "Smeed's camp is on the road south of Kolkar Village, by the Kodo Graveyard.", ["{npc:11863}'s tower stands on the hill west of {area:599}: take his quest first, the sceptre he wants is in the fortress."] = "Azore's tower stands on the hill west of Thunder Axe Fortress: take his quest first, the sceptre he wants is in the fortress.", ["{npc:5638}: the wreck's chest lies below {npc:11863}'s tower, on the way to {area:599}"] = "Kreldig Ungor: the wreck's chest lies below Azore's tower, on the way to Thunder Axe Fortress", ["{npc:5643} and the Seer"] = "Tyranis and the Seer" },
