			written = { ["Back to {npc:6122}. Use the {item:6928} at the summoning circle in the {object:2164}'s cellar and defeat the voidwalker it calls."] = "Back to Gakin. Use the Bloodstone Choker at the summoning circle in the Slaughtered Lamb's cellar and defeat the voidwalker it calls.", ["Follow the road south out of {area:87} to the {area:64}. {npc:251} waits by the house."] = "Follow the road south out of Goldshire to the Maclure Vineyards. Maybell waits by the house.", ["Follow the road west back to {area:87}; {npc:6306} stands on the lake shore before town. {npc:377} (priests), {npc:328} (mages) and {npc:917} (rogues) stand upstairs in the inn: take the stairs inside, the arrow cannot tell the floors apart."] = "Follow the road west back to Goldshire; Helene stands on the lake shore before town. Priestess Josetta (priests), Zaldimar Wefhellt (mages) and Keryn Sylvius (rogues) stand upstairs in the inn: take the stairs inside, the arrow cannot tell the floors apart.", ["{area:64}: kill these as you meet them"] = "The Maclure Vineyards: kill these as you meet them", ["{npc:1632}, beside {npc:6306}"] = "Adele Fielder, beside Helene", ["{npc:5504} in {zone:1453}; {area:87} has no druid trainer"] = "Sheldras Moontree in Stormwind City; Goldshire has no druid trainer", ["{zone:1453}"] = "Stormwind City" },
