			written = { ["/sit by {npc:263664}'s campfire until you get {spell:1229451}"] = "/sit by Raan's campfire until you get Boosted Rest", ["Al'Aketh Stormchasers and Footsoldiers camp just north of {npc:257944} and drop the heirloom; the Shrieklings west of her drop the feathers and talons; the {item:265105} grows along the stream west of her."] = "Al'Aketh Stormchasers and Footsoldiers camp just north of Elegael and drop the heirloom; the Shrieklings west of her drop the feathers and talons; the Lady's Tear Moss grows along the stream west of her.", ["Fight north to the {area:16629}. Guardians, Spiritcallers and Blademasters hold the approach; {npc:253576} waits at the shrine's door, {npc:253590} inside the inner sanctum."] = "Fight north to the Shrine of Akir. Guardians, Spiritcallers and Blademasters hold the approach; Hyusaa Quickbreeze waits at the shrine's door, Valennia inside the inner sanctum.", ["Jump off the top of the watchtower and use {spell:1259416} to float down to {npc:251361}, west of the tower."] = "Jump off the top of the watchtower and use Walk on Air to float down to Rorian, west of the tower.", ["Listen to {npc:257554}"] = "Listen to Halaan", ["Lorthuna waits up on the {area:16630}, east of the shrine: take the Portal to {area:16630} in the inner sanctum, beside Valennia, and cross the heights east to {npc:252475}. When she falls, the {object:617084} beside her takes you back to town."] = "Lorthuna waits up on the Rohashi Spires, east of the shrine: take the Portal to Rohashi Spires in the inner sanctum, beside Valennia, and cross the heights east to Elaadrin. When she falls, the Portal to Valanaar beside her takes you back to town.", ["Meet {npc:253844} at the gate"] = "Meet Valennia at the gate", ["Speak to {npc:252448} by the inn on the west side, then cross town to {npc:252359} and {npc:259012}."] = "Speak to Alvarion by the inn on the west side, then cross town to Lotheluum and Ealaane.", ["The Raw Windstones glitter on the ground just south of the grove. {quest:92463} hovers over the meadow further east, on the way to {npc:249363}."] = "The Raw Windstones glitter on the ground just south of the grove. The Cirrusfly Queen hovers over the meadow further east, on the way to Yala.", ["Valennia asks you to hear out both leaders: {npc:252475} of the Alliance and {npc:251968} of the Horde. {npc:251968}'s name shows red to you, but she talks to you all the same, and the quest needs both."] = "Valennia asks you to hear out both leaders: Elaadrin Evengale of the Alliance and Ayessa Dawnsinger of the Horde. Ayessa's name shows red to you, but she talks to you all the same, and the quest needs both.", ["With a profession learned, {npc:263664} also offers its Camping 101, which its trainer in {area:16624} takes on the village round. {quest:93159} has his own for engineers."] = "With a profession learned, Raan also offers its Camping 101, which its trainer in Shen'dar Village takes on the village round. The Strange Hermit has his own for engineers.", ["{item:258771}: the Stormchasers and Footsoldiers around {npc:254151}'s camp"] = "Al'Aketh Cultist's Ear: the Stormchasers and Footsoldiers around Vayn's camp", ["{npc:251361}: {quest:92485}"] = "Rorian: A Student of Nature", ["{npc:251373}, the druid trainer, on the ground floor of the tree behind {npc:251361}"] = "Xyton Silverwind, the druid trainer, on the ground floor of the tree behind Rorian", ["{npc:251913}, beside {npc:251991}"] = "Aedi Thriceforged, beside Taleen", ["{npc:252377}, beside {npc:257006}: {npc:257196} holds the Bulwark at the {area:16629}"] = "Seena Skybreaker, beside Nyalah: Zaal Stormshield holds the Bulwark at the Shrine of Akir", ["{npc:252389}, beside {npc:257006}: the first {item:15908}"] = "Quel'ana Quickgale, beside Nyalah: the first Taming Rod", ["{npc:252800} again"] = "Aamelia again", ["{npc:254151}, {npc:258130} and {npc:258134} are north-east of {npc:257944}; {npc:253622} stands east of them. Haalien also drops a {quest:94490}. For {quest:94489}, enter the Nightfang Den, heal 7 injured druids and find {npc:258130}."] = "Vayn Moongaze, Jorel Windsinger and Naaleos Leafwhisper are north-east of Elegael; Commander Haalien stands east of them. Haalien also drops a Ripped Missive. For The Wounds of Betrayal, enter the Nightfang Den, heal 7 injured druids and find Jorel.", ["{npc:254588}, among the crabs: tame one with {npc:252389}'s first {item:15908} while you are there"] = "Windsong Crawler, among the crabs: tame one with Quel'ana's first Taming Rod while you are there", ["{npc:254589} lurks in the hills south-west of the village, on the way back. {npc:254589} is elite: grouping up is advised."] = "Vulgara lurks in the hills south-west of the village, on the way back. Vulgara the Insatiable is elite: grouping up is advised.", ["{npc:257006} and {npc:252448} stand on {area:16638}'s west side, beside the inn; {npc:252377} and {npc:252389} train just west of {npc:257006}. Windsong Crawlers line the shore further west, around 51,70."] = "Nyalah Brightfire and Alvarion Windfield stand on Valanaar's west side, beside the inn; Seena Skybreaker and Quel'ana Quickgale train just west of Nyalah. Windsong Crawlers line the shore further west, around 51,70.", ["{npc:257019}, west of {npc:251905}"] = "Nyassa Swiftdraught, west of Zerril", ["{npc:257022}, beside {npc:251993}"] = "Messana Crestwind, beside Indari", ["{npc:257554} and {npc:263113} stand at the top of the watchtower, a few steps north-east of {npc:251368}."] = "Halaan Hawk-Eye and Myriaal Mistwake stand at the top of the watchtower, a few steps north-east of Elatrell.", ["{npc:257944} again"] = "Elegael again", ["{npc:270459}, beside {npc:259084}: for {npc:5504} in {zone:1453}"] = "Alfina Nightgaze, beside Denaaris: for Sheldras Moontree in Stormwind", ["{quest:93159} lives west of {npc:257944}. The Zephyrseed Cones lie in the woods between his hut and {npc:257944}."] = "The Strange Hermit lives west of Elegael. The Zephyrseed Cones lie in the woods between his hut and Elegael.", ["{zone:1453}"] = "Stormwind City" },
