 = { races = { \"NightElf\" } },\n\t\twhen = { { k = \"onquest\", neg = true, q = { 94792, 94863, 94864, 94793 } }, { k = \"turnedin\", neg = true, q = 94792 } },\n\t\tgoals = {\n\t\t\t{ t = \"turnin\", quest = 6103, title = \"Training the Beast\", npc = 4146, npcName = \"Jocaste\", map = 1457, x = 40.22, y = 8.75, z = 1343.2, spotsPacked = \"40.2,8.8,1343.2,15,3\", note = \"{npc:4146}: {spell:5149}\" },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{npc:251507} in {area:87}\",\n\t\tnote = \"At 10 go to {npc:251507}, the hunter trainer who stands with the other trainers by the Lion's Pride Inn in {area:87}; {npc:258930}, the pet trainer, is beside her. Skyborne: this is for one who left {zone:2521} without taming; it teaches the same.\",\n\t\tlabel = \"goldshire\",\n\t\tonly = { races = { \"Human\", \"Skyborne\" } },\n\t\tskipto = { { to = \"pet\", when = { k = \"turnedin\", q = 94013 } } },\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 10 },\n\t\t\t{ t = \"accept\", quest = 94792, title = \"Taming the Beast\", npc = 251507, npcName = \"Josephine Carson\", minLevel = 10, qlvl = 10, map = 1429, x = 41.03, y = 66.25, z = 57.4, note = \"{npc:251507}: the first {item:15908}\" },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{npc:524}\",\n\t\tnote = \"Rockhide Boars (level 7-8) graze in three herds south and south-east of {area:87}, toward the {area:64}. How the rod works: target a living beast, use the {item:15908} and stand still for the whole channel while it hits you. Moving, fighting back, a heal from someone else or anyone else hitting the beast breaks it and costs one of the rod's few charges; if they run out, destroy the rod, abandon the quest and take it again. The boars use {spell:6268}, so start with the rod, not {spell:75}. Killing a boar does not count. Keep each rod: it goes back to Josephine. A Dwarf or Night Elf who took Josephine's rod instead of their home trainer's is led through {area:87} from here.\",\n\t\twhen = { { k = \"turnedin\", neg = true, q = 6064 }, { k = \"turnedin\", neg = true, q = 6063 } },\n\t\tgoals = {\n\t\t\t{ t = \"kill\", quest = 94792, title = \"Taming the Beast\", target = \"Rockhide Boar\", npc = 524, count = 1, oi = 1, text = \"Tame {npc:524}\", map = 1429, x = 43.32, y = 77.87, z = 38.3, f = \"e\", spotsPacked = \"43.3,77.9,38.3,40,1;45.6,83.9,,44,3;45,88.3,,40,3;53.3,83.4,,51,5;53.1,75.2,,52,5;48.4,75.9,39.6,40,4;58.9,74.4,51.8,50,6;60.5,81.4,27.3,40,1;63.9,79.6,,40,4;66.2,76.8,,40,3;70.5,74.3,,50,4;73.6,79.6,,75,6;43.9,80.4,27.8,50,4,1;47.2,79.8,29.8,48,6,1;50.1,79.2,40.3,40,2,1;53.8,79.3,,66,5,1;56.4,75.2,54.1,46,5,1;55.7,84.9,,40,2,1;57.6,81.6,,40,2,1;60.9,78.6,,40,5,1;63.5,76.1,,53,4,1;66.5,81.2,,40,3,1;71.7,83,,42,3,1\", spread = true, lvl = 8, note = \"Use the {item:15908} on a living boar\" },\n\t\t\t{ t = \"turnin\", quest = 94792, title = \"Taming the Beast\", npc = 251507, npcName = \"Josephine Carson\", map = 1429, x = 41.03, y = 66.25, z = 57.4 },\n\t\t\t{ t = \"accept\", quest = 94863, title = \"Taming the Beast\", npc = 251507, npcName = \"Josephine Carson\", minLevel = 10, qlvl = 10, pre = { 94792 }, preTitles = { [94792] = \"Taming the Beast\" }, map = 1429, x = 41.03, y = 66.25, z = 57.4 },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{npc:1922}\",\n\t\tnote = \"Dismiss the boar first (right-click the pet portrait, {spell:2641}): a released practice pet can turn on you. Gray Forest Wolves (level 7-8) run in the woods east of {area:87}, east of {area:18}.\",\n\t\twhen = { { k = \"turnedin\", neg = true, q = 6064 }, { k = \"turnedin\", neg = true, q = 6063 } },\n\t\tgoals = {\n\t\t\t{ t = \"kill\", quest = 94863, title = \"Taming the Beast\", target = \"Gray Forest Wolf\", npc = 1922, count = 1, oi = 1, text = \"Tame {npc:1922}\", map = 1429, x = 58.44, y = 62.13, z = 69.4, f = \"e\", spotsPacked = \"59.8,64.4,73.7,71,10;61,60.8,,40,3;64.6,60.3,67.9,40,1;64.6,63.9,,50,3;66.2,66.7,,40,2;67.8,63,,42,4;70.6,62.1,64.6,50,6;73.6,63.9,61.2,40,3;73,67.3,55.3,53,4;69.9,69.5,46.1,40,1;68,58.3,70,56,4;61.3,70.8,,40,3;60.2,67.5,,56,6,1;63.1,69,62.4,40,1,1;68.7,65,60.6,40,3,1\", spread = true, lvl = 8, note = \"Use the {item:15908} on a living wolf\" },\n\t\t\t{ t = \"turnin\", quest = 94863, title = \"Taming the Beast\", npc = 251507, npcName = \"Josephine Carson\", map = 1429, x = 41.03, y = 66.25, z = 57.4 },\n\t\t\t{ t = \"accept\", quest = 94864, title = \"Taming the Beast\", npc = 251507, npcName = \"Josephine Carson\", minLevel = 10, qlvl = 10, pre = { 94863 }, preTitles = { [94863] = \"Taming the Beast\" }, map = 1429, x = 41.03, y = 66.25, z = 57.4 },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{npc:822}\",\n\t\tnote = \"Dismiss the wolf. Young Forest Bears (level 8-9) roam the woods just south of {area:87}, with more south-west and south-east of town.\",\n\t\twhen = { { k = \"turnedin\", neg = true, q = 6064 }, { k = \"turnedin\", neg = true, q = 6063 } },\n\t\tgoals = {\n\t\t\t{ t = \"kill\", quest = 94864, title = \"Taming the Beast\", target = \"Young Forest Bear\", npc = 822, count = 1, oi = 1, text = \"Tame {npc:822}\", map = 1429, x = 43.4, y = 80.4, f = \"e\", spotsPacked = \"43.6,80.7,31.5,40,3;36,88.3,34.4,40,3;26.2,90,,40,8;22.6,75.6,32.1,40,2;53.5,83.7,,40,3;60.6,79.9,,40,4;64.6,63,67.9,40,2;74.9,67.5,,40,5;81.8,59,,40,5;81.2,77.2,52,40,1;88.7,77.4,51,40,3;73.4,81,39.4,40,3;44.9,77,,40,4,1;47.1,79.7,,40,2,1;45.7,86,,40,3,1;49.1,82.1,,40,2,1;49.1,75.3,,55,4,1;38.5,89.2,,40,2,1;54,75.4,,40,2,1;57.1,75.6,51.6,40,3,1;28,81.3,,40,3,1;58.8,68.2,,40,1,1;60.7,75.3,,40,2,1;25.3,83.5,,44,6,1;63.3,77.6,,42,4,1;65.7,78,41.5,40,4,1;70.5,74.6,42.3,40,3,1;68.7,64.7,,40,3,1;71.9,61,,40,5,1;76.8,76.6,39.9,40,1,1;78.3,79.4,37.8,40,2,1;79.2,83.5,,40,2,1;78.2,60.9,,40,6,1;82.8,84,,40,1,1;86,77.2,,40,1,1;87.5,69.4,60.3,40,3,1;87.1,64.6,,40,6,1\", spread = true, lvl = 9, note = \"Use the {item:15908} on a living bear\" },\n\t\t\t{ t = \"turnin\", quest = 94864, title = \"Taming the Beast\", npc = 251507, npcName = \"Josephine Carson\", map = 1429, x = 41.03, y = 66.25, z = 57.4, note = \"{npc:251507}: {spell:1515}\" },\n\t\t\t{ t = \"accept\", quest = 94793, title = \"Training the Beast\", npc = 251507, npcName = \"Josephine Carson\", minLevel = 10, qlvl = 10, pre = { 94864 }, preTitles = { [94864] = \"Taming the Beast\" }, map = 1429, x = 41.03, y = 66.25, z = 57.4 },\n\t\t\t{ t = \"turnin\", quest = 94793, title = \"Training the Beast\", npc = 258930, npcName = \"Isaac Chan\", map = 1429, x = 41.68, y = 66.34, z = 57, note = \"{npc:258930}, beside her: {spell:5149}\" },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"Your first pet\",\n\t\tnote = \"{spell:1515} works like the rod: a beast of your level or lower, a channel you must not move during, the beast hitting you all the while. A pet keeps the level you tame it at and levels up with you; it can never be above your level, so tame one close to yours. Each family has its own ability on Forever (a boar's Charge, for example). For levelling, a cat hits hardest (Claw and {spell:17253}) and a boar takes more punishment.\",\n\t\tlabel = \"pet\",\n\t\tgoals = {\n\t\t\t{ t = \"task\", text = \"Tame a beast of your level to keep\", optional = true },\n\t\t\t{ t = \"note\", text = \"Near {area:87} there are no cats: Prowlers (wolves, level 9-10) roam eastern Elwynn, Longsnouts (boars, 10-11) its far south-west by the {zone:1436} border; at 12-13, Young Goretusks (boars) graze the fields of northern {zone:1436}.\", only = { races = { \"Human\" } } },\n\t\t\t{ t = \"note\", text = \"Near {area:131}: Snow Leopards (cats, level 7-8) prowl all over {zone:1426}, Scarred Crag Boars (9-10) its east toward {zone:1432}; at 10-11, Mountain Boars roam western {zone:1432}.\", only = { races = { \"Dwarf\" } } },\n\t\t\t{ t = \"note\", text = \"Near {area:186}: Elder Nightsabers (cats, level 8-9) and Feral Nightsabers (cats, 10-11) prowl the woods of north-western {zone:1438}.\", only = { races = { \"NightElf\" } } },\n\t\t\t{ t = \"note\", text = \"Near {area:16638}: Vuldren Alphas (level 10), the beast of your last practice tame, hunt the {area:16626}; Shriekling Matriarchs (raptors, level 9) nest just west of {area:16638}; Shadowgale Urseras (bears, 10-11) roam the north of {zone:2521}.\", only = { races = { \"Skyborne\" } } },\n\t\t\t{ t = \"note\", text = \"{spell:1584}: open your spellbook, cast {spell:1584} and click a food your pet's family eats (the pet's tooltip lists them: cats eat meat and fish, boars almost anything). Raw meat looted from beasts counts. To buy: Toddrick the butcher in {area:87}, Jaeana in {zone:1457} and the innkeepers on {zone:2521} sell meat; the innkeepers of {area:131} and {area:186} sell bread. Food near the pet's level makes it happiest; much lower food gives about half. You cannot feed in combat.\" },\n\t\t\t{ t = \"note\", text = \"Happiness: the face on the pet frame. An unhappy pet does three quarters of its damage, a happy one a quarter more. Happiness drains slowly, faster when the pet dies; a pet left unhappy too long can run away.\" },\n\t\t\t{ t = \"note\", text = \"Loyalty grows with time and kills. Each loyalty rank raises the training points you spend in {spell:5149} (pet level times loyalty rank minus one).\" },\n\t\t\t{ t = \"note\", text = \"{spell:5149} (spellbook, General tab) teaches your current pet the abilities you know. To learn a new ability or rank: leave your pet with a stable master (Erma in {area:87}, {npc:9980} in {area:131}, Seriadne in {area:186}, {npc:265756} on {zone:2521}), tame a beast that has it (its pet spellbook tab shows what it knows), use the ability in fights until the game says you learned it, then take your own pet back and teach it with {spell:5149}. A pet holds four active abilities at most.\" },\n\t\t\t{ t = \"note\", text = \"Pet trainers sell {spell:1853} ranks and resistances. Alliance: {npc:258930} in {area:87}, {npc:2879} by the hunter trainers in {zone:1453}'s {object:28027}, {npc:2878} in {area:131}, {npc:10090} in {zone:1455}'s {object:32390}, Keldas in {area:186}, Silvaria in {zone:1457}' Cenarion Enclave, {npc:254411} in {area:16638}.\" },\n\t\t\t{ t = \"note\", text = \"{spell:883}, {spell:2641} and {spell:982} are in your spellbook now; {spell:136} comes from your trainer at 12. A dead pet needs {spell:982}; one that is away more than about 100 yards is dismissed and comes back with {spell:883}.\" },\n\t\t},\n\t},\n}",
		})
	end
	register()
end

