			classes = { "MAGE" },
			minLevel = 26,
			maxLevel = 30,
			category = "Class",
			folder = "Mage",
			keywords = { "High Sorcerer Andromath", "Ur's Treatise on Shadow Magic", "Tower of Ilgalar", "Redridge Mountains", "Pristine Spider Silk", "Carrion Recluse", "Duskwood", "Wynne Larson", "Astral Knot Robe", "Astral Knot Blouse", "Mage", "class robe" },
			reward = { { item = 7511, itemName = "Astral Knot Robe", choice = true }, { item = 9516, itemName = "Astral Knot Blouse", choice = true } },
			why = "A robe or a blouse for Alliance mages in their late 20s.",
			zone = 1453,
			zoneName = "Stormwind City",
			author = "Polestar",
			version = 1,
			names = { ["area:2257"] = "Deeprun Tram", ["area:492"] = "Raven Hill Cemetery", ["area:69"] = "Lakeshire", ["area:96"] = "Tower of Ilgalar", ["npc:1309"] = "Wynne Larson", ["npc:5144"] = "Bink", ["npc:522"] = "Mor'Ladim", ["npc:5497"] = "Jennea Cannon", ["npc:930"] = "Black Widow Hatchling", ["npc:949"] = "Carrion Recluse", ["object:171524"] = "Tinker Town", ["object:2101"] = "Mage Quarter", ["object:23296"] = "Larson Clothiers", ["object:32362"] = "Mystic Ward", ["quest:1939"] = "High Sorcerer Andromath", ["quest:1942"] = "Astral Knot Garment", ["spell:2691"] = "Mana Burn", ["spell:3609"] = "Paralyzing Poison", ["zone:1429"] = "Elwynn Forest", ["zone:1431"] = "Duskwood", ["zone:1453"] = "Stormwind", ["zone:1455"] = "Ironforge" },
			stepCount = 8,
			stepsSrc = "return {\n\t{\n\t\ttitle = \"{npc:5144} ({zone:1455})\",\n\t\tnote = \"{npc:5144} teaches mages in {zone:1455}'s {object:32362}. Take the {area:2257} from {object:171524} to {zone:1453} afterwards.\",\n\t\tonly = { races = { \"Gnome\" } },\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 26 },\n\t\t\t{ t = \"accept\", quest = 1939, title = \"High Sorcerer Andromath\", npc = 5144, npcName = \"Bink\", minLevel = 26, qlvl = 26, closedBy = { 1938 }, endNpcs = { 5694 }, xp = 1050, preTitles = { [1938] = \"Ur's Treatise on Shadow Magic\" }, map = 1455, x = 26.93, y = 8.28, z = 501.2, spotsPacked = \"26.9,8.3,501.2,15,6\" },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{npc:5497} ({zone:1453})\",\n\t\tnote = \"{npc:5497} stands at the top of the Wizard's Sanctum, the violet tower of the {object:2101}; the portal near the top of the spiral ramp takes you to her.\",\n\t\tonly = { races = { \"Human\" } },\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 26 },\n\t\t\t{ t = \"accept\", quest = 1939, title = \"High Sorcerer Andromath\", npc = 5497, npcName = \"Jennea Cannon\", minLevel = 26, qlvl = 26, closedBy = { 1938 }, endNpcs = { 5694 }, xp = 1050, preTitles = { [1938] = \"Ur's Treatise on Shadow Magic\" }, map = 1453, x = 49.51, y = 85.99, z = 29.7, spotsPacked = \"49.5,86,29.7,15,3\" },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{quest:1939} (Skyborne)\",\n\t\tnote = \"You do not need a letter: at 26 climb the Wizard's Sanctum, the violet tower of {zone:1453}'s {object:2101}. {quest:1939} waits on the spiral walkway, just past the door of the portal room near the top, and has the quest for you. ({npc:5497} may also offer you {quest:1939}, the pointer quest; it is only a pointer and you can skip it.)\",\n\t\tonly = { races = { \"Skyborne\" } },\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 27 },\n\t\t\t{ t = \"accept\", quest = 1938, title = \"Ur's Treatise on Shadow Magic\", npc = 5694, npcName = \"High Sorcerer Andromath\", minLevel = 26, qlvl = 28, crumbs = { 1939 }, preTitles = { [1939] = \"High Sorcerer Andromath\" }, map = 1453, x = 48.68, y = 87.39, z = 148.7, spotsPacked = \"48.8,87.6,148.7,15,3\" },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{quest:1939}\",\n\t\tnote = \"{quest:1939} waits on the spiral walkway of the Wizard's Sanctum, just past the door of the portal room as you walk down from the trainers.\",\n\t\tonly = { races = { \"Human\", \"Gnome\" } },\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 27 },\n\t\t\t{ t = \"turnin\", quest = 1939, title = \"High Sorcerer Andromath\", npc = 5694, npcName = \"High Sorcerer Andromath\", map = 1453, x = 48.68, y = 87.39, z = 148.7, spotsPacked = \"48.8,87.6,148.7,15,3\" },\n\t\t\t{ t = \"accept\", quest = 1938, title = \"Ur's Treatise on Shadow Magic\", npc = 5694, npcName = \"High Sorcerer Andromath\", minLevel = 26, qlvl = 28, crumbs = { 1939 }, preTitles = { [1939] = \"High Sorcerer Andromath\" }, map = 1453, x = 48.68, y = 87.39, z = 148.7, spotsPacked = \"48.8,87.6,148.7,15,3\" },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"The {area:96}\",\n\t\tnote = \"Head east through {zone:1429} into Redridge, or fly to {area:69}. The {area:96} stands alone in the east of the zone. Climb to the very top floor (not the one below): the treatise is the book sticking out of the shelf where the stairs come up. Two gnoll dogs and a gnoll caster guard the shelf; the dogs' {spell:2691} interrupts the click, so fight them on the stairs out of their sight. Morganth (level 26 elite) stands across the top floor: you do not need him, keep to the left edge of the ramp so he stays put. The book is back two seconds after anyone takes it. If you die, your ghost can run up and come back to life beside it.\",\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 28 },\n\t\t\t{ t = \"collect\", quest = 1938, title = \"Ur's Treatise on Shadow Magic\", item = 7266, itemName = \"Ur's Treatise on Shadow Magic\", count = 1, oi = 1, map = 1433, x = 73.77, y = 47.61, z = 150.9, from = \"Ur's Treatise on Shadow Magic\", fromKind = \"object\", fromId = 103628, group = { kind = \"elite\", lvl = 27, near = true, rank = 1 } },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"Back to Andromath\",\n\t\tgoals = {\n\t\t\t{ t = \"turnin\", quest = 1938, title = \"Ur's Treatise on Shadow Magic\", npc = 5694, npcName = \"High Sorcerer Andromath\", map = 1453, x = 48.8, y = 87.63, z = 148.7, spotsPacked = \"48.8,87.6,148.7,15,3\" },\n\t\t\t{ t = \"accept\", quest = 1940, title = \"Pristine Spider Silk\", npc = 5694, npcName = \"High Sorcerer Andromath\", minLevel = 26, qlvl = 26, pre = { 1938 }, preTitles = { [1938] = \"Ur's Treatise on Shadow Magic\" }, map = 1453, x = 48.7, y = 87.77, z = 148.7, spotsPacked = \"48.8,87.6,148.7,15,3\" },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"Carrion Recluses\",\n\t\tnote = \"{area:492} in western {zone:1431}: the six Carrion Recluses (level 25-26, green, {spell:3609}) walk the graves, the central statue and the riverbank, and every one drops a silk; they come back after 5 minutes. The Black Widow Hatchlings (24-25) on the slopes east of the cemetery drop it about one time in six, so mix them in while you wait. {npc:522}, a level 35 elite skeleton, walks the cemetery: watch for him.\",\n\t\tgoals = {\n\t\t\t{ t = \"collect\", quest = 1940, title = \"Pristine Spider Silk\", item = 7267, itemName = \"Pristine Spider Silk\", count = 8, oi = 1, map = 1431, x = 19.99, y = 41.24, f = \"e\", spotsPacked = \"21,39.1,36.7,15,1;17.9,40.9,,36,2;18.1,43.7,31.8,15,1;21.5,46.3,30.9,15,1;23.4,36.7,33.8,15,1\", lvl = 26, from = \"Carrion Recluse\", fromKind = \"npc\", fromAlso = \"Black Widow Hatchling\", fromId = 949, fromAlsoId = 930, fromNpcs = { { npc = 949, npcName = \"Carrion Recluse\" } } },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{npc:1309}\",\n\t\tnote = \"{npc:1309} works at {object:23296} in the {object:2101}. The robe gives intellect, stamina and spirit; the blouse more intellect and stamina but no spirit.\",\n\t\tgoals = {\n\t\t\t{ t = \"turnin\", quest = 1940, title = \"Pristine Spider Silk\", npc = 1309, npcName = \"Wynne Larson\", map = 1453, x = 51.95, y = 83.58, z = 109.4, spotsPacked = \"51.9,83.6,109.4,15,4\" },\n\t\t\t{ t = \"accept\", quest = 1942, title = \"Astral Knot Garment\", npc = 1309, npcName = \"Wynne Larson\", minLevel = 26, qlvl = 26, pre = { 1940 }, preTitles = { [1940] = \"Pristine Spider Silk\" }, map = 1453, x = 52.07, y = 83.54, z = 109.4, spotsPacked = \"51.9,83.6,109.4,15,4\" },\n\t\t\t{ t = \"turnin\", quest = 1942, title = \"Astral Knot Garment\", npc = 1309, npcName = \"Wynne Larson\", map = 1453, x = 52.07, y = 83.54, z = 109.4, spotsPacked = \"51.9,83.6,109.4,15,4\", note = \"{quest:1942}\", rewards = { choices = { { item = 7511, itemName = \"Astral Knot Robe\" }, { item = 9516, itemName = \"Astral Knot Blouse\" } } } },\n\t\t},\n\t},\n}",
		})
	end
	register()
end

-- Source: forever/class/mage/manaweave-robe.guide
