			faction = "Alliance",
			classes = { "MAGE" },
			minLevel = 15,
			maxLevel = 17,
			category = "Class",
			folder = "Mage",
			keywords = { "Jennea Cannon", "Investigate the Blue Recluse", "Gathering Materials", "Wynne Larson", "Rift Spawn", "Charged Rift Gem", "Silver Stream Mine", "Loch Modan", "Manaweave Robe", "Mage", "class robe" },
			reward = { { item = 7509, itemName = "Manaweave Robe" } },
			why = "A robe at 15 for Alliance mages, from {zone:1453} and {zone:1432}.",
			zone = 1453,
			zoneName = "Stormwind City",
			author = "Polestar",
			version = 1,
			names = { ["area:144"] = "Thelsamar", ["area:149"] = "Silver Stream Mine", ["area:2257"] = "Deeprun Tram", ["area:87"] = "Goldshire", ["item:2589"] = "Linen Cloth", ["item:7247"] = "Chest of Containment Coffers", ["item:7249"] = "Charged Rift Gem", ["item:7292"] = "Filled Containment Coffer", ["item:7308"] = "Cantation of Manifestation", ["npc:1309"] = "Wynne Larson", ["npc:328"] = "Zaldimar Wefhellt", ["npc:5497"] = "Jennea Cannon", ["npc:6492"] = "Rift Spawn", ["npc:7312"] = "Dink", ["object:171524"] = "Tinker Town", ["object:2096"] = "Trade District", ["object:2101"] = "Mage Quarter", ["object:2169"] = "The Blue Recluse", ["object:23296"] = "Larson Clothiers", ["object:271"] = "Miners' League Crates", ["object:32362"] = "Mystic Ward", ["quest:1941"] = "Manaweave Robe", ["spell:122"] = "Frost Nova", ["zone:1432"] = "Loch Modan", ["zone:1453"] = "Stormwind", ["zone:1455"] = "Ironforge" },
			stepCount = 8,
			stepsSrc = "return {\n\t{\n\t\ttitle = \"{npc:328} ({area:87})\",\n\t\tnote = \"{npc:328} is the {area:87} mage trainer, upstairs in the Lion's Pride Inn.\",\n\t\tonly = { races = { \"Human\", \"Skyborne\" } },\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 15 },\n\t\t\t{ t = \"accept\", quest = 1919, title = \"Report to Jennea\", npc = 328, npcName = \"Zaldimar Wefhellt\", minLevel = 15, qlvl = 15, closedBy = { 1920 }, endNpcs = { 5497 }, xp = 110, preTitles = { [1920] = \"Investigate the Blue Recluse\" }, map = 1429, x = 43.27, y = 66.19, z = 63.9 },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{npc:7312} ({zone:1455})\",\n\t\tnote = \"{npc:7312} teaches mages in {zone:1455}'s {object:32362}. Take the {area:2257} from {object:171524} to {zone:1453} afterwards.\",\n\t\tonly = { races = { \"Gnome\" } },\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 15 },\n\t\t\t{ t = \"accept\", quest = 1919, title = \"Report to Jennea\", npc = 7312, npcName = \"Dink\", minLevel = 15, qlvl = 15, closedBy = { 1920 }, endNpcs = { 5497 }, xp = 110, preTitles = { [1920] = \"Investigate the Blue Recluse\" }, map = 1455, x = 26.87, y = 8.42, z = 501.2, spotsPacked = \"26.9,8.4,501.2,15,5\" },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{npc:5497}\",\n\t\tnote = \"{npc:5497} stands at the top of the Wizard's Sanctum, the violet tower of the {object:2101}: climb the spiral ramp and take the portal near the top. The {item:7247} and the {item:7308} lie on the table behind her (both come back 5 minutes after someone takes them). You hand both in at the end, so keep them.\",\n\t\tgoals = {\n\t\t\t{ t = \"turnin\", quest = 1919, title = \"Report to Jennea\", npc = 5497, npcName = \"Jennea Cannon\", map = 1453, x = 49.51, y = 85.99, z = 29.7, spotsPacked = \"49.5,86,29.7,15,3\" },\n\t\t\t{ t = \"accept\", quest = 1920, title = \"Investigate the Blue Recluse\", npc = 5497, npcName = \"Jennea Cannon\", minLevel = 15, qlvl = 16, crumbs = { 1919 }, preTitles = { [1919] = \"Report to Jennea\" }, map = 1453, x = 49.5, y = 86.19, z = 29.7, spotsPacked = \"49.5,86,29.7,15,3\" },\n\t\t\t{ t = \"collect\", quest = 1920, title = \"Investigate the Blue Recluse\", item = 7247, itemName = \"Chest of Containment Coffers\", count = 1, oi = 2, map = 1453, x = 49.54, y = 86.06, z = 30.6, spotsPacked = \"49.45,85.48,30.6,0;49.54,86.06,30.6,0\", from = \"Chest of Containment Coffers\", fromKind = \"object\", fromId = 105174 },\n\t\t\t{ t = \"collect\", quest = 1920, title = \"Investigate the Blue Recluse\", item = 7308, itemName = \"Cantation of Manifestation\", count = 1, oi = 3, map = 1453, x = 49.59, y = 85.71, z = 30.7, spotsPacked = \"49.6,85.5,30.7,15,2\", from = \"Cantation of Manifestation\", fromKind = \"object\", fromId = 105175 },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{object:2169}\",\n\t\tnote = \"{object:2169} is the tavern in the {object:2101}. Read the {item:7308} inside to make the invisible Rift Spawns (level 16-17) show: in the basement it brings out one, on the balcony or in the kitchen two, in the main room or by the door three, so read it downstairs. They hit hard and break out of {spell:122} fast. Beat one down: it does not die but sits stunned with a spiral over its head; use the {item:7247} on it while it is stunned, then click the {item:7292} it leaves on the floor (clicking before it appears wastes a charge). You need three, and the cantation works only once every 5 minutes (logging out does not reset it), so plan on three rounds.\",\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 16 },\n\t\t\t{ t = \"use\", item = 7308, itemName = \"Cantation of Manifestation\", map = 1453, x = 51.3, y = 93.3, optional = true },\n\t\t\t{ t = \"kill\", target = \"Rift Spawn\", npc = 6492, map = 1453, x = 51.3, y = 93.33, z = 108.4, spotsPacked = \"51.2,93.7,108.4,18,5\", lvl = 17, optional = true, note = \"{npc:6492}, down to the stun\" },\n\t\t\t{ t = \"use\", item = 7247, itemName = \"Chest of Containment Coffers\", map = 1453, x = 51.3, y = 93.3, optional = true, note = \"{item:7247}, on the stunned {npc:6492}\" },\n\t\t\t{ t = \"collect\", quest = 1920, title = \"Investigate the Blue Recluse\", item = 7292, itemName = \"Filled Containment Coffer\", count = 3, oi = 1, map = 1453, x = 51.3, y = 93.3, spotsPacked = \"50.58,92.92,,0;50.75,95.31,,0;50.99,92.37,,0;51.17,95.86,,0;51.19,93.01,,0;51.61,94.5,,0;52,94.3,,0\", from = \"Filled Containment Coffer\", fromKind = \"object\", fromId = 103574 },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"Back to {npc:5497}\",\n\t\tgoals = {\n\t\t\t{ t = \"turnin\", quest = 1920, title = \"Investigate the Blue Recluse\", npc = 5497, npcName = \"Jennea Cannon\", map = 1453, x = 49.5, y = 86.19, z = 29.7, spotsPacked = \"49.5,86,29.7,15,3\" },\n\t\t\t{ t = \"accept\", quest = 1921, title = \"Gathering Materials\", npc = 5497, npcName = \"Jennea Cannon\", minLevel = 15, qlvl = 15, pre = { 1920 }, preTitles = { [1920] = \"Investigate the Blue Recluse\" }, map = 1453, x = 49.5, y = 86.19, z = 29.7, spotsPacked = \"49.5,86,29.7,15,3\" },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{item:2589}\",\n\t\tnote = \"Any humanoid drops {item:2589}, and the Tunnel Rats in the {area:149} drop it while you gather the gems; the Auction House in the {object:2096} sells it. You hand in ten.\",\n\t\tgoals = {\n\t\t\t{ t = \"collect\", quest = 1921, title = \"Gathering Materials\", item = 2589, itemName = \"Linen Cloth\", count = 10, oi = 1, map = 1453, x = 61.2, y = 71.3, spotsPacked = \"61.2,71.3,,15,0;42.79,72.36,99.2,0,,1,26;73.75,59.18,,0,,1,26\", note = \"{item:2589}: humanoids, or the Auction House\", fromNpcs = { { npc = 4969, npcName = \"Old Town Thug\" }, { npc = 2044, npcName = \"Forlorn Spirit\" } } },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"The {area:149}\",\n\t\tnote = \"Take the {area:2257} to {zone:1455}, then the road east through the South Gate tunnel into {zone:1432}. The {area:149} is at the north end of the loch, north of {area:144}; Tunnel Rat kobolds hold it. The gems come only from the tall stacked {object:271} (the cursor shows a cog over them; single boxes hold nothing): every crate gives one, there are fourteen and they come back after 3 to 5 minutes. You may have to go as deep as the end chamber for six. The same crates serve the dwarves' Filthy Paws quest.\",\n\t\tgoals = {\n\t\t\t{ t = \"collect\", quest = 1921, title = \"Gathering Materials\", item = 7249, itemName = \"Charged Rift Gem\", count = 6, oi = 2, map = 1432, x = 35.48, y = 24.1, z = 321.8, f = \"e\", spotsPacked = \"34.21,26.49,315.9,0;34.69,26.64,314.9,0;34.77,23.35,316.9,0;34.86,24.86,321.2,0;34.88,26.94,314.9,0;35.03,23.17,316.9,0;35.12,24.47,317.7,0;35.14,24.1,317.7,0;35.25,21.77,316.6,0;35.39,22.04,316.6,0;35.46,19.88,321.5,0;35.7,22.15,317,0;35.71,24.29,321.8,0;35.71,27.78,314.4,0;35.86,27.47,314.4,0;36.13,24.58,319.9,0;36.31,20.48,317.4,0;36.34,24.83,319.9,0;36.46,20.79,317.4,0;36.66,26.02,318.5,0\", note = \"{item:7249}: {object:271}\", from = \"Miners' League Crates\", fromKind = \"object\", fromId = 271 },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{npc:1309}\",\n\t\tnote = \"Back to {zone:1453} by the tram. {npc:1309} works at {object:23296} in the {object:2101}.\",\n\t\tgoals = {\n\t\t\t{ t = \"turnin\", quest = 1921, title = \"Gathering Materials\", npc = 1309, npcName = \"Wynne Larson\", map = 1453, x = 51.95, y = 83.58, z = 109.4, spotsPacked = \"51.9,83.6,109.4,15,4\" },\n\t\t\t{ t = \"accept\", quest = 1941, title = \"Manaweave Robe\", npc = 1309, npcName = \"Wynne Larson\", minLevel = 15, qlvl = 15, pre = { 1921 }, preTitles = { [1921] = \"Gathering Materials\" }, map = 1453, x = 52.07, y = 83.54, z = 109.4, spotsPacked = \"51.9,83.6,109.4,15,4\" },\n\t\t\t{ t = \"turnin\", quest = 1941, title = \"Manaweave Robe\", npc = 1309, npcName = \"Wynne Larson\", map = 1453, x = 52.07, y = 83.54, z = 109.4, spotsPacked = \"51.9,83.6,109.4,15,4\", note = \"{npc:1309}: {quest:1941}\" },\n\t\t},\n\t},\n}",
		})
	end
	register()
end

