do
	local function register()
		Polestar.RegisterGuide({
			id = "forever/class/mage/staff-or-orb-alliance",
			pack = "guides",
			title = "Ley or {item:9514} or Orb (Alliance)",
			faction = "Alliance",
			classes = { "MAGE" },
			minLevel = 10,
			maxLevel = 15,
			category = "Class",
			folder = "Mage",
			keywords = { "Speak with Jennea", "Mirror Lake", "Jennea Cannon", "Zaldimar Wefhellt", "Jennea's Flask", "Speak with Bink", "Mage-tastic Gizmonitor", "Bink", "Magis Sparkmantle", "Bink's Toolbox", "Speak with Belann", "Boughs in the Wind", "Belann Windwood", "Anathamaas Aetherwind", "Windbough Wand", "Ley Staff", "Ley Orb", "Arcane Staff", "Arcane Orb", "Mage", "class weapon" },
			reward = { { item = 7508, itemName = "Ley Orb", choice = true }, { item = 9513, itemName = "Ley Staff", choice = true }, { item = 7507, itemName = "Arcane Orb", choice = true }, { item = 9514, itemName = "Arcane Staff", choice = true }, { item = 263430, itemName = "Windbough Wand" } },
			why = "A staff or an off-hand orb at 10 from your home town's mage trainer; Skyborne add a wand.",
			zone = 1429,
			zoneName = "Elwynn Forest",
			author = "Polestar",
			version = 1,
			names = { ["area:131"] = "Kharanos", ["area:133"] = "Gnomeregan", ["area:16636"] = "Falaath Village", ["area:16638"] = "Valanaar", ["area:2102"] = "Thunderbrew Distillery", ["area:87"] = "Goldshire", ["item:262668"] = "Wind-Infused Bough", ["item:263430"] = "Windbough Wand", ["item:7207"] = "Jennea's Flask", ["item:7507"] = "Arcane Orb", ["item:7508"] = "Ley Orb", ["item:9513"] = "Ley Staff", ["item:9514"] = "Arcane Staff", ["npc:1211"] = "Leper Gnome", ["npc:1228"] = "Magis Sparkmantle", ["npc:252373"] = "Anathamaas Aetherwind", ["npc:256507"] = "Belann Windwood", ["npc:328"] = "Zaldimar Wefhellt", ["npc:5144"] = "Bink", ["npc:5497"] = "Jennea Cannon", ["object:102984"] = "Bink's Toolbox", ["object:2101"] = "Mage Quarter", ["object:32362"] = "Mystic Ward", ["object:32386"] = "Hall of Mysteries", ["object:697118"] = "Windstone Formation", ["quest:1860"] = "Speak with Jennea", ["quest:1861"] = "Mirror Lake", ["quest:1879"] = "Speak with Bink", ["zone:1453"] = "Stormwind", ["zone:1455"] = "Ironforge", ["zone:2521"] = "Zephras Isle" },
			written = { ["At 10 {npc:1228}, the {area:131} mage trainer in the {area:2102}, sends you to {npc:5144} in {zone:1455}. Taking it shuts out {quest:1860}, the {area:87} trainer's errand; {npc:5144}'s Gizmonitor and {npc:5497}'s {quest:1861} shut out each other, so you get one staff or orb. (A Gnome who took {npc:328}'s quest in {area:87} instead follows the {quest:1861} steps; a Human who took this one, the Gizmonitor steps.)"] = "At 10 Magis Sparkmantle, the Kharanos mage trainer in the Thunderbrew Distillery, sends you to Bink in Ironforge. Taking it shuts out Speak with Jennea, the Goldshire trainer's errand; Bink's Gizmonitor and Jennea's Mirror Lake shut out each other, so you get one staff or orb. (A Gnome who took Zaldimar's quest in Goldshire instead follows the Mirror Lake steps; a Human who took this one, the Gizmonitor steps.)", ["Back to {npc:256507}"] = "Back to Belann", ["Back to {npc:5497}"] = "Back to Jennea", ["Follow the road north into {zone:1453} and west to the {object:2101}. {npc:5497} stands at the top of the Wizard's Sanctum, the tall violet tower: climb the spiral ramp and step into the portal near the top, which puts you beside her. She hands you {item:7207}. Skyborne mages take {quest:1861} from her when they first reach {zone:1453}, at about 15."] = "Follow the road north into Stormwind and west to the Mage Quarter. Jennea stands at the top of the Wizard's Sanctum, the tall violet tower: climb the spiral ramp and step into the portal near the top, which puts you beside her. She hands you Jennea's Flask. Skyborne mages take Mirror Lake from her when they first reach Stormwind, at about 15.", ["{npc:256507}'s quest is open to Human and Gnome mages too, if you ever visit {area:16638} on {zone:2521}, the Skyborne home: {npc:252373}, the town's mage trainer, sends you to {npc:256507} next door, who wants a {item:262668} from the ground by the Windstone Formations south of {area:16636}, for the {item:263430}. It does not shut out the staff or the orb."] = "Belann's quest is open to Human and Gnome mages too, if you ever visit Valanaar on Zephras Isle, the Skyborne home: Anathamaas Aetherwind, the town's mage trainer, sends you to Belann Windwood next door, who wants a Wind-Infused Bough from the ground by the Windstone Formations south of Falaath Village, for the Windbough Wand. It does not shut out the staff or the orb.", ["{npc:256507}'s wand (optional)"] = "Belann's wand (optional)" },
			stepCount = 12,
			stepsSrc = "return {\n\t{\n\t\ttitle = \"{npc:252373} ({area:16638})\",\n\t\tnote = \"At 10 {npc:252373}, the {area:16638} mage trainer, sends you to {npc:256507}, the staff merchant a few steps away in the same town.\",\n\t\tonly = { races = { \"Skyborne\" } },\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 10 },\n\t\t\t{ t = \"accept\", quest = 93791, title = \"Speak with Belann\", npc = 252373, npcName = \"Anathamaas Aetherwind\", minLevel = 10, qlvl = 10, map = 2521, x = 65.91, y = 80.57, z = 658.8 },\n\t\t\t{ t = \"turnin\", quest = 93791, title = \"Speak with Belann\", npc = 256507, npcName = \"Belann Windwood\", map = 2521, x = 62.87, y = 77.37, z = 668.5 },\n\t\t\t{ t = \"accept\", quest = 93797, title = \"Boughs in the Wind\", npc = 256507, npcName = \"Belann Windwood\", minLevel = 10, qlvl = 10, pre = { 93791 }, preTitles = { [93791] = \"Speak with Belann\" }, map = 2521, x = 62.87, y = 77.37, z = 668.5 },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"The Windstone Formations\",\n\t\tnote = \"The bough lies on the ground among the Windstone Formations, the wind shrine on the rise west of Fillion's camp, south of {area:16636}. It does not sparkle, so look at the ground by the stones; there are two spots for it.\",\n\t\tonly = { races = { \"Skyborne\" } },\n\t\tgoals = {\n\t\t\t{ t = \"collect\", quest = 93797, title = \"Boughs in the Wind\", item = 262668, itemName = \"Wind-Infused Bough\", count = 1, oi = 1, map = 2521, x = 48.57, y = 67.63, from = \"Wind-Infused Bough\", fromKind = \"object\", fromId = 616860 },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"Back to {npc:256507}\",\n\t\tonly = { races = { \"Skyborne\" } },\n\t\tgoals = {\n\t\t\t{ t = \"turnin\", quest = 93797, title = \"Boughs in the Wind\", npc = 256507, npcName = \"Belann Windwood\", map = 2521, x = 62.87, y = 77.37, z = 668.5, note = \"{npc:256507}: {item:263430}\", rewards = { items = { { item = 263430, itemName = \"Windbough Wand\" } } } },\n\t\t\t{ t = \"note\", text = \"{quest:1861} (the next steps) waits for you with {npc:5497} in {zone:1453}, at about 15.\" },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{npc:328} ({area:87})\",\n\t\tnote = \"At 10 {npc:328}, the {area:87} mage trainer, upstairs in the Lion's Pride Inn, sends you to {npc:5497} in {zone:1453}. Taking it shuts out {quest:1879}, the {area:131} trainer's errand; {quest:1861} and {npc:5144}'s Gizmonitor shut out each other, so you get one staff or orb.\",\n\t\tonly = { races = { \"Human\" } },\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 10 },\n\t\t\t{ t = \"accept\", quest = 1860, title = \"Speak with Jennea\", npc = 328, npcName = \"Zaldimar Wefhellt\", minLevel = 10, qlvl = 10, closedBy = { 1861, 1879, 1880 }, endNpcs = { 5497 }, xp = 420, preTitles = { [1861] = \"Mirror Lake\", [1879] = \"Speak with Bink\", [1880] = \"Mage-tastic Gizmonitor\" }, map = 1429, x = 43.27, y = 66.19, z = 63.9 },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{npc:1228} ({area:131})\",\n\t\tnote = \"At 10 {npc:1228}, the {area:131} mage trainer in the {area:2102}, sends you to {npc:5144} in {zone:1455}. Taking it shuts out {quest:1860}, the {area:87} trainer's errand; {npc:5144}'s Gizmonitor and {npc:5497}'s {quest:1861} shut out each other, so you get one staff or orb. (A Gnome who took {npc:328}'s quest in {area:87} instead follows the {quest:1861} steps; a Human who took this one, the Gizmonitor steps.)\",\n\t\tonly = { races = { \"Gnome\" } },\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 10 },\n\t\t\t{ t = \"accept\", quest = 1879, title = \"Speak with Bink\", npc = 1228, npcName = \"Magis Sparkmantle\", minLevel = 10, qlvl = 10, closedBy = { 1880, 1860, 1861 }, endNpcs = { 5144 }, xp = 85, preTitles = { [1860] = \"Speak with Jennea\", [1861] = \"Mirror Lake\", [1880] = \"Mage-tastic Gizmonitor\" }, map = 1426, x = 47.42, y = 51.97, z = 403.6 },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{npc:5497}\",\n\t\tnote = \"Follow the road north into {zone:1453} and west to the {object:2101}. {npc:5497} stands at the top of the Wizard's Sanctum, the tall violet tower: climb the spiral ramp and step into the portal near the top, which puts you beside her. She hands you {item:7207}. Skyborne mages take {quest:1861} from her when they first reach {zone:1453}, at about 15.\",\n\t\tonly = { races = { \"Human\", \"Gnome\", \"Skyborne\" } },\n\t\twhen = { { k = \"onquest\", neg = true, q = { 1879 } } },\n\t\tgoals = {\n\t\t\t{ t = \"turnin\", quest = 1860, title = \"Speak with Jennea\", npc = 5497, npcName = \"Jennea Cannon\", map = 1453, x = 49.51, y = 85.99, z = 29.7, spotsPacked = \"49.5,86,29.7,15,3\", only = { races = { \"Human\", \"Gnome\" } } },\n\t\t\t{ t = \"accept\", quest = 1861, title = \"Mirror Lake\", npc = 5497, npcName = \"Jennea Cannon\", minLevel = 10, qlvl = 10, closedBy = { 1880 }, endNpcs = { 5497 }, xp = 850, crumbs = { 1860 }, preTitles = { [1860] = \"Speak with Jennea\", [1880] = \"Mage-tastic Gizmonitor\" }, map = 1453, x = 49.5, y = 86.19, z = 29.7, spotsPacked = \"49.5,86,29.7,15,3\" },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"The {quest:1861} waterfall\",\n\t\tnote = \"Leave {zone:1453} by the main gate and head south-west to the waterfall that feeds {quest:1861}. Wade in under the falling water to the rock behind it and use {item:7207} there (a 5 second cast); it fails anywhere else. Level 10 Defias casters stand on the rocks either side of the falls and shoot from range: pull them one at a time or fill the flask from the water.\",\n\t\tonly = { races = { \"Human\", \"Gnome\", \"Skyborne\" } },\n\t\twhen = { { k = \"onquest\", q = { 1861 } } },\n\t\tgoals = {\n\t\t\t{ t = \"use\", quest = 1861, title = \"Mirror Lake\", item = 7207, itemName = \"Jennea's Flask\", oi = 1, map = 1429, x = 28.57, y = 61.39, z = 48.4, f = \"e\", note = \"{item:7207}, under the falls\" },\n\t\t\t{ t = \"collect\", quest = 1861, title = \"Mirror Lake\", item = 7206, itemName = \"Mirror Lake Water Sample\", count = 1, oi = 1, map = 1429, x = 28.57, y = 61.39, z = 48.4, f = \"e\", from = \"Mirror Lake Waterwall\", fromKind = \"object\", fromId = 174794, group = { kind = \"elite\", lvl = 15, near = true, rank = 1 } },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"Back to {npc:5497}\",\n\t\tnote = \"Back up the Wizard's Sanctum and through the portal. The orb is an off-hand for a one-hand weapon; the staff is a two-hander.\",\n\t\tonly = { races = { \"Human\", \"Gnome\", \"Skyborne\" } },\n\t\twhen = { { k = \"onquest\", q = { 1861 } } },\n\t\tgoals = {\n\t\t\t{ t = \"turnin\", quest = 1861, title = \"Mirror Lake\", npc = 5497, npcName = \"Jennea Cannon\", map = 1453, x = 49.51, y = 85.99, z = 29.7, spotsPacked = \"49.5,86,29.7,15,3\", note = \"{npc:5497}: {item:7508} or {item:9513}\", rewards = { choices = { { item = 7508, itemName = \"Ley Orb\" }, { item = 9513, itemName = \"Ley Staff\" } } } },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{npc:5144}\",\n\t\tnote = \"{npc:5144} teaches mages in the {object:32362}, at the back of {zone:1455} past the {object:32386}.\",\n\t\tonly = { races = { \"Human\", \"Gnome\" } },\n\t\twhen = { { k = \"onquest\", q = { 1879 } } },\n\t\tgoals = {\n\t\t\t{ t = \"turnin\", quest = 1879, title = \"Speak with Bink\", npc = 5144, npcName = \"Bink\", map = 1455, x = 26.93, y = 8.28, z = 501.2, spotsPacked = \"26.9,8.3,501.2,15,6\" },\n\t\t\t{ t = \"accept\", quest = 1880, title = \"Mage-tastic Gizmonitor\", npc = 5144, npcName = \"Bink\", minLevel = 10, qlvl = 10, closedBy = { 1861 }, endNpcs = { 5144 }, xp = 850, crumbs = { 1879 }, preTitles = { [1861] = \"Mirror Lake\", [1879] = \"Speak with Bink\" }, map = 1455, x = 26.89, y = 8.38, z = 501.2, spotsPacked = \"26.9,8.3,501.2,15,6\" },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{object:102984}\",\n\t\tnote = \"Head west along the road to {area:133}. Just north of its entrance stand two huts; the toolbox is in the taller, eastern one, the hut with the lift: a small grey box on the ground floor, half under the table beside the lift. Leper Gnomes (level 8) guard the huts: pull them singly. There is only one toolbox and it takes 15 minutes to come back after someone opens it, so wait nearby if it is gone.\",\n\t\tonly = { races = { \"Human\", \"Gnome\" } },\n\t\twhen = { { k = \"onquest\", q = { 1880 } } },\n\t\tgoals = {\n\t\t\t{ t = \"interact\", object = 102984, objName = \"Bink's Toolbox\", map = 1426, x = 27.67, y = 36.37, z = 410.8, f = \"e\" },\n\t\t\t{ t = \"collect\", quest = 1880, title = \"Mage-tastic Gizmonitor\", item = 7226, itemName = \"Mage-tastic Gizmonitor\", count = 1, oi = 1, map = 1426, x = 27.67, y = 36.37, z = 410.8, f = \"e\", from = \"Bink's Toolbox\", fromKind = \"object\", fromId = 102984 },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"Back to {npc:5144}\",\n\t\tonly = { races = { \"Human\", \"Gnome\" } },\n\t\twhen = { { k = \"onquest\", q = { 1880 } } },\n\t\tgoals = {\n\t\t\t{ t = \"turnin\", quest = 1880, title = \"Mage-tastic Gizmonitor\", npc = 5144, npcName = \"Bink\", map = 1455, x = 26.93, y = 8.28, z = 501.2, spotsPacked = \"26.9,8.3,501.2,15,6\", note = \"{npc:5144}: {item:7507} or {item:9514}\", rewards = { choices = { { item = 7507, itemName = \"Arcane Orb\" }, { item = 9514, itemName = \"Arcane Staff\" } } } },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{npc:256507}'s wand (optional)\",\n\t\tnote = \"{npc:256507}'s quest is open to Human and Gnome mages too, if you ever visit {area:16638} on {zone:2521}, the Skyborne home: {npc:252373}, the town's mage trainer, sends you to {npc:256507} next door, who wants a {item:262668} from the ground by the Windstone Formations south of {area:16636}, for the {item:263430}. It does not shut out the staff or the orb.\",\n\t\tonly = { races = { \"Human\", \"Gnome\" } },\n\t\tgoals = {\n\t\t\t{ t = \"accept\", quest = 93791, title = \"Speak with Belann\", npc = 252373, npcName = \"Anathamaas Aetherwind\", minLevel = 10, qlvl = 10, map = 2521, x = 65.91, y = 80.57, z = 658.8, optional = true },\n\t\t\t{ t = \"turnin\", quest = 93791, title = \"Speak with Belann\", npc = 256507, npcName = \"Belann Windwood\", map = 2521, x = 62.87, y = 77.37, z = 668.5 },\n\t\t\t{ t = \"accept\", quest = 93797, title = \"Boughs in the Wind\", npc = 256507, npcName = \"Belann Windwood\", minLevel = 10, qlvl = 10, pre = { 93791 }, preTitles = { [93791] = \"Speak with Belann\" }, map = 2521, x = 62.87, y = 77.37, z = 668.5, optional = true },\n\t\t\t{ t = \"collect\", quest = 93797, title = \"Boughs in the Wind\", item = 262668, itemName = \"Wind-Infused Bough\", count = 1, oi = 1, map = 2521, x = 48.57, y = 67.63, optional = true, from = \"Wind-Infused Bough\", fromKind = \"object\", fromId = 616860 },\n\t\t\t{ t = \"turnin\", quest = 93797, title = \"Boughs in the Wind\", npc = 256507, npcName = \"Belann Windwood\", map = 2521, x = 62.87, y = 77.37, z = 668.5, optional = true, note = \"{npc:256507}: {item:263430}\", rewards = { items = { { item = 263430, itemName = \"Windbough Wand\" } } } },\n\t\t},\n\t},\n}",
		})
	end
	register()
end

