			written = { ["Back to {npc:3663} at {area:413} in western {zone:1440}, across the whole zone."] = "Back to Delgren at Maestra's Post in western Ashenvale, across the whole zone.", ["Back to {npc:5495}"] = "Back to Ursula" },
			stepCount = 9,
			stepsSrc = "return {\n\t{\n\t\ttitle = \"The {object:409289}\",\n\t\tnote = \"Climb to the top of the {area:444} in northern {zone:1439}. The Dark Strand Fanatics around it are easy (level 16-17), but four Dark Strand Voidcallers (level 28-29) stand in the tower on the way to the orb: each calls a voidwalker and casts {spell:686} from range. At 22-25 bring a friend or two, pull them one at a time and step behind a wall so they have to come to you. Loot the {object:409289} at the top: it gives you the {item:209748}; right-click it to start the quest. Keep the orb in your bags until the {object:409311}: three later quests need it.\",\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 22 },\n\t\t\t{ t = \"accept\", quest = 78088, title = \"A Strange Artifact\", object = 409289, objName = \"Strange Orb\", minLevel = 22, qlvl = 30, map = 1439, x = 56.2, y = 26.5, f = \"e\", note = \"{object:409289} atop the {area:444}: right-click the {item:209748} it gives\" },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{npc:3663}\",\n\t\tnote = \"{npc:3663} stands at {area:413} in western {zone:1440}, south of the {zone:1439} road. He sends you to {zone:1453} with the orb.\",\n\t\tgoals = {\n\t\t\t{ t = \"turnin\", quest = 78088, title = \"A Strange Artifact\", npc = 3663, npcName = \"Delgren the Purifier\", map = 1440, x = 26.12, y = 38.7, z = 4.8 },\n\t\t\t{ t = \"accept\", quest = 78089, title = \"Advice From Stormwind\", npc = 3663, npcName = \"Delgren the Purifier\", minLevel = 22, qlvl = 30, pre = { 78088 }, preTitles = { [78088] = \"A Strange Artifact\" }, map = 1440, x = 26.12, y = 38.7, z = 4.8 },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{npc:5492}\",\n\t\tnote = \"{npc:5492} stands in the Cathedral of Light; she sends you to a warlock for a second opinion.\",\n\t\tgoals = {\n\t\t\t{ t = \"turnin\", quest = 78089, title = \"Advice From Stormwind\", npc = 5492, npcName = \"Katherine the Pure\", map = 1453, x = 48.57, y = 49.08, z = 106.6, spotsPacked = \"48.6,49.1,106.6,15,2\" },\n\t\t\t{ t = \"accept\", quest = 78090, title = \"A Second Opinion\", npc = 5492, npcName = \"Katherine the Pure\", minLevel = 22, qlvl = 30, pre = { 78089 }, preTitles = { [78089] = \"Advice From Stormwind\" }, map = 1453, x = 48.47, y = 49.19, z = 106.6, spotsPacked = \"48.6,49.1,106.6,15,2\" },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{npc:5495}\",\n\t\tnote = \"{npc:5495}, the warlock trainer, is in the {object:2101}'s warlock sanctum, down in the {object:2164}'s cellar. She wants 14 {item:209778} to read the orb.\",\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 29 },\n\t\t\t{ t = \"turnin\", quest = 78090, title = \"A Second Opinion\", npc = 5495, npcName = \"Ursula Deline\", map = 1453, x = 39.88, y = 84.19, z = 101.5, spotsPacked = \"39.8,84.3,101.5,15,2\" },\n\t\t\t{ t = \"accept\", quest = 78091, title = \"Earning Your Salt\", npc = 5495, npcName = \"Ursula Deline\", minLevel = 22, qlvl = 30, pre = { 78090 }, preTitles = { [78090] = \"A Second Opinion\" }, map = 1453, x = 39.88, y = 84.19, z = 101.5, spotsPacked = \"39.8,84.3,101.5,15,2\" },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{item:209778}\",\n\t\tnote = \"The Blackrock Summoners, Champions and Trackers (level 22-25, not elite) camp in the north-west of Redridge and drop the {item:209778}; you need 14. Two elite Blackrock Shadowcasters (22-23) stand at the cave mouth at the camp's east end: pull around them. The Blackrock camps east of {area:69} drop the salt too, but their Shadowcasters, Sentries and Hunters are elite (level 21-24), and so is {npc:334} (26): stay in the north-west.\",\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 30 },\n\t\t\t{ t = \"collect\", quest = 78091, title = \"Earning Your Salt\", item = 209778, itemName = \"Summoner's Salt\", count = 14, oi = 1, map = 1433, x = 23.5, y = 12, z = 163.9, spotsPacked = \"25.11,10.81,151.3,76,23,,25;30.79,10.05,156.3,51,6,,25;34,14.6,156.2,40,2,1;37.8,11.9,132.9,40,3,1;38.8,19.6,,40,1,1;55.8,43.2,113.1,40,4,1;68.9,78.8,58.7,40,2,1\", lvl = 23, fromNpcs = { { npc = 4463, npcName = \"Blackrock Summoner\" }, { npc = 435, npcName = \"Blackrock Champion\" } } },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"Back to {npc:5495}\",\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 29 },\n\t\t\t{ t = \"turnin\", quest = 78091, title = \"Earning Your Salt\", npc = 5495, npcName = \"Ursula Deline\", map = 1453, x = 39.78, y = 84.32, z = 101.5, spotsPacked = \"39.8,84.3,101.5,15,2\" },\n\t\t\t{ t = \"accept\", quest = 78092, title = \"It Must Be Destroyed\", npc = 5495, npcName = \"Ursula Deline\", minLevel = 22, qlvl = 30, pre = { 78091 }, preTitles = { [78091] = \"Earning Your Salt\" }, map = 1453, x = 39.88, y = 84.19, z = 101.5, spotsPacked = \"39.8,84.3,101.5,15,2\" },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"Motes of Mannoroth\",\n\t\tnote = \"{area:435} is in south-east {zone:1440}, east of {area:431} (a Horde camp: go round it). The Mannoroc Lashers, Searing Infernals, Felguards and Legion Hounds (level 29-30, not elite) drop the Motes of Mannoroth; you need 12. Below about 27 they are hard alone: come with a second player or later. Felguards knock you down, Lashers cast {spell:686} and {spell:348}, Infernals keep a fire shield up. They respawn in five minutes.\",\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 30 },\n\t\t\t{ t = \"collect\", quest = 78092, title = \"It Must Be Destroyed\", item = 209779, itemName = \"Mote of Mannoroth\", count = 12, oi = 1, map = 1440, x = 81.2, y = 79.9, f = \"e\", spotsPacked = \"81.1,79.9,,40,2;79.3,81.5,183.4,50,16;78,84.1,144.5,40,16;82.1,77,131.3,40,1;85,77.8,115.8,40,2;87.1,79.3,144.5,40,1;89.1,77.4,,67,5;84.5,74.2,,40,2;83.4,70.8,106.5,53,6;81.6,69.1,107.9,67,4;80.7,70.1,105.4,40,1;80.8,65.6,,40,3;83.5,67.6,104.3,40,1;82.7,78.9,,40,2,1\", spread = true, lvl = 30, fromNpcs = { { npc = 11697, npcName = \"Mannoroc Lasher\" }, { npc = 6073, npcName = \"Searing Infernal\" } } },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"The {object:409311}\",\n\t\tnote = \"The {object:409311} stands at the east end of {area:435}. Hand in the motes at the spear with the {item:209748} in your bags: the orb shatters, and the {object:409315} beside it starts the last quest.\",\n\t\tgoals = {\n\t\t\t{ t = \"turnin\", quest = 78092, title = \"It Must Be Destroyed\", object = 409311, objName = \"Spear of Mannoroth\", map = 1440, x = 89.28, y = 77.05 },\n\t\t\t{ t = \"accept\", quest = 78093, title = \"Return to Delgren\", object = 409315, objName = \"Shattered Orb\", minLevel = 22, qlvl = 30, pre = { 78092 }, preTitles = { [78092] = \"It Must Be Destroyed\" }, map = 1440, x = 89.41, y = 77.05, f = \"e\", note = \"from the {object:409315}\" },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{quest:78093}\",\n\t\tnote = \"Back to {npc:3663} at {area:413} in western {zone:1440}, across the whole zone.\",\n\t\tgoals = {\n\t\t\t{ t = \"turnin\", quest = 78093, title = \"Return to Delgren\", npc = 3663, npcName = \"Delgren the Purifier\", map = 1440, x = 26.12, y = 38.7, z = 4.8, note = \"{npc:3663}: {item:277205}\" },\n\t\t},\n\t},\n}",
		})
	end
	register()
end

