			names = { ["area:144"] = "Thelsamar", ["area:1581"] = "Deadmines", ["area:20"] = "Moonbrook", ["area:2257"] = "Deeprun Tram", ["area:236"] = "Shadowfang Keep", ["area:2797"] = "Blackfathom Deeps", ["area:287"] = "Hillsbrad", ["area:414"] = "Zoram Strand", ["area:442"] = "Auberdine", ["item:6776"] = "Tome of Valor", ["item:6895"] = "Jordan's Smithing Hammer", ["item:6953"] = "Verigan's Fist", ["item:6993"] = "Jordan's Refined Ore Shipment", ["item:6994"] = "Whitestone Oak Lumber", ["item:6995"] = "Corrupted Kor Gem", ["item:6996"] = "Jordan's Weapon Notes", ["item:7083"] = "Purified Kor Gem", ["item:9607"] = "Bastion of Stormwind", ["npc:3649"] = "Thundris Windweaver", ["npc:6171"] = "Duthorian Rall", ["npc:6179"] = "Tiza Battleforge", ["npc:6180"] = "Defias Raider", ["npc:6181"] = "Jordan Stilwell", ["npc:6182"] = "Daphne Stilwell", ["npc:6241"] = "Bailor Stonehand", ["npc:641"] = "Goblin Woodcarver", ["object:32362"] = "Mystic Ward", ["object:32386"] = "Hall of Mysteries", ["object:91138"] = "Jordan's Hammer", ["object:92420"] = "Bailor's Ore", ["quest:1649"] = "The Tome of Valor", ["quest:1794"] = "The Tome of Valor", ["spell:122"] = "Frost Nova", ["spell:5502"] = "Sense Undead", ["zone:1421"] = "Silverpine Forest", ["zone:1432"] = "Loch Modan", ["zone:1436"] = "Westfall", ["zone:1437"] = "Wetlands", ["zone:1439"] = "Darkshore", ["zone:1440"] = "Ashenvale", ["zone:1453"] = "Stormwind", ["zone:1455"] = "Ironforge" },
			written = { ["Back to the Cathedral of Light: {npc:6171} gives you the {item:9607} shield and teaches you {spell:5502}."] = "Back to the Cathedral of Light: Duthorian gives you the Bastion of Stormwind shield and teaches you Sense Undead.", ["Back to {npc:3649} in {area:442}: he purifies the gem."] = "Back to Thundris in Auberdine: he purifies the gem.", ["Back to {npc:6241}"] = "Back to Bailor", ["{area:1581} is a group of five under {area:20}; the instance portal is at the bottom of the {area:20} mine. The Goblin Woodcarvers (elite, level 18-19) in the mast room with Sneed drop the lumber every time."] = "The Deadmines is a group of five under Moonbrook; the instance portal is at the bottom of the Moonbrook mine. The Goblin Woodcarvers (elite, level 18-19) in the mast room with Sneed drop the lumber every time.", ["{area:1581}, in the {area:20} mine"] = "The Deadmines, in the Moonbrook mine", ["{npc:6182}'s farmhouse stands on the south-west coast of {zone:1436}, south of {area:20}: take the path that runs south beside the {area:1581}' back exit. When you take her quest, she walks from her orchard to the house and three waves of Defias Raiders (level 17-18) attack: three, then four, then five. Fight close to her so they do not swarm her, and heal her when she drops. You get time to eat and drink between waves, and she heals to full. If you or {npc:6182} die, the quest fails: abandon it and take it again from her (she is back five minutes after dying). Players find it hard alone before about 24."] = "Daphne Stilwell's farmhouse stands on the south-west coast of Westfall, south of Moonbrook: take the path that runs south beside the Deadmines' back exit. When you take her quest, she walks from her orchard to the house and three waves of Defias Raiders (level 17-18) attack: three, then four, then five. Fight close to her so they do not swarm her, and heal her when she drops. You get time to eat and drink between waves, and she heals to full. If you or Daphne die, the quest fails: abandon it and take it again from her (she is back five minutes after dying). Players find it hard alone before about 24.", ["{npc:6241} turns the ore into {item:6993}, the part Jordan wants."] = "Bailor turns the ore into Jordan's Refined Ore Shipment, the part Jordan wants." },
			stepCount = 15,
			stepsSrc = "return {\n\t{\n\t\ttitle = \"{quest:1794} ({zone:1455})\",\n\t\tnote = \"At 20 {npc:6179}, upstairs in the {object:32386} in the {object:32362}, gives you the {item:6776}. Right-click it: it sends you to {npc:6171} in {zone:1453}'s Cathedral of Light. Take the {area:2257} from {zone:1455} to {zone:1453}.\",\n\t\tonly = { races = { \"Dwarf\" } },\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 20 },\n\t\t\t{ t = \"turnin\", quest = 1794, title = \"The Tome of Valor\", npc = 6179, npcName = \"Tiza Battleforge\", minLevel = 20, qlvl = 20, map = 1455, x = 27.33, y = 12.1, z = 524.8, spotsPacked = \"27.3,12.1,524.8,15,2\", direct = true },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{quest:1649}\",\n\t\tnote = \"{npc:6171} stands in the Cathedral of Light. Humans get the {item:6776} from him. Right-click the book to start its quest and hand it straight back to him.\",\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 20 },\n\t\t\t{ t = \"turnin\", quest = 1793, title = \"The Tome of Valor\", npc = 6171, npcName = \"Duthorian Rall\", minLevel = 20, qlvl = 20, map = 1453, x = 50.49, y = 47.44, z = 106.6, spotsPacked = \"50.5,47.4,106.6,15,4\", only = { races = { \"Human\" } }, direct = true },\n\t\t\t{ t = \"accept\", quest = 1649, title = \"The Tome of Valor\", item = 6776, itemName = \"Tome of Valor\", minLevel = 20, qlvl = 20, note = \"Right-click the {item:6776}\" },\n\t\t\t{ t = \"turnin\", quest = 1649, title = \"The Tome of Valor\", npc = 6171, npcName = \"Duthorian Rall\", map = 1453, x = 50.57, y = 47.35, z = 106.6, spotsPacked = \"50.5,47.4,106.6,15,4\" },\n\t\t\t{ t = \"accept\", quest = 1650, title = \"The Tome of Valor\", npc = 6171, npcName = \"Duthorian Rall\", minLevel = 20, qlvl = 23, pre = { 1649 }, preTitles = { [1649] = \"The Tome of Valor\" }, map = 1453, x = 50.57, y = 47.35, z = 106.6, spotsPacked = \"50.5,47.4,106.6,15,4\" },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{npc:6182}\",\n\t\tnote = \"{npc:6182}'s farmhouse stands on the south-west coast of {zone:1436}, south of {area:20}: take the path that runs south beside the {area:1581}' back exit. When you take her quest, she walks from her orchard to the house and three waves of Defias Raiders (level 17-18) attack: three, then four, then five. Fight close to her so they do not swarm her, and heal her when she drops. You get time to eat and drink between waves, and she heals to full. If you or {npc:6182} die, the quest fails: abandon it and take it again from her (she is back five minutes after dying). Players find it hard alone before about 24.\",\n\t\tgoals = {\n\t\t\t{ t = \"turnin\", quest = 1650, title = \"The Tome of Valor\", npc = 6182, npcName = \"Daphne Stilwell\", map = 1436, x = 41.47, y = 88.82, z = 48.6, spotsPacked = \"41.5,88.8,48.6,15,5\" },\n\t\t\t{ t = \"level\", level = 24 },\n\t\t\t{ t = \"accept\", quest = 1651, title = \"The Tome of Valor\", npc = 6182, npcName = \"Daphne Stilwell\", minLevel = 20, qlvl = 25, pre = { 1650 }, preTitles = { [1650] = \"The Tome of Valor\" }, map = 1436, x = 41.5, y = 88.63, z = 48.6, spotsPacked = \"41.5,88.8,48.6,15,5\" },\n\t\t\t{ t = \"complete\", quest = 1651, title = \"The Tome of Valor\", note = \"Protect {npc:6182}: three waves\", objs = { { text = \"Protect Daphne Stilwell\", count = 1 } } },\n\t\t\t{ t = \"turnin\", quest = 1651, title = \"The Tome of Valor\", npc = 6182, npcName = \"Daphne Stilwell\", map = 1436, x = 41.5, y = 88.63, z = 48.6, spotsPacked = \"41.5,88.8,48.6,15,5\" },\n\t\t\t{ t = \"accept\", quest = 1652, title = \"The Tome of Valor\", npc = 6182, npcName = \"Daphne Stilwell\", minLevel = 20, qlvl = 25, pre = { 1651 }, preTitles = { [1651] = \"The Tome of Valor\" }, map = 1436, x = 41.5, y = 88.63, z = 48.6, spotsPacked = \"41.5,88.8,48.6,15,5\" },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{npc:6171}\",\n\t\tnote = \"Back to the Cathedral of Light: {npc:6171} gives you the {item:9607} shield and teaches you {spell:5502}.\",\n\t\tgoals = {\n\t\t\t{ t = \"turnin\", quest = 1652, title = \"The Tome of Valor\", npc = 6171, npcName = \"Duthorian Rall\", map = 1453, x = 50.49, y = 47.44, z = 106.6, spotsPacked = \"50.5,47.4,106.6,15,4\", note = \"{npc:6171}: {item:9607}, {spell:5502}\", rewards = { items = { { item = 9607, itemName = \"Bastion of Stormwind\" } } } },\n\t\t\t{ t = \"accept\", quest = 1653, title = \"The Test of Righteousness\", npc = 6171, npcName = \"Duthorian Rall\", minLevel = 20, qlvl = 21, pre = { 1652 }, preTitles = { [1652] = \"The Tome of Valor\" }, map = 1453, x = 50.57, y = 47.35, z = 106.6, spotsPacked = \"50.5,47.4,106.6,15,4\" },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{npc:6181}\",\n\t\tnote = \"{npc:6181} works outside the gates of {zone:1455}, not inside. He gives you {item:6996}: four parts, in any order. Keep the notes.\",\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 21 },\n\t\t\t{ t = \"turnin\", quest = 1653, title = \"The Test of Righteousness\", npc = 6181, npcName = \"Jordan Stilwell\", map = 1426, x = 52.5, y = 36.84, z = 495.3 },\n\t\t\t{ t = \"accept\", quest = 1654, title = \"The Test of Righteousness\", npc = 6181, npcName = \"Jordan Stilwell\", minLevel = 20, qlvl = 22, pre = { 1653 }, preTitles = { [1653] = \"The Test of Righteousness\" }, map = 1426, x = 52.5, y = 36.84, z = 495.3 },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{npc:6241}\",\n\t\tnote = \"{npc:6241} is downstairs in the house of {area:144} that has a tailoring merchant outside. His quest only opens once you hold Jordan's.\",\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 21 },\n\t\t\t{ t = \"accept\", quest = 1655, title = \"Bailor's Ore Shipment\", npc = 6241, npcName = \"Bailor Stonehand\", minLevel = 20, qlvl = 22, parent = 1654, preTitles = { [1654] = \"The Test of Righteousness\" }, map = 1432, x = 35.96, y = 44.98, z = 322.2 },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{object:92420}\",\n\t\tnote = \"The crate of ore sits outdoors in the middle of the Mo'grosh ogre camp in north-east {zone:1432}, beside a big tree and a broken wagon, between the caves. The camp holds about fifteen Mo'grosh ogres, elite (level 18-19), who knock you down and come back after five minutes: grouping up is encouraged; at 20-22 it needs a group of about three. The crate is back two seconds after each loot, so every paladin in the group gets one.\",\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 21 },\n\t\t\t{ t = \"collect\", quest = 1655, title = \"Bailor's Ore Shipment\", item = 6992, itemName = \"Jordan's Ore Shipment\", count = 1, oi = 1, map = 1432, x = 71.46, y = 21.41, z = 297.9, f = \"e\", spotsPacked = \"71.46,21.41,297.9,0;71.66,21.8,297.9,0\", note = \"{object:92420} crate\", from = \"Bailor's Ore\", fromKind = \"object\", fromId = 92420, group = { kind = \"elite\", lvl = 19, near = true, rank = 1 } },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"Back to {npc:6241}\",\n\t\tnote = \"{npc:6241} turns the ore into {item:6993}, the part Jordan wants.\",\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 21 },\n\t\t\t{ t = \"turnin\", quest = 1655, title = \"Bailor's Ore Shipment\", npc = 6241, npcName = \"Bailor Stonehand\", map = 1432, x = 35.96, y = 44.98, z = 322.2, rewards = { items = { { item = 6993, itemName = \"Jordan's Refined Ore Shipment\" } } }, repeatable = true },\n\t\t\t{ t = \"collect\", quest = 1654, title = \"The Test of Righteousness\", item = 6993, itemName = \"Jordan's Refined Ore Shipment\", count = 1, oi = 2, map = 1432, x = 35.96, y = 44.98, z = 322.2, from = \"Bailor Stonehand\", fromKind = \"npc\", fromFaction = \"A\", fromId = 6241, fromNpcs = { { npc = 6241, npcName = \"Bailor Stonehand\" } } },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{item:6994}\",\n\t\tnote = \"{area:1581} is a group of five under {area:20}; the instance portal is at the bottom of the {area:20} mine. The Goblin Woodcarvers (elite, level 18-19) in the mast room with Sneed drop the lumber every time.\",\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 22 },\n\t\t\t{ t = \"goto\", text = \"{area:1581}, in the {area:20} mine\", map = 1436, x = 42.5, y = 71.7 },\n\t\t\t{ t = \"collect\", quest = 1654, title = \"The Test of Righteousness\", item = 6994, itemName = \"Whitestone Oak Lumber\", count = 1, oi = 1, map = 1436, x = 42.5, y = 71.7, note = \"Goblin Woodcarvers, inside\", group = { kind = \"elite\", lvl = 19, rank = 1 } },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{item:6895}\",\n\t\tnote = \"{area:236} is a dungeon for a group of five in the low to mid 20s, in southern {zone:1421}, Horde land: a long trip for the Alliance, through the {zone:1437}, Arathi and {area:287}. The hammer lies on a crate across from the horses in the stables, early in the dungeon, at the far end of the courtyard before the ramp up; it is back five minutes after someone takes it.\",\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 22 },\n\t\t\t{ t = \"goto\", text = \"{area:236}\", area = 236, map = 1421, x = 44.8, y = 67.8 },\n\t\t\t{ t = \"collect\", quest = 1654, title = \"The Test of Righteousness\", item = 6895, itemName = \"Jordan's Smithing Hammer\", count = 1, oi = 3, map = 1421, x = 44.8, y = 67.8, note = \"{object:91138}, inside\" },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{npc:3649}\",\n\t\tnote = \"{npc:3649} is in {area:442}. Take his quest before you hunt naga: the Kor Gem never drops without it.\",\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 21 },\n\t\t\t{ t = \"accept\", quest = 1442, title = \"Seeking the Kor Gem\", npc = 3649, npcName = \"Thundris Windweaver\", minLevel = 20, qlvl = 22, parent = 1654, preTitles = { [1654] = \"The Test of Righteousness\" }, map = 1439, x = 37.38, y = 40.14, z = 8.3 },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"The north end of the {area:414}\",\n\t\tnote = \"The naga's flooded ruins lie just past the north end of the {area:414}, south of {zone:1439} along the coast. The arrow cannot find its own way down into them, so it leads you to the water's edge first: from there swim north into the ruins.\",\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 22 },\n\t\t\t{ t = \"goto\", text = \"The north end of the {area:414}\", map = 1440, x = 14.6, y = 13.7, f = \"e\" },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"The {item:6995}\",\n\t\tnote = \"The Blackfathom naga in the flooded passages around the {area:2797} entrance, on {zone:1440}'s north-west coast, drop the {item:6995}: Tide Priestesses (level 20-21), Oracles (21-22) and Sea Witches (23-24), one in two. You do not need to enter the instance. All are elite: grouping up is encouraged; players solo them one at a time, with difficulty. They heal themselves, run for help at low health, satyrs stand near some, and the Sea Witches cast {spell:122} up close. Some players report no drop while in a raid group.\",\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 22 },\n\t\t\t{ t = \"collect\", quest = 1442, title = \"Seeking the Kor Gem\", item = 6995, itemName = \"Corrupted Kor Gem\", count = 1, oi = 1, map = 1440, x = 13.55, y = 12.06, z = -9.6, f = \"e\", spotsPacked = \"13.8,9.3,-13.8,80,10;16.2,11.3,,58,5;13.6,12.1,-9.6,15,1,1,21;17.7,11.1,-28.8,15,1,1\", lvl = 22, fromNpcs = { { npc = 4802, npcName = \"Blackfathom Tide Priestess\" }, { npc = 4803, npcName = \"Blackfathom Oracle\" } }, group = { kind = \"elite\", lvl = 22, rank = 1 } },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"The {item:7083}\",\n\t\tnote = \"Back to {npc:3649} in {area:442}: he purifies the gem.\",\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 21 },\n\t\t\t{ t = \"turnin\", quest = 1442, title = \"Seeking the Kor Gem\", npc = 3649, npcName = \"Thundris Windweaver\", map = 1439, x = 37.38, y = 40.14, z = 8.3, rewards = { items = { { item = 7083, itemName = \"Purified Kor Gem\" } } }, repeatable = true },\n\t\t\t{ t = \"collect\", quest = 1654, title = \"The Test of Righteousness\", item = 7083, itemName = \"Purified Kor Gem\", count = 1, oi = 4, map = 1439, x = 37.38, y = 40.14, z = 8.3, from = \"Thundris Windweaver\", fromKind = \"npc\", fromFaction = \"A\", fromId = 3649, fromNpcs = { { npc = 3649, npcName = \"Thundris Windweaver\" } } },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{item:6953}\",\n\t\tnote = \"Bring the four parts to {npc:6181} outside {zone:1455}. Accept his last quest and wait by him while he forges the mace at his anvil.\",\n\t\tgoals = {\n\t\t\t{ t = \"turnin\", quest = 1654, title = \"The Test of Righteousness\", npc = 6181, npcName = \"Jordan Stilwell\", map = 1426, x = 52.5, y = 36.84, z = 495.3 },\n\t\t\t{ t = \"accept\", quest = 1806, title = \"The Test of Righteousness\", npc = 6181, npcName = \"Jordan Stilwell\", minLevel = 20, qlvl = 22, pre = { 1654 }, preTitles = { [1654] = \"The Test of Righteousness\" }, map = 1426, x = 52.5, y = 36.84, z = 495.3 },\n\t\t\t{ t = \"turnin\", quest = 1806, title = \"The Test of Righteousness\", npc = 6181, npcName = \"Jordan Stilwell\", map = 1426, x = 52.5, y = 36.84, z = 495.3, note = \"{item:6953}\", rewards = { items = { { item = 6953, itemName = \"Verigan's Fist\" } } } },\n\t\t},\n\t},\n}",
		})
	end
	register()
end

