			stepCount = 14,
			stepsSrc = "return {\n\t{\n\t\ttitle = \"{quest:94817}: {npc:1226}\",\n\t\tnote = \"At 10, {npc:1226}, the priest trainer inside the {area:2102} in {area:131}, hands you a {quest:94817} letter for {npc:258785} in {zone:1455}. {area:131} is on the road up to the city.\",\n\t\twhen = { { k = \"zone\", name = \"Dun Morogh\", area = 1 }, { k = \"onquest\", neg = true, q = { 94817, 94821, 94822, 94823, 94824, 94825, 94826 } } },\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 10 },\n\t\t\t{ t = \"talk\", npc = 1226, npcName = \"Maxan Anvol\", map = 1426, x = 47.26, y = 52.17, z = 399.7, note = \"{npc:1226}: take his {quest:94817} letter\" },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{quest:94817}: {npc:377}\",\n\t\tnote = \"At 10 in {zone:1429}, {npc:377}, upstairs in the Lion's Pride Inn in {area:87}, hands you a {quest:94817} letter for {npc:258785} in {zone:1455}.\",\n\t\twhen = { { k = \"zone\", name = \"Elwynn Forest\", area = 12 }, { k = \"onquest\", neg = true, q = { 94817, 94821, 94822, 94823, 94824, 94825, 94826 } } },\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 10 },\n\t\t\t{ t = \"talk\", npc = 377, npcName = \"Priestess Josetta\", map = 1429, x = 43.27, y = 65.67, z = 63.9, note = \"{npc:377}: take her {quest:94817} letter\" },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{quest:94817}: {npc:376}\",\n\t\tnote = \"At 10 in {zone:1453}, {npc:376} at the altar of the Cathedral of Light hands you a {quest:94817} letter for {npc:258785} in {zone:1455} (the {area:2257} from the {object:28027}).\",\n\t\twhen = { { k = \"zone\", name = \"Stormwind City\", area = 1519 }, { k = \"onquest\", neg = true, q = { 94817, 94821, 94822, 94823, 94824, 94825, 94826 } } },\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 10 },\n\t\t\t{ t = \"talk\", npc = 376, npcName = \"High Priestess Laurena\", map = 1453, x = 49.55, y = 44.74, z = 109.9, spotsPacked = \"49.5,44.7,109.9,15,4\", note = \"{npc:376}: take her {quest:94817} letter\" },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{quest:94817}: {npc:258785}