			stepCount = 12,
			stepsSrc = "return {\n\t{\n\t\ttitle = \"{quest:2205}\",\n\t\tnote = \"At 10 {npc:917}, the rogue trainer upstairs in the Lion's Pride Inn in {area:87}, gives you a package for {npc:332} in {zone:1453}. Train {spell:921} if you lack it: this chain needs it.\",\n\t\tonly = { races = { \"Human\", \"Skyborne\" } },\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 10 },\n\t\t\t{ t = \"accept\", quest = 2205, title = \"Seek out SI: 7\", npc = 917, npcName = \"Keryn Sylvius\", minLevel = 10, qlvl = 10, map = 1429, x = 43.75, y = 65.92, z = 63.9 },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{npc:332}\",\n\t\tnote = \"Head north to {zone:1453}. Shaw stands upstairs in the SI:7 building in {object:2100} (the quest says the Barracks; it means SI:7).\",\n\t\tonly = { races = { \"Human\", \"Skyborne\" } },\n\t\tgoals = {\n\t\t\t{ t = \"turnin\", quest = 2205, title = \"Seek out SI: 7\", npc = 332, npcName = \"Master Mathias Shaw\", map = 1453, x = 78.28, y = 70.86, z = 109.6, spotsPacked = \"78.3,70.9,109.6,15,4\" },\n\t\t\t{ t = \"accept\", quest = 2206, title = \"Snatch and Grab\", npc = 332, npcName = \"Master Mathias Shaw\", minLevel = 10, qlvl = 10, pre = { 2205 }, preTitles = { [2205] = \"Seek out SI: 7\" }, map = 1453, x = 78.3, y = 71.04, z = 109.6, spotsPacked = \"78.3,70.9,109.6,15,4\" },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{npc:6846}\",\n\t\tnote = \"The {npc:6846} (level 10, a goblin) works in the dock house at {area:797}, on the river at Elwynn's southern edge, south of {area:87}. Stealth in and {spell:921} him from behind: the schedule never drops from his corpse. Do not open with {spell:2070} or a fight: he calls in three waves of bodyguards. Keep away from the fireplaces in the house; they burn you out of stealth. He is back 2 to 5 minutes after a death.\",\n\t\tonly = { races = { \"Human\", \"Skyborne\" } },\n\t\tgoals = {\n\t\t\t{ t = \"collect\", quest = 2206, title = \"Snatch and Grab\", item = 7675, itemName = \"Defias Shipping Schedule\", count = 1, oi = 1, text = \"{spell:921} the {npc:6846} for the {item:7675}\", map = 1429, x = 48.06, y = 86.96, z = 25.5, f = \"e\", from = \"Defias Dockmaster\", fromKind = \"npc\", fromId = 6846, fromNpcs = { { npc = 6846, npcName = \"Defias Dockmaster\" } } },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"Back to Mathias Shaw\",\n\t\tonly = { races = { \"Human\", \"Skyborne\" } },\n\t\tgoals = {\n\t\t\t{ t = \"turnin\", quest = 2206, title = \"Snatch and Grab\", npc = 332, npcName = \"Master Mathias Shaw\", map = 1453, x = 78.28, y = 70.86, z = 109.6, spotsPacked = \"78.3,70.9,109.6,15,4\", note = \"{npc:332}, SI:7\", rewards = { items = { { item = 7298, itemName = \"Blade of Cunning\" } } } },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{quest:2218}\",\n\t\tnote = \"At 10 {npc:1234}, the rogue trainer in the {area:2102} in {area:131}, sends you to {npc:5165} in {zone:1455}.\",\n\t\tonly = { races = { \"Dwarf\", \"Gnome\" } },\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 10 },\n\t\t\t{ t = \"accept\", quest = 2218, title = \"Road to Salvation\", npc = 1234, npcName = \"Hogral Bakkan\", minLevel = 10, qlvl = 10, map = 1426, x = 47.55, y = 52.55, z = 399.2 },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{npc:5165}\",\n\t\tnote = \"{npc:5165} is in the {object:32383}, the rogue quarter in the north of {zone:1455}: go into the building with a shady dealer outside and down the stairs.\",\n\t\tonly = { races = { \"Dwarf\", \"Gnome\" } },\n\t\tgoals = {\n\t\t\t{ t = \"turnin\", quest = 2218, title = \"Road to Salvation\", npc = 5165, npcName = \"Hulfdan Blackbeard\", map = 1455, x = 51.55, y = 14.68, z = 502, spotsPacked = \"51.5,14.7,502,15,2\" },\n\t\t\t{ t = \"accept\", quest = 2238, title = \"Simple Subterfugin'\", npc = 5165, npcName = \"Hulfdan Blackbeard\", minLevel = 10, qlvl = 10, pre = { 2218 }, preTitles = { [2218] = \"Road to Salvation\" }, map = 1455, x = 51.7, y = 14.7, z = 502, spotsPacked = \"51.5,14.7,502,15,2\" },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{npc:6886}\",\n\t\tnote = \"Head west to {area:133}. Beside the road to its entrance stands a wooden spiral tower: {npc:6886} waits stealthed on the top platform, next to a level 10 {npc:1211}, so you only see him up close.\",\n\t\tonly = { races = { \"Dwarf\", \"Gnome\" } },\n\t\tgoals = {\n\t\t\t{ t = \"turnin\", quest = 2238, title = \"Simple Subterfugin'\", npc = 6886, npcName = \"Onin MacHammar\", map = 1426, x = 25.15, y = 44.52, z = 395.9 },\n\t\t\t{ t = \"accept\", quest = 2239, title = \"Onin's Report\", npc = 6886, npcName = \"Onin MacHammar\", minLevel = 10, qlvl = 10, pre = { 2238 }, preTitles = { [2238] = \"Simple Subterfugin'\" }, map = 1426, x = 25.15, y = 44.52, z = 395.9 },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"Back to {npc:5165}\",\n\t\tonly = { races = { \"Dwarf\", \"Gnome\" } },\n\t\tgoals = {\n\t\t\t{ t = \"turnin\", quest = 2239, title = \"Onin's Report\", npc = 5165, npcName = \"Hulfdan Blackbeard\", map = 1455, x = 51.55, y = 14.68, z = 502, spotsPacked = \"51.5,14.7,502,15,2\", note = \"{npc:5165}, {zone:1455}\", rewards = { items = { { item = 7298, itemName = \"Blade of Cunning\" } } } },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{quest:2241}\",\n\t\tnote = \"At 10 {npc:3599}, the rogue trainer in the {area:186} inn, gives you a rose for {npc:4163} in {zone:1457}. If you lose the rose, abandon the quest and take it again.\",\n\t\tonly = { races = { \"NightElf\" } },\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 10 },\n\t\t\t{ t = \"accept\", quest = 2241, title = \"The Apple Falls\", npc = 3599, npcName = \"Jannok Breezesong\", minLevel = 10, qlvl = 10, map = 1438, x = 56.3, y = 60.13, z = 1308.9 },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{npc:4163}\",\n\t\tnote = \"Head west to {zone:1457}. {npc:4163} is below ground in the {area:1658}: the way down is the opening at the foot of the split tree left of the Arch Druid's tree, near the nightsaber trainer. Her map marker shows above ground.\",\n\t\tonly = { races = { \"NightElf\" } },\n\t\tgoals = {\n\t\t\t{ t = \"turnin\", quest = 2241, title = \"The Apple Falls\", npc = 4163, npcName = \"Syurna\", map = 1457, x = 36.68, y = 21.76, z = 1295.1, spotsPacked = \"36.7,21.8,1295.1,15,2\" },\n\t\t\t{ t = \"accept\", quest = 2242, title = \"Destiny Calls\", npc = 4163, npcName = \"Syurna\", minLevel = 10, qlvl = 10, pre = { 2241 }, preTitles = { [2241] = \"The Apple Falls\" }, map = 1457, x = 36.8, y = 21.86, z = 1295.1, spotsPacked = \"36.7,21.8,1295.1,15,2\" },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{npc:6909}\",\n\t\tnote = \"{npc:6909} (level 12 satyr) lives out on a great branch north of the {area:264}: go through the V-shaped gap in the wall north of the glade and out along the branch. Pick his pocket for the journal; killing him does not give it, and a fight brings out three Minions of Sethir. He walks between the main branch and a side branch: wait stealthed at the far end of the main branch and pick him from behind when he comes back. Then {spell:2983} away. He is back 8 1/2 minutes after a death.\",\n\t\tonly = { races = { \"NightElf\" } },\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 12 },\n\t\t\t{ t = \"collect\", quest = 2242, title = \"Destiny Calls\", item = 7737, itemName = \"Sethir's Journal\", count = 1, oi = 1, text = \"Pick Pocket Sethir the Ancient for {item:7737}\", map = 1438, x = 37.11, y = 22.83, z = 1334.6, f = \"e\", from = \"Sethir the Ancient\", fromKind = \"npc\", fromId = 6909, fromNpcs = { { npc = 6909, npcName = \"Sethir the Ancient\" } } },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"Back to {npc:4163}\",\n\t\tonly = { races = { \"NightElf\" } },\n\t\tgoals = {\n\t\t\t{ t = \"turnin\", quest = 2242, title = \"Destiny Calls\", npc = 4163, npcName = \"Syurna\", map = 1457, x = 36.68, y = 21.76, z = 1295.1, spotsPacked = \"36.7,21.8,1295.1,15,2\", note = \"{npc:4163}, {zone:1457}\", rewards = { items = { { item = 7298, itemName = \"Blade of Cunning\" } } } },\n\t\t},\n\t},\n}",
		})
	end
	register()
end

