			written = { ["{npc:4214} stands in the {area:1658}. Then the boat from {area:702} to {area:442}, and the boat from {area:442} to {area:17203}."] = "Erion stands in the Cenarion Enclave. Then the boat from Rut'theran Village to Auberdine, and the boat from Auberdine to Stormwind Harbor.", ["{npc:5165} is in the house with a shady dealer outside, in the {object:32383}, down the stairs. Then fly or take the {area:2257} to {zone:1453}."] = "Hulfdan is in the house with a shady dealer outside, in the Forlorn Cavern, down the stairs. Then fly or take the Deeprun Tram to Stormwind.", ["{npc:6946} stands upstairs in the {quest:2300} building in {object:2100}, behind the rogue trainers. Before you leave: if you lack {spell:1804}, {npc:13283} in the {quest:2300} building teaches it; Lockpicking is the test of the next quest."] = "Renzik stands upstairs in the SI:7 building in Old Town, behind the rogue trainers. Before you leave: if you lack Pick Lock, Lord Tony Romano in the SI:7 building teaches it; Lockpicking is the test of the next quest." },
			stepCount = 9,
			stepsSrc = "return {\n\t{\n\t\ttitle = \"{quest:2300} ({area:87})\",\n\t\tnote = \"At 16 {npc:917}, the rogue trainer upstairs in the Lion's Pride Inn in {area:87}, sends you to {npc:6946} in {zone:1453}. Taking it shuts out the other towns' breadcrumbs.\",\n\t\tonly = { races = { \"Human\", \"Skyborne\" } },\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 16 },\n\t\t\t{ t = \"accept\", quest = 2300, title = \"SI:7\", npc = 917, npcName = \"Keryn Sylvius\", minLevel = 16, qlvl = 16, closedBy = { 2260, 2298 }, endNpcs = { 6946 }, xp = 120, preTitles = { [2260] = \"Erion's Behest\", [2298] = \"Kingly Shakedown\" }, map = 1429, x = 43.75, y = 65.92, z = 63.9 },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{quest:2299} ({area:131})\",\n\t\tnote = \"At 16 {npc:1234} in the {area:2102} in {area:131} sends you to {npc:5165} in {zone:1455}'s {object:32383}.\",\n\t\tonly = { races = { \"Dwarf\", \"Gnome\" } },\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 16 },\n\t\t\t{ t = \"accept\", quest = 2299, title = \"To Hulfdan!\", npc = 1234, npcName = \"Hogral Bakkan\", minLevel = 16, qlvl = 16, closedBy = { 2298, 2259 }, endNpcs = { 5165 }, xp = 120, preTitles = { [2259] = \"Erion Shadewhisper\", [2298] = \"Kingly Shakedown\" }, map = 1426, x = 47.55, y = 52.55, z = 399.2 },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{npc:5165}\",\n\t\tnote = \"{npc:5165} is in the house with a shady dealer outside, in the {object:32383}, down the stairs. Then fly or take the {area:2257} to {zone:1453}.\",\n\t\tonly = { races = { \"Dwarf\", \"Gnome\" } },\n\t\tgoals = {\n\t\t\t{ t = \"turnin\", quest = 2299, title = \"To Hulfdan!\", npc = 5165, npcName = \"Hulfdan Blackbeard\", map = 1455, x = 51.55, y = 14.68, z = 502, spotsPacked = \"51.5,14.7,502,15,2\" },\n\t\t\t{ t = \"accept\", quest = 2298, title = \"Kingly Shakedown\", npc = 5165, npcName = \"Hulfdan Blackbeard\", minLevel = 16, qlvl = 16, closedBy = { 2260, 2300 }, endNpcs = { 6946 }, xp = 120, crumbs = { 2299 }, preTitles = { [2260] = \"Erion's Behest\", [2299] = \"To Hulfdan!\", [2300] = \"SI:7\" }, map = 1455, x = 51.7, y = 14.7, z = 502, spotsPacked = \"51.5,14.7,502,15,2\" },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{quest:2259} ({area:186})\",\n\t\tnote = \"At 16 {npc:3599} in the {area:186} inn sends you to {quest:2259} in {zone:1457}.\",\n\t\tonly = { races = { \"NightElf\" } },\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 16 },\n\t\t\t{ t = \"accept\", quest = 2259, title = \"Erion Shadewhisper\", npc = 3599, npcName = \"Jannok Breezesong\", minLevel = 16, qlvl = 16, closedBy = { 2260, 2299 }, endNpcs = { 4214 }, xp = 120, preTitles = { [2260] = \"Erion's Behest\", [2299] = \"To Hulfdan!\" }, map = 1438, x = 56.3, y = 60.13, z = 1308.9 },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{quest:2259}\",\n\t\tnote = \"{npc:4214} stands in the {area:1658}. Then the boat from {area:702} to {area:442}, and the boat from {area:442} to {area:17203}.\",\n\t\tonly = { races = { \"NightElf\" } },\n\t\tgoals = {\n\t\t\t{ t = \"turnin\", quest = 2259, title = \"Erion Shadewhisper\", npc = 4214, npcName = \"Erion Shadewhisper\", map = 1457, x = 34.56, y = 25.64, z = 1282.6, note = \"{quest:2259}, {zone:1457}\" },\n\t\t\t{ t = \"accept\", quest = 2260, title = \"Erion's Behest\", npc = 4214, npcName = \"Erion Shadewhisper\", minLevel = 16, qlvl = 16, closedBy = { 2298, 2300 }, endNpcs = { 6946 }, xp = 575, crumbs = { 2259 }, preTitles = { [2259] = \"Erion Shadewhisper\", [2298] = \"Kingly Shakedown\", [2300] = \"SI:7\" }, map = 1457, x = 34.56, y = 25.64, z = 1282.6 },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{npc:6946}\",\n\t\tnote = \"{npc:6946} stands upstairs in the {quest:2300} building in {object:2100}, behind the rogue trainers. Before you leave: if you lack {spell:1804}, {npc:13283} in the {quest:2300} building teaches it; Lockpicking is the test of the next quest.\",\n\t\tgoals = {\n\t\t\t{ t = \"turnin\", quest = 2300, title = \"SI:7\", npc = 6946, npcName = \"Renzik \\\"The Shiv\\\"\", map = 1453, x = 78.34, y = 70.97, z = 109.6, only = { races = { \"Human\", \"Skyborne\" } } },\n\t\t\t{ t = \"turnin\", quest = 2298, title = \"Kingly Shakedown\", npc = 6946, npcName = \"Renzik \\\"The Shiv\\\"\", map = 1453, x = 78.34, y = 70.97, z = 109.6, only = { races = { \"Dwarf\", \"Gnome\" } } },\n\t\t\t{ t = \"turnin\", quest = 2260, title = \"Erion's Behest\", npc = 6946, npcName = \"Renzik \\\"The Shiv\\\"\", map = 1453, x = 78.34, y = 70.97, z = 109.6, only = { races = { \"NightElf\" } } },\n\t\t\t{ t = \"accept\", quest = 2281, title = \"Redridge Rendezvous\", npc = 6946, npcName = \"Renzik \\\"The Shiv\\\"\", minLevel = 16, qlvl = 16, map = 1453, x = 78.34, y = 70.97, z = 109.6 },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{npc:6966}\",\n\t\tnote = \"Head east through {zone:1429} into Redridge, or fly to {area:69}. {npc:6966} stands on a crate on one of the {area:69} docks, south of town; he gives you {item:5060} with the job ({npc:3090} in {area:69} sells more). {spell:1804} does not work without the tools in your bags.\",\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 19 },\n\t\t\t{ t = \"turnin\", quest = 2281, title = \"Redridge Rendezvous\", npc = 6966, npcName = \"Lucius\", map = 1433, x = 22.99, y = 52.06, z = 64 },\n\t\t\t{ t = \"accept\", quest = 2282, title = \"Alther's Mill\", npc = 6966, npcName = \"Lucius\", minLevel = 16, qlvl = 20, pre = { 2281 }, preTitles = { [2281] = \"Redridge Rendezvous\" }, map = 1433, x = 22.99, y = 52.06, z = 64 },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{quest:2282}\",\n\t\tnote = \"{quest:2282} stands east of {area:69}, up off the road; Blackrock orcs roam near it. Inside, the Practice Lockboxes come back almost at once: pick them until {object:121264} opens for you (about 25 Lockpicking). Your Lockpicking cap rises 5 per level, so a low character may stall. Some boxes are trapped (a frost trap, for one); the skill still goes up. On Forever level 20 spiders wander near the boxes: clear them first or bring a friend. The lockbox always holds the token and is back two seconds after use. Practise on while it still gives skill: the next class quest needs about 75.\",\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 20 },\n\t\t\t{ t = \"collect\", quest = 2282, title = \"Alther's Mill\", item = 7871, itemName = \"Token of Thievery\", count = 1, oi = 1, map = 1433, x = 46.72, y = 44.77, z = 89.1, spotsPacked = \"46.72,44.77,89.1,0;47.02,44.91,89.1,0\", note = \"{item:7871}: {object:121264}\", from = \"Lucius's Lockbox\", fromKind = \"object\", fromId = 121264 },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"Back to {npc:6966}\",\n\t\tgoals = {\n\t\t\t{ t = \"turnin\", quest = 2282, title = \"Alther's Mill\", npc = 6966, npcName = \"Lucius\", map = 1433, x = 22.99, y = 52.06, z = 64, note = \"{npc:6966}: {item:7907}\", rewards = { items = { { item = 7907, itemName = \"Certificate of Thievery\" } } } },\n\t\t},\n\t},\n}",
		})
	end
	register()
end

