			names = { ["area:97"] = "Alther's Mill", ["item:2928"] = "Dust of Decay", ["item:3371"] = "Empty Vial", ["item:3372"] = "Leaded Vial", ["item:3421"] = "Simple Wildflowers", ["item:4371"] = "Bronze Tube", ["item:6452"] = "Anti-Venom", ["item:7676"] = "Thistle Tea", ["item:7908"] = "Klaven Mortwake's Journal", ["item:7923"] = "Defias Tower Key", ["item:8046"] = "Kearnen's Journal", ["item:8431"] = "Spool of Light Chartreuse Silk Thread", ["item:8432"] = "Eau de Mixilpixil", ["npc:1257"] = "Keldric Boucher", ["npc:1303"] = "Felicia Gump", ["npc:1325"] = "Jasper Fel", ["npc:1326"] = "Sloan McCoy", ["npc:332"] = "Master Mathias Shaw", ["npc:7024"] = "Agent Kearnen", ["npc:7050"] = "Defias Drone", ["npc:7051"] = "Malformed Defias Drone", ["npc:7052"] = "Defias Tower Patroller", ["npc:7053"] = "Klaven Mortwake", ["npc:7207"] = "Doc Mixilpixil", ["object:123214"] = "Duskwood Chest", ["object:2096"] = "Trade District", ["object:2100"] = "Old Town", ["object:2177"] = "The Finest Thread", ["quest:2359"] = "Klaven's Tower", ["quest:2360"] = "Mathias and the Defias", ["quest:2607"] = "The Touch of Zanzil", ["skill:129"] = "First Aid", ["spell:2983"] = "Sprint", ["spell:526"] = "Cure Poison", ["spell:8681"] = "Instant Poison", ["spell:921"] = "Pick Pocket", ["spell:9810"] = "Touch of Zanzil", ["zone:1431"] = "Duskwood", ["zone:1436"] = "Westfall", ["zone:1453"] = "Stormwind" },
			stepCount = 8,
			groupQuests = { { quest = 2359, title = "Klaven's Tower" } },
			stepsSrc = "return {\n\t{\n\t\ttitle = \"{quest:2360}\",\n\t\tnote = \"At 20 {npc:332}, upstairs in the SI:7 building in {object:2100}, sends you to {npc:7024} in {zone:1436}. This chain is how you learn Poisons on Forever, so do not skip it.\",\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 20 },\n\t\t\t{ t = \"accept\", quest = 2360, title = \"Mathias and the Defias\", npc = 332, npcName = \"Master Mathias Shaw\", minLevel = 20, qlvl = 20, map = 1453, x = 78.28, y = 70.86, z = 109.6, spotsPacked = \"78.3,70.9,109.6,15,4\" },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{npc:7024}\",\n\t\tnote = \"Kearnen hides stealthed against the west side of a big tree with two small trees in front of it, just north of {npc:7053}'s Defias tower in the far east of {zone:1436}, by the {zone:1431} border. Read {item:8046} for the tower's layout if you like.\",\n\t\tgoals = {\n\t\t\t{ t = \"turnin\", quest = 2360, title = \"Mathias and the Defias\", npc = 7024, npcName = \"Agent Kearnen\", map = 1436, x = 68.41, y = 70.12, z = 35.4 },\n\t\t\t{ t = \"accept\", quest = 2359, title = \"Klaven's Tower\", npc = 7024, npcName = \"Agent Kearnen\", minLevel = 20, qlvl = 24, pre = { 2360 }, preTitles = { [2360] = \"Mathias and the Defias\" }, map = 1436, x = 68.41, y = 70.12, z = 35.4 },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{quest:2359}, with a group\",\n\t\tnote = \"{npc:7053} on the top floor is a level 26 elite: easier at 24 or with a friend. Get the key first: the {npc:7051} (level 23, the spiky-haired one trailing yellow sparkles) walks a loop around the tower; stealth up and {spell:921} it from behind. Then up the tower past the Defias Tower Patrollers (23) and Sentries (24) to the {object:123214} beside Klaven's desk (Lockpicking about 70-75). Opening it poisons you with the {spell:9810}, which stops your stealth for a while.\",\n\t\twhen = { { k = \"group\", q = 2359 } },\n\t\tgoals = {\n\t\t\t{ t = \"collect\", quest = 2359, title = \"Klaven's Tower\", item = 7923, itemName = \"Defias Tower Key\", count = 1, oi = 2, text = \"{spell:921} the {npc:7051} for the {item:7923}\", map = 1436, x = 69.47, y = 73.99, z = 34, f = \"e\", from = \"Malformed Defias Drone\", fromKind = \"npc\", fromId = 7051, fromNpcs = { { npc = 7051, npcName = \"Malformed Defias Drone\" } } },\n\t\t\t{ t = \"collect\", quest = 2359, title = \"Klaven's Tower\", item = 7908, itemName = \"Klaven Mortwake's Journal\", count = 1, oi = 1, map = 1436, x = 70.4, y = 74, z = 70.4, f = \"e\", note = \"{item:7908}: the {object:123214}, top floor\", from = \"Duskwood Chest\", fromKind = \"object\", fromId = 123214, group = { kind = \"elite\", lvl = 26, near = true, rank = 1 } },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{quest:2359}, solo\",\n\t\tnote = \"Get the key first. The {npc:7051} (level 23, not elite) starts at the tower entrance and walks a loop around the outside; it is the spiky-haired one trailing yellow sparkles. Stealth up and {spell:921} it from behind: it always has the key. It hits hard: if stealth breaks, {spell:2983} away. Watch for the pair of Defias Drones that also patrol. Then sneak up the tower. Defias Tower Patrollers (23) and Sentries (24) guard the floors; an Ambush with a dagger kills them outright if you would rather clear them. {npc:7053}, a level 26 elite, waits on the top floor: Sap him, or bring a friend. The {object:123214} beside his desk needs Lockpicking of about 70-75 (practise on the boxes at {area:97} in Redridge first). A trick: while the Sentries are away, jump from the chair to the lamp to the bookshelf above the chest, step out of stealth and open the chest from there. Opening it poisons you with the {spell:9810}, which stops your stealth for a while and lets the drone see you; that is why the key comes first. Then get out.\",\n\t\twhen = { { k = \"group\", neg = true, q = 2359 } },\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 24 },\n\t\t\t{ t = \"collect\", quest = 2359, title = \"Klaven's Tower\", item = 7923, itemName = \"Defias Tower Key\", count = 1, oi = 2, text = \"{spell:921} the {npc:7051} for the {item:7923}\", map = 1436, x = 69.47, y = 73.99, z = 34, f = \"e\", from = \"Malformed Defias Drone\", fromKind = \"npc\", fromId = 7051, fromNpcs = { { npc = 7051, npcName = \"Malformed Defias Drone\" } } },\n\t\t\t{ t = \"collect\", quest = 2359, title = \"Klaven's Tower\", item = 7908, itemName = \"Klaven Mortwake's Journal\", count = 1, oi = 1, map = 1436, x = 70.4, y = 74, z = 70.4, f = \"e\", note = \"{item:7908}: the {object:123214}, top floor\", from = \"Duskwood Chest\", fromKind = \"object\", fromId = 123214, group = { kind = \"elite\", lvl = 26, near = true, rank = 1 } },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{npc:332}\",\n\t\tnote = \"Head north through Elwynn to {zone:1453}; Mathias Shaw is upstairs in SI:7. He teaches Poisons and gives you the {item:7676} recipe. Poisons are made, not bought: each batch of {spell:8681} takes a {item:2928} and an {item:3371}, which {npc:1325} and {npc:1326} sell in {object:2100} next to SI:7. Buy a stack of each, open Poisons from your spellbook to make them, then use a poison on your weapon.\",\n\t\tgoals = {\n\t\t\t{ t = \"turnin\", quest = 2359, title = \"Klaven's Tower\", npc = 332, npcName = \"Master Mathias Shaw\", map = 1453, x = 78.28, y = 70.86, z = 109.6, spotsPacked = \"78.3,70.9,109.6,15,4\", note = \"{npc:332}: Poisons\", rewards = { items = { { item = 18160, itemName = \"Recipe: Thistle Tea\" } } } },\n\t\t\t{ t = \"accept\", quest = 2607, title = \"The Touch of Zanzil\", npc = 332, npcName = \"Master Mathias Shaw\", minLevel = 20, qlvl = 20, pre = { 2359 }, preTitles = { [2359] = \"Klaven's Tower\" }, map = 1453, x = 78.3, y = 71.04, z = 109.6, spotsPacked = \"78.3,70.9,109.6,15,4\" },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{npc:7207}\",\n\t\tnote = \"{quest:2607} still sits on you. {npc:7207} works in the cellar of the SI:7 building: the stairs down are under the stairs to the upper floor, behind {npc:1325}. Target him and type /lay (nothing after it) to be examined, then wait. If he does nothing, abandon the quest, take it again and wait until he asks you to lie down.\",\n\t\tgoals = {\n\t\t\t{ t = \"turnin\", quest = 2607, title = \"The Touch of Zanzil\", npc = 7207, npcName = \"Doc Mixilpixil\", map = 1453, x = 79.86, y = 69.94, z = 95.1, spotsPacked = \"80,70.1,95.1,15,2\" },\n\t\t\t{ t = \"accept\", quest = 2608, title = \"The Touch of Zanzil\", npc = 7207, npcName = \"Doc Mixilpixil\", minLevel = 20, qlvl = 20, pre = { 2607 }, preTitles = { [2607] = \"The Touch of Zanzil\" }, map = 1453, x = 79.86, y = 69.94, z = 95.1, spotsPacked = \"80,70.1,95.1,15,2\" },\n\t\t\t{ t = \"complete\", quest = 2608, title = \"The Touch of Zanzil\", map = 1453, x = 80.06, y = 69.9, note = \"/lay with the Doc targeted\", objs = { { text = \"Diagnosis Complete\", count = 1 } } },\n\t\t\t{ t = \"turnin\", quest = 2608, title = \"The Touch of Zanzil\", npc = 7207, npcName = \"Doc Mixilpixil\", map = 1453, x = 80.09, y = 70.19, z = 95.1, spotsPacked = \"80,70.1,95.1,15,2\" },\n\t\t\t{ t = \"accept\", quest = 2609, title = \"The Touch of Zanzil\", npc = 7207, npcName = \"Doc Mixilpixil\", minLevel = 20, qlvl = 20, pre = { 2608 }, preTitles = { [2608] = \"The Touch of Zanzil\" }, map = 1453, x = 80.09, y = 70.19, z = 95.1, spotsPacked = \"80,70.1,95.1,15,2\" },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"The cure's ingredients\",\n\t\tnote = \"All four are in {zone:1453}. {item:3421}: Bernard or {npc:1303}'s flower shop by the {object:2096} canal. A {item:3372}: many general goods and alchemy vendors ({npc:1257}, {npc:1325} and others). A {item:4371}: the Auction House in the {object:2096}; the engineering suppliers keep only one and are nearly always sold out, and an engineer can make one. The {item:8431} lies on the floor beside the left end of the counter in {object:2177}, the tailor's shop on the canals; you can only pick it up with this quest. If you skip the cure, an {item:6452} ({skill:129}) or a druid's {spell:526} also clears the {spell:9810}.\",\n\t\tgoals = {\n\t\t\t{ t = \"buy\", item = 3421, itemName = \"Simple Wildflowers\", count = 1, candidates = { { npc = 1302, npcName = \"Bernard Gump\", map = 1453, x = 69.41, y = 71.59, z = 98.9, faction = \"A\" } } },\n\t\t\t{ t = \"buy\", item = 3372, itemName = \"Leaded Vial\", count = 1, candidates = { { npc = 1325, npcName = \"Jasper Fel\", map = 1453, x = 79.98, y = 70.02, z = 102.3, faction = \"A\" }, { npc = 1286, npcName = \"Edna Mullby\", map = 1453, x = 64.8, y = 71.41, z = 95.7, faction = \"A\" }, { npc = 5503, npcName = \"Eldraeith\", map = 1453, x = 55.53, y = 85.16, z = 98.4, faction = \"A\" }, { npc = 14847, npcName = \"Professor Thaddeus Paleo\", map = 1429, x = 41.26, y = 69.95, z = 59, faction = \"AH\" }, { npc = 958, npcName = \"Dawn Brightstar\", map = 1429, x = 64.81, y = 69.3, z = 99.3, faction = \"A\" }, { npc = 844, npcName = \"Antonio Perelli\", map = 1429, x = 78.12, y = 72.96, z = 40, f = \"e\", faction = \"A\" }, { npc = 2481, npcName = \"Bliztik\", map = 1431, x = 17.99, y = 54.42, z = 44.6, faction = \"AH\" }, { npc = 8934, npcName = \"Christopher Hewen\", map = 1436, x = 52.21, y = 52.88, z = 35.3, faction = \"A\" }, { npc = 960, npcName = \"Gunder Thornbush\", map = 1431, x = 73.78, y = 45.13, z = 35, faction = \"A\" }, { npc = 3090, npcName = \"Gerald Crawley\", map = 1433, x = 20, y = 41.14, z = 88.9, faction = \"A\" }, { npc = 5100, npcName = \"Fillius Fizzlespinner\", map = 1455, x = 38.5, y = 73.76, z = 504, faction = \"A\" }, { npc = 5138, npcName = \"Gwina Stonebranch\", map = 1455, x = 55.24, y = 59.27, z = 505.9, faction = \"A\" }, { npc = 5178, npcName = \"Soolie Berryfizz\", map = 1455, x = 66.59, y = 54.85, z = 501.8, faction = \"A\" }, { npc = 5163, npcName = \"Burbik Gearspanner\", map = 1455, x = 46.42, y = 27.06, z = 502.9, faction = \"A\" }, { npc = 8178, npcName = \"Nina Lightbrew\", map = 1419, x = 66.84, y = 18.42, z = 103.2, faction = \"A\" }, { npc = 5169, npcName = \"Tynnus Venomsprout\", map = 1455, x = 52