			why = "The {item:5178} that lets you place air totems, then a weapon of your choice at 40.",
			zone = 1455,
			zoneName = "Ironforge",
			author = "Polestar",
			version = 1,
			group = true,
			names = { ["area:1717"] = "Razorfen Kraul", ["area:2408"] = "Shadowprey Village", ["area:272"] = "Tarren Mill", ["area:320"] = "Refuge Pointe", ["area:321"] = "Hammerfall", ["area:338"] = "Angor Fortress", ["area:484"] = "Freewind Post", ["area:489"] = "Thalanaar", ["area:496"] = "Brackenwall Village", ["area:75"] = "Stonard", ["item:212792"] = "Eye of the Tempest", ["item:268582"] = "Corrupted Totems", ["item:274044"] = "Twisted Fire Totem", ["item:274045"] = "Twisted Earth Totem", ["item:274046"] = "Twisted Water Totem", ["item:274047"] = "Twisted Air Totem", ["item:274463"] = "Tattered Note", ["item:280604"] = "Rage of the Storm", ["item:280605"] = "Tidebringer's Claw", ["item:280607"] = "Lightning's Grasp", ["item:280696"] = "Elementalist's Guard", ["item:5178"] = "Air Totem", ["npc:216474"] = "Ravaging Tempest", ["npc:256028"] = "The Lost One", ["npc:258098"] = "Eldrun Stormbreaker", ["npc:259023"] = "Veyric Thunderhame", ["npc:3560"] = "Healing Ward", ["npc:4421"] = "Charlga Razorflank", ["npc:5879"] = "Fire Nova Totem", ["npc:6176"] = "Bath'rah the Windwatcher", ["quest:94789"] = "Call of Air", ["quest:96264"] = "Elemental Aid", ["spell:10596"] = "Nature Resistance", ["spell:139"] = "Renew", ["spell:8292"] = "Chain Bolt", ["spell:9654"] = "Jumping Lightning", ["zone:1413"] = "Barrens", ["zone:1416"] = "Alterac Mountains", ["zone:1417"] = "Arathi Highlands", ["zone:1418"] = "Badlands", ["zone:1435"] = "Swamp of Sorrows", ["zone:1441"] = "Thousand Needles", ["zone:1443"] = "Desolace", ["zone:1444"] = "Feralas", ["zone:1445"] = "Dustwallow Marsh", ["zone:1455"] = "Ironforge" },
			written = { ["{npc:259023} hands you the {item:268582}. {zone:1441} is far: the boat to Theramore and the road west, or fly to {area:489} on the {zone:1444} border and head east into the canyon. Place the {item:268582} at the steam pools north-west of {area:484} to call the corrupted elementals and then the {npc:216474}; Razormane quilboar join the fight while the ritual runs. A group quest: bring at least one or two friends. The {item:212792} drops about every other kill, and every group member can loot it."] = "Veyric hands you the Corrupted Totems. Thousand Needles is far: the boat to Theramore and the road west, or fly to Thalanaar on the Feralas border and head east into the canyon. Place the Corrupted Totems at the steam pools north-west of Freewind Post to call the corrupted elementals and then the Ravaging Tempest; Razormane quilboar join the fight while the ritual runs. A group quest: bring at least one or two friends. The Eye of the Tempest drops about every other kill, and every group member can loot it.", ["{npc:6176} camps in the ruins in the east of {zone:1416}: from {area:272} follow the river east of town north into the hills. Pick your weapon: {item:280607}, {item:280605} or {item:280604}."] = "Bath'rah camps in the ruins in the east of Alterac Mountains: from Tarren Mill follow the river east of town north into the hills. Pick your weapon: Lightning's Grasp, Tidebringer's Claw or Rage of the Storm.", ["{quest:96264} sends you to {npc:4421}, a level 33 elite at the end of {area:1717}: {npc:259023}'s next quest waits for 32."] = "Elemental Aid sends you to Charlga Razorflank, a level 33 elite at the end of Razorfen Kraul: Veyric's next quest waits for 32." },
			stepCount = 13,
			stepsSrc = "return {\n\t{\n\t\ttitle = \"{npc:258098}\",\n\t\tnote = \"At 30 {npc:258098}, the shaman trainer in {zone:1455}, sends you to {npc:259023} in {zone:1417}. Your level 30 air totems (Grounding, {spell:10596}) need the {item:5178} he gives.\",\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 30 },\n\t\t\t{ t = \"accept\", quest = 94789, title = \"Call of Air\", npc = 258098, npcName = \"Eldrun Stormbreaker\", minLevel = 30, qlvl = 30, map = 1455, x = 47.2, y = 13.55, z = 500.6, spotsPacked = \"47.2,13.6,500.6,15,16\" },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{npc:259023}\",\n\t\tnote = \"{npc:259023} camps in the hills just west of {area:321}, the Horde town in the north-east of Arathi: mind its guards. Fly to {area:320} and head north-east.\",\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 30 },\n\t\t\t{ t = \"turnin\", quest = 94789, title = \"Call of Air\", npc = 259023, npcName = \"Veyric Thunderhame\", map = 1417, x = 59.72, y = 27.59, z = 159.8, note = \"{npc:259023}: your {item:5178}\", rewards = { items = { { item = 5178, itemName = \"Air Totem\" } } } },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{npc:259023}\",\n\t\tnote = \"{quest:96264} sends you to {npc:4421}, a level 33 elite at the end of {area:1717}: {npc:259023}'s next quest waits for 32.\",\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 32 },\n\t\t\t{ t = \"accept\", quest = 96264, title = \"Elemental Aid\", npc = 259023, npcName = \"Veyric Thunderhame\", minLevel = 30, qlvl = 33, pre = { 94789 }, preTitles = { [94789] = \"Call of Air\" }, map = 1417, x = 59.72, y = 27.59, z = 159.8 },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{npc:4421}\",\n\t\tnote = \"{area:1717} is a five-player dungeon at the southern edge of the {zone:1413} (the arrow points at its entrance); {npc:4421} (level 33 elite) is its last boss. She casts {spell:8292}, {spell:139} on her allies and Purity; the {item:274463} drops only from her.\",\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 33 },\n\t\t\t{ t = \"collect\", quest = 96264, title = \"Elemental Aid\", item = 274463, itemName = \"Tattered Note\", count = 1, oi = 1, map = 1413, x = 42.9, y = 90.2, note = \"{item:274463}, from {npc:4421}\", group = { kind = \"elite\", lvl = 33, rank = 1 } },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{npc:259023}\",\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 42 },\n\t\t\t{ t = \"turnin\", quest = 96264, title = \"Elemental Aid\", npc = 259023, npcName = \"Veyric Thunderhame\", map = 1417, x = 59.72, y = 27.59, z = 159.8 },\n\t\t\t{ t = \"accept\", quest = 79358, title = \"Storm, Earth, and Fire\", npc = 259023, npcName = \"Veyric Thunderhame\", minLevel = 30, qlvl = 43, pre = { 96264 }, preTitles = { [96264] = \"Elemental Aid\" }, map = 1417, x = 59.72, y = 27.59, z = 159.8 },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"Twisted Fire Totems\",\n\t\tnote = \"Five Twisted Fire Totems. The Stonevault troggs (Skullthumpers, Bonesnappers and Shamans, level 37-41) south of {area:338} in the {zone:1418} carry them; the Shamans drop Fire Nova Totems and a {npc:3560}, the Bonesnappers run for help when hurt. Respawn about five minutes.\",\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 43 },\n\t\t\t{ t = \"collect\", quest = 79358, title = \"Storm, Earth, and Fire\", item = 274044, itemName = \"Twisted Fire Totem\", count = 5, oi = 3, map = 1418, x = 66.15, y = 23.29, z = 244.3, f = \"e\", spotsPacked = \"66.1,23.4,244.3,57,8;51.1,66.6,241.8,61,9,,42;49.4,70.8,,55,6,,40;12.9,73.3,241.8,40,1\", spread = true, lvl = 37, fromNpcs = { { npc = 2906, npcName = \"Dustbelcher Warrior\" }, { npc = 2893, npcName = \"Stonevault Bonesnapper\" }, { npc = 2907, npcName = \"Dustbelcher Mystic\" }, { npc = 2945, npcName = \"Murdaloc\" } } },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"Twisted Earth Totems\",\n\t\tnote = \"Five Twisted Earth Totems. The Lost Ones (murlocs, level 34-39) north and north-east of {area:75} in the {zone:1435} carry them; most run for help when hurt.\",\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 43 },\n\t\t\t{ t = \"collect\", quest = 79358, title = \"Storm, Earth, and Fire\", item = 274045, itemName = \"Twisted Earth Totem\", count = 5, oi = 2, map = 1435, x = 65.07, y = 21.97, z = 21.8, f = \"e\", spotsPacked = \"65.36,20.43,,53,1,,37;61.78,25.12,,64;53.04,30.33,,97\", from = \"Ongeku\", fromKind = \"npc\", fromId = 5622, fromNpcs = { { npc = 5622, npcName = \"Ongeku\" } } },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"Twisted Water Totems\",\n\t\tnote = \"Five Twisted Water Totems. The Mirefin murlocs (level 35-38) north-east of {area:496} in northern {zone:1445} carry them.\",\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 43 },\n\t\t\t{ t = \"collect\", quest = 79358, title = \"Storm, Earth, and Fire\", item = 274046, itemName = \"Twisted Water Totem\", count = 5, oi = 1, map = 1445, x = 56.54, y = 15.6, f = \"e\", spotsPacked = \"57.7,15.9,6.5,85,9,,37;54.5,15,-6.1,53,5,,37;57.6,10.9,,49,9;58.7,9.1,,50,11;59.4,10.2,,40,7;59.8,7.7,,40,4;63,7.5,3.4,64,18;62.4,18.6,,53,6;64.8,26.7,,40,2;64.5,28.6,,40,2;63.4,27.6,,49,5\", spread = true, lvl = 38, from = \"Mirefin Coastrunner\", fromKind = \"npc\", fromId = 4362, fromNpcs = { { npc = 4362, npcName = \"Mirefin Coastrunner\" }, { npc = 4361, npcName = \"Mirefin Muckdweller\" }, { npc = 4360, npcName = \"Mirefin Warrior\" }, { npc = 4363, npcName = \"Mirefin Oracle\" } } },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"Twisted Air Totems\",\n\t\tnote = \"Five Twisted Air Totems. The Maraudine centaurs (level 36-40) north and north-east of {area:2408} in western {zone:1443} carry them; the Scouts drop one nearly every other kill. Wranglers Net and Disarm, Windchasers heal, Stormers throw {spell:9654}: pull one at a time. Respawn about five minutes.\",\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 43 },\n\t\t\t{ t = \"collect\", quest = 79358, title = \"Storm, Earth, and Fire\", item = 274047, itemName = \"Twisted Air Totem\", count = 5, oi = 4, map = 1443, x = 28.83, y = 59.44, f = \"e\", spotsPacked = \"28.77,60.84,131.1,0;28.88,58.04,119.7,0\", lvl = 40, from = \"Maraudine Marauder\", fromKind = \"npc\", fromId = 4659, fromNpcs = { { npc = 4659, npcName = \"Maraudine Marauder\" } } },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{npc:259023}\",\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 39 },\n\t\t\t{ t = \"turnin\", quest = 79358, title = \"Storm, Earth, and Fire\", npc = 259023, npcName = \"Veyric Thunderhame\", map = 1417, x = 59.72, y = 27.59, z = 159.8 },\n\t\t\t{ t = \"accept\", quest = 96135, title = \"Heed My Call\", npc = 259023, npcName = \"Veyric Thunderhame\", minLevel = 30, qlvl = 40, pre = { 79358 }, closedBy = { 79366 }, endNpcs = { 259023 }, xp = 3150, preTitles = { [79358] = \"Storm, Earth, and Fire\", [79366] = \"Heed My Call\" }, map = 1417, x = 59.72, y = 27.59, z = 159.8 },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"The steam pools\",\n\t\tnote = \"{npc:259023} hands you the {item:268582}. {zone:1441} is far: the boat to Theramore and the road west, or fly to {area:489} on the {zone:1444} border and head east into the canyon. Place the {item:268582} at the steam pools north-west of {area:484} to call the corrupted elementals and then the {npc:216474}; Razormane quilboar join the fight while the ritual runs. A group quest: bring at least one or two friends. The {item:212792} drops about every other kill, and every group member can loot it.\",\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 40 },\n\t\t\t{ t = \"collect\", quest = 96135, title = \"Heed My Call\", item = 212792, itemName = \"Eye of the Tempest\", count = 1, oi = 1, map = 1441, x = 37.36, y = 40.86, f = \"e\", spotsPacked = \"36.79,39.69,,22,2;39,37.8,,37,5;40.6,40.3,,15,2;34.4,43,,76,8;39.2,45,,45,3;41.3,37.4,,26,2,1\", lvl = 40, note = \"{item:212792}, from the {npc:216474}\", from = \"Ravaging Tempest\", fromKind = \"npc\", fromRank = 1, fromId = 216474, fromNpcs = { { npc = 216474, npcName = \"Ravaging Tempest\" } }, group = { kind = \"group\", size = 3 } },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{npc:259023}\",\n\t\tgoals = {\n\t\t\t{ t = \"turnin\", quest = 96135, title = \"Heed My Call\", npc = 259023, npcName = \"Veyric Thunderhame\", map = 1417, x = 59.72, y = 27.59, z = 159.8 },\n\t\t\t{ t = \"accept\", quest = 96016, title = \"The Tempest's Weapons\", npc = 259023, npcName = \"Veyric Thunderhame\", minLevel = 30, qlvl = 40, pre = { 79366, 96135 }, closedBy = { 79442 }, endNpcs = { 6176 }, xp = 3900, preTitles = { [79366] = \"Heed My Call\", [79442] = \"The Tempest's Weapons\", [96135] = \"Heed My Call\" }, map = 1417, x = 59.72, y = 27.59, z = 159.8 },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{npc:6176}\",\n\t\tnote = \"{npc:6176} camps in the ruins in the east of {zone:1416}: from {area:272} follow the river east of town north into the hills. Pick your weapon: {item:280607}, {item:280605} or {item:280604}.\",\n\t\tgoals = {\n\t\t\t{ t = \"turnin\", quest = 96016, title = \"The Tempest's Weapons\", npc = 6176, npcName = \"Bath'rah the Windwatcher\", map = 1416, x = 80.32, y = 66.86, z = 55.4, spotsPacked = \"79.83,64.72,,46,1\", note = \"{npc:6176}: the {item:280696} and your weapon\", rewards = { choices = { { item = 280607, itemName = \"Lightning's Grasp\" }, { item = 280605, itemName = \"Tidebringer's Claw\" }, { item = 280604, itemName = \"Rage of the Storm\" } }, items = { { item = 280696, itemName = \"Elementalist's Guard\" } } } },\n\t\t},\n\t},\n}",
