do
	local function register()
		Polestar.RegisterGuide({
			id = "forever/class/shaman/call-of-earth-alliance",
			pack = "guides",
			title = "{quest:94373} (Alliance)",
			faction = "Alliance",
			classes = { "SHAMAN" },
			minLevel = 4,
			maxLevel = 5,
			category = "Class",
			folder = "Shaman",
			keywords = { "Earth Totem", "Stoneskin Totem", "Earth Sapta", "Call of Earth", "Archaic Rune", "Teo Hammerstorm", "Sten Stoutarm", "Eldrun Stormbreaker", "Ingrid Dunwald", "Spirit Stone", "Minor Manifestation of Earth", "Iceclaw Bear Pendant", "Frostmane", "Rough Quartz", "Coldridge Valley", "Anvilmar", "Shaman", "class quest", "totem" },
			collects = { 5175 },
			reward = { { item = 5175, itemName = "Earth Totem" }, { spell = 8071, spellName = "Stoneskin Totem" } },
			why = "Your {item:5175}: without it no earth totem can be cast. {spell:8071} comes with it at level 4.",
			zone = 1426,
			zoneName = "Dun Morogh",
			author = "Polestar",
			version = 1,
			names = { ["area:131"] = "Kharanos", ["area:132"] = "Coldridge Valley", ["area:77"] = "Anvilmar", ["item:264356"] = "Iceclaw Bear Pendant", ["item:5175"] = "Earth Totem", ["item:6635"] = "Earth Sapta", ["item:6656"] = "Rough Quartz", ["npc:257446"] = "Teo Hammerstorm", ["npc:258098"] = "Eldrun Stormbreaker", ["npc:258113"] = "Ingrid Dunwald", ["npc:5891"] = "Minor Manifestation of Earth", ["npc:658"] = "Sten Stoutarm", ["npc:706"] = "Frostmane Troll Whelp", ["npc:946"] = "Frostmane Novice", ["quest:179"] = "Dwarven Outfitters", ["quest:94373"] = "Call of Earth", ["quest:94472"] = "Earth Sapta", ["quest:98581"] = "Archaic Rune", ["spell:116"] = "Frostbolt", ["spell:8071"] = "Stoneskin Totem", ["zone:1455"] = "Ironforge" },
			stepCount = 7,
			stepsSrc = "return {\n\t{\n\t\ttitle = \"{quest:98581}\",\n\t\tnote = \"Teo's {quest:94373} needs the {quest:98581} handed in first: {npc:658}, where you entered {area:132}, gives it to Dwarf shamans after his {quest:179}. Bring it up the road to {npc:257446} inside {area:77}.\",\n\t\twhen = { { k = \"turnedin\", neg = true, q = 98581 } },\n\t\tgoals = {\n\t\t\t{ t = \"accept\", quest = 98581, title = \"Archaic Rune\", npc = 658, npcName = \"Sten Stoutarm\", minLevel = 1, qlvl = 1, pre = { 179 }, preTitles = { [179] = \"Dwarven Outfitters\" }, map = 1426, x = 29.84, y = 71.25, z = 383.7 },\n\t\t\t{ t = \"turnin\", quest = 98581, title = \"Archaic Rune\", npc = 257446, npcName = \"Teo Hammerstorm\", map = 1426, x = 28.75, y = 66.22, z = 399 },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{npc:257446}\",\n\t\tnote = \"{npc:257446} trains shamans inside {area:77}, the hall at the south end of {area:132}. The quest opens at level 4. Never took it and now 10 or more? {npc:258098} in {zone:1455} or {npc:258113} in {area:131} gives you {quest:94373}, a pointer back to Teo: take it for the experience on the way.\",\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 4 },\n\t\t\t{ t = \"accept\", quest = 94373, title = \"Call of Earth\", npc = 257446, npcName = \"Teo Hammerstorm\", minLevel = 4, qlvl = 4, pre = { 98581 }, preTitles = { [98581] = \"Archaic Rune\" }, map = 1426, x = 28.75, y = 66.22, z = 399 },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"Iceclaw Bear Pendants\",\n\t\tnote = \"The Frostmane Troll Whelps (level 3-4) hold the snowy slopes west and south-west of {area:77}, and the Frostmane Novices (level 3-4, they throw Frostbolts from range) camp south of it. Both carry the pendants; they respawn in about three minutes.\",\n\t\tgoals = {\n\t\t\t{ t = \"collect\", quest = 94373, title = \"Call of Earth\", item = 264356, itemName = \"Iceclaw Bear Pendant\", count = 2, oi = 1, map = 1426, x = 27.7, y = 78.82, z = 415.8, f = \"e\", spotsPacked = \"26.7,79.4,386,57,11;28.6,80.5,383,60,15;29,82.5,389.9,55,6;30.2,80.4,372.9,53,11;22.8,79.5,386.7,55,9;20.9,76.5,386.4,54,9\", spread = true, lvl = 4, from = \"Frostmane Troll Whelp\", fromKind = \"npc\", fromAlso = \"Frostmane Novice\", fromId = 706, fromAlsoId = 946, fromNpcs = { { npc = 706, npcName = \"Frostmane Troll Whelp\" }, { npc = 946, npcName = \"Frostmane Novice\" } } },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{npc:257446}\",\n\t\tnote = \"Back to Teo inside {area:77}. He hands you the {item:6635}: do not drink it yet.\",\n\t\tgoals = {\n\t\t\t{ t = \"turnin\", quest = 94373, title = \"Call of Earth\", npc = 257446, npcName = \"Teo Hammerstorm\", map = 1426, x = 28.75, y = 66.22, z = 399 },\n\t\t\t{ t = \"accept\", quest = 94374, title = \"Call of Earth\", npc = 257446, npcName = \"Teo Hammerstorm\", minLevel = 4, qlvl = 4, pre = { 94373 }, preTitles = { [94373] = \"Call of Earth\" }, map = 1426, x = 28.75, y = 66.22, z = 399 },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"Lost the {quest:94472}?\",\n\t\tnote = \"Only if the {quest:94472} is gone from your bags (drunk away from the stone, or sold): Teo gives you another.\",\n\t\twhen = { { k = \"onquest\", q = { 94374 } }, { k = \"has\", neg = true, n = 1, item = 6635 } },\n\t\tgoals = {\n\t\t\t{ t = \"turnin\", quest = 94472, title = \"Earth Sapta\", npc = 257446, npcName = \"Teo Hammerstorm\", minLevel = 4, qlvl = 4, pre = { 94373 }, map = 1426, x = 28.75, y = 66.22, z = 399, note = \"{npc:257446}: a new {quest:94472}\", direct = true },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"The Spirit Stone\",\n\t\tnote = \"The Spirit Stone stands on a snowy ridge north-west of {area:77}. The trail is easy to miss: it climbs the hill from the valley floor; at the small camp near the top turn left and the stone comes into view. Stand beside it, drink the {item:6635} and speak to the {npc:5891} before it fades.\",\n\t\tgoals = {\n\t\t\t{ t = \"use\", item = 6635, itemName = \"Earth Sapta\", map = 1426, x = 24.8, y = 61.8, f = \"e\", note = \"{item:6635}, beside the Spirit Stone\" },\n\t\t\t{ t = \"turnin\", quest = 94374, title = \"Call of Earth\", npc = 5891, npcName = \"Minor Manifestation of Earth\", map = 1426, x = 24.8, y = 61.8, z = 500.9, f = \"e\" },\n\t\t\t{ t = \"accept\", quest = 94375, title = \"Call of Earth\", npc = 5891, npcName = \"Minor Manifestation of Earth\", minLevel = 4, qlvl = 4, pre = { 94374 }, preTitles = { [94374] = \"Call of Earth\" }, map = 1426, x = 24.8, y = 61.8, z = 500.9, f = \"e\", note = \"it hands you the {item:6656}: keep it\" },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{npc:257446}\",\n\t\tnote = \"Bring the {item:6656} back to Teo inside {area:77}. Keep the {item:5175} in your bags for good: every earth totem needs it.\",\n\t\tgoals = {\n\t\t\t{ t = \"turnin\", quest = 94375, title = \"Call of Earth\", npc = 257446, npcName = \"Teo Hammerstorm\", map = 1426, x = 28.75, y = 66.22, z = 399, note = \"{npc:257446}: {spell:8071} and your {item:5175}\", rewards = { items = { { item = 5175, itemName = \"Earth Totem\" } } } },\n\t\t\t{ t = \"train\", class = true, zone = 1426, note = \"the level 4 shaman spells\", candidates = { { npc = 257446, npcName = \"Teo Hammerstorm\", map = 1426, x = 28.75, y = 66.22, z = 399, faction = \"A\", classes = { \"SHAMAN\" } }, { npc = 258113, npcName = \"Ingrid Dunwald\", map = 1426, x = 47.49, y = 51.95, z = 403.6, faction = \"A\", classes = { \"SHAMAN\" } }, { npc = 258098, npcName = \"Eldrun Stormbreaker\", map = 1455, x = 47.23, y = 13.71, z = 500.6, faction = \"A\", classes = { \"SHAMAN\" } } } },\n\t\t},\n\t},\n}",
		})
	end
	register()
end

