			names = { ["area:131"] = "Kharanos", ["area:144"] = "Thelsamar", ["area:149"] = "Silver Stream Mine", ["area:806"] = "South Gate Outpost", ["area:923"] = "Stonesplinter Valley", ["item:263412"] = "Totem of Charged Flames", ["item:277329"] = "Torch of Eternal Flame", ["item:5026"] = "Fire Tar", ["item:5176"] = "Fire Totem", ["item:6636"] = "Fire Sapta", ["item:6652"] = "Reagent Pouch", ["item:6653"] = "Torch of the Dormant Flame", ["item:6655"] = "Glowing Ember", ["npc:1166"] = "Stonesplinter Seer", ["npc:1174"] = "Tunnel Rat Geomancer", ["npc:1959"] = "Mountaineer Barleybrew", ["npc:257597"] = "Bruegs Kindleborn", ["npc:257808"] = "Braldir Ashmantle", ["npc:258098"] = "Eldrun Stormbreaker", ["npc:258113"] = "Ingrid Dunwald", ["npc:5893"] = "Minor Manifestation of Fire", ["object:61934"] = "Brazier of the Dormant Flame", ["quest:94449"] = "Call of Fire", ["quest:94473"] = "Fire Sapta", ["spell:1245113"] = "Lightning Bolts", ["spell:134"] = "Fire Shield", ["spell:2136"] = "Fire Blast", ["spell:3599"] = "Searing Totem", ["spell:8017"] = "Rockbiter Weapon", ["spell:8042"] = "Earth Shock", ["zone:1432"] = "Loch Modan", ["zone:1455"] = "Ironforge" },
			written = { ["Back through the South Gate tunnel and up the trail to {npc:257597}' cave. Keep the {item:5176} in your bags for good: every fire totem needs it."] = "Back through the South Gate tunnel and up the trail to Bruegs' cave. Keep the Fire Totem in your bags for good: every fire totem needs it.", ["Back up the trail to {npc:257808}. He makes the {item:6636} from the tar and the pouch: keep it with the torch."] = "Back up the trail to Braldir. He makes the Fire Sapta from the tar and the pouch: keep it with the torch.", ["Climb on past {npc:257808} to the peak. Drink the {item:6636} beside the rock statue there to see the {npc:5893} (level 12): it waits until you strike, but grows stronger the longer it is left, and it is immune to fire. Open at once with {spell:8017} and {spell:8042}. Its {item:6655} drops every time."] = "Climb on past Braldir to the peak. Drink the Fire Sapta beside the rock statue there to see the Minor Manifestation of Fire (level 12): it waits until you strike, but grows stronger the longer it is left, and it is immune to fire. Open at once with Rockbiter Weapon and Earth Shock. Its Glowing Ember drops every time.", ["Follow the road east to the tunnel towards {area:806}. Out of the first tunnel, keep left past {npc:1959} and the tower: a slim trail, hard to see but shown on the minimap, winds up the mountain to {npc:257597}' cave above the farm. He hands you the {item:6653}: keep it until the end of the chain."] = "Follow the road east to the tunnel towards South Gate Outpost. Out of the first tunnel, keep left past Mountaineer Barleybrew and the tower: a slim trail, hard to see but shown on the minimap, winds up the mountain to Bruegs' cave above the farm. He hands you the Torch of the Dormant Flame: keep it until the end of the chain.", ["From {npc:257597}' ledge you can drop carefully down the mountain into {zone:1432}, or walk back through the tunnel. {npc:257808} keeps the shrine on the peak just south of {area:144}: a hidden trail along a cliff ledge, marked by stone totems, climbs to it from the road north of the peak."] = "From Bruegs' ledge you can drop carefully down the mountain into Loch Modan, or walk back through the tunnel. Braldir Ashmantle keeps the shrine on the peak just south of Thelsamar: a hidden trail along a cliff ledge, marked by stone totems, climbs to it from the road north of the peak.", ["Only if the {quest:94473} is gone from your bags: {npc:257808} gives you another."] = "Only if the Fire Sapta is gone from your bags: Braldir gives you another." },
			stepCount = 10,
			stepsSrc = "return {\n\t{\n\t\ttitle = \"{quest:94449}\",\n\t\tnote = \"At 10 {npc:258113}, the shaman trainer in {area:131}, or {npc:258098}, the shaman trainer in {zone:1455}, sends you to {npc:257597}.\",\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 10 },\n\t\t\t{ t = \"accept\", quest = 94449, title = \"Call of Fire\", npc = 258113, npcName = \"Ingrid Dunwald\", minLevel = 10, qlvl = 10, map = 1426, x = 47.49, y = 51.95, z = 403.6, note = \"{npc:258113}, {area:131}; or {npc:258098}, {zone:1455}\" },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{npc:257597}\",\n\t\tnote = \"Follow the road east to the tunnel towards {area:806}. Out of the first tunnel, keep left past {npc:1959} and the tower: a slim trail, hard to see but shown on the minimap, winds up the mountain to {npc:257597}' cave above the farm. He hands you the {item:6653}: keep it until the end of the chain.\",\n\t\tgoals = {\n\t\t\t{ t = \"turnin\", quest = 94449, title = \"Call of Fire\", npc = 257597, npcName = \"Bruegs Kindleborn\", map = 1426, x = 87.56, y = 43.67, z = 484.3 },\n\t\t\t{ t = \"accept\", quest = 94465, title = \"Call of Fire\", npc = 257597, npcName = \"Bruegs Kindleborn\", minLevel = 10, qlvl = 11, map = 1426, x = 87.56, y = 43.67, z = 484.3 },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{npc:257808}\",\n\t\tnote = \"From {npc:257597}' ledge you can drop carefully down the mountain into {zone:1432}, or walk back through the tunnel. {npc:257808} keeps the shrine on the peak just south of {area:144}: a hidden trail along a cliff ledge, marked by stone totems, climbs to it from the road north of the peak.\",\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 13 },\n\t\t\t{ t = \"turnin\", quest = 94465, title = \"Call of Fire\", npc = 257808, npcName = \"Braldir Ashmantle\", map = 1432, x = 32.12, y = 66.01, z = 456, spotsPacked = \"32.1,66,456,15,2\" },\n\t\t\t{ t = \"accept\", quest = 94466, title = \"Call of Fire\", npc = 257808, npcName = \"Braldir Ashmantle\", minLevel = 10, qlvl = 14, pre = { 94465 }, preTitles = { [94465] = \"Call of Fire\" }, map = 1432, x = 32.21, y = 65.89, z = 456, spotsPacked = \"32.1,66,456,15,2\" },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{item:6652}\",\n\t\tnote = \"The Stonesplinter Seers (level 13-14) stand among the troggs of {area:923} in the south of the loch, and in the trogg camps north-east of {area:144}. They throw {spell:1245113} from 40 yards and run for help when hurt: pull one at a time. Respawn about five minutes.\",\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 14 },\n\t\t\t{ t = \"collect\", quest = 94466, title = \"Call of Fire\", item = 6652, itemName = \"Reagent Pouch\", count = 1, oi = 2, map = 1432, x = 36.75, y = 77.75, z = 378.1, f = \"e\", spotsPacked = \"36.7,78.7,,40,2;35.4,82.7,397.2,48,7;34.7,88.4,,66,10;28.6,85.3,,48,7;29.22,80.97,383.1,32,2;49.2,29.1,299.4,43,5;50.6,24,303.9,40,4;48,21.2,306.6,42,6\", spread = true, lvl = 14, from = \"Stonesplinter Seer\", fromKind = \"npc\", fromId = 1166, fromNpcs = { { npc = 1166, npcName = \"Stonesplinter Seer\" } } },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{item:5026}\",\n\t\tnote = \"The Tunnel Rat Geomancers (level 12-13) work only inside the {area:149} at the north end of the loch, past {area:144}. They cast {spell:2136} behind a {spell:134} and run for help at low health.\",\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 14 },\n\t\t\t{ t = \"collect\", quest = 94466, title = \"Call of Fire\", item = 5026, itemName = \"Fire Tar\", count = 1, oi = 1, map = 1432, x = 35.55, y = 27.92, f = \"e\", spotsPacked = \"35.8,23.3,,49,9;35.6,27.9,,15,1,1\", lvl = 13, from = \"Tunnel Rat Geomancer\", fromKind = \"npc\", fromId = 1174, fromNpcs = { { npc = 1174, npcName = \"Tunnel Rat Geomancer\" } } },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{npc:257808}\",\n\t\tnote = \"Back up the trail to {npc:257808}. He makes the {item:6636} from the tar and the pouch: keep it with the torch.\",\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 13 },\n\t\t\t{ t = \"turnin\", quest = 94466, title = \"Call of Fire\", npc = 257808, npcName = \"Braldir Ashmantle\", map = 1432, x = 32.21, y = 65.89, z = 456, spotsPacked = \"32.1,66,456,15,2\" },\n\t\t\t{ t = \"accept\", quest = 94467, title = \"Call of Fire\", npc = 257808, npcName = \"Braldir Ashmantle\", minLevel = 10, qlvl = 14, pre = { 94466 }, preTitles = { [94466] = \"Call of Fire\" }, map = 1432, x = 32.21, y = 65.89, z = 456, spotsPacked = \"32.1,66,456,15,2\" },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"Lost the {quest:94473}?\",\n\t\tnote = \"Only if the {quest:94473} is gone from your bags: {npc:257808} gives you another.\",\n\t\twhen = { { k = \"onquest\", q = { 94467 } }, { k = \"has\", neg = true, n = 1, item = 6636 } },\n\t\tgoals = {\n\t\t\t{ t = \"turnin\", quest = 94473, title = \"Fire Sapta\", npc = 257808, npcName = \"Braldir Ashmantle\", minLevel = 10, qlvl = 13, pre = { 94466 }, map = 1432, x = 32.21, y = 65.89, z = 456, spotsPacked = \"32.1,66,456,15,2\", note = \"{npc:257808}: a new {quest:94473}\", direct = true },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"The Shrine of Eternal Flame\",\n\t\tnote = \"Climb on past {npc:257808} to the peak. Drink the {item:6636} beside the rock statue there to see the {npc:5893} (level 12): it waits until you strike, but grows stronger the longer it is left, and it is immune to fire. Open at once with {spell:8017} and {spell:8042}. Its {item:6655} drops every time.\",\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 14 },\n\t\t\t{ t = \"use\", quest = 94467, title = \"Call of Fire\", item = 6636, itemName = \"Fire Sapta\", oi = 1, map = 1432, x = 31.9, y = 64.5, f = \"e\", note = \"{item:6636}, beside the statue\" },\n\t\t\t{ t = \"collect\", quest = 94467, title = \"Call of Fire\", item = 6655, itemName = \"Glowing Ember\", count = 1, oi = 1, map = 1432, x = 31.96, y = 64.42, f = \"e\", note = \"{item:6655}: {npc:5893}\", from = \"Minor Manifestation of Fire\", fromKind = \"npc\", fromId = 5893, fromNpcs = { { npc = 5893, npcName = \"Minor Manifestation of Fire\" } } },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"The {object:61934}\",\n\t\tnote = \"Click the {object:61934} atop the shrine with the torch in your bags to place the ember, then click it again for the next quest: the lit {item:277329}.\",\n\t\tgoals = {\n\t\t\t{ t = \"turnin\", quest = 94467, title = \"Call of Fire\", object = 61934, objName = \"Brazier of the Dormant Flame\", map = 1432, x = 31.79, y = 64.64 },\n\t\t\t{ t = \"accept\", quest = 94468, title = \"Call of Fire\", object = 61934, objName = \"Brazier of the Dormant Flame\", minLevel = 10, qlvl = 14, pre = { 94467 }, preTitles = { [94467] = \"Call of Fire\" }, map = 1432, x = 31.79, y = 64.64 },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{npc:257597}\",\n\t\tnote = \"Back through the South Gate tunnel and up the trail to {npc:257597}' cave. Keep the {item:5176} in your bags for good: every fire totem needs it.\",\n\t\tgoals = {\n\t\t\t{ t = \"turnin\", quest = 94468, title = \"Call of Fire\", npc = 257597, npcName = \"Bruegs Kindleborn\", map = 1426, x = 87.56, y = 43.67, z = 484.3, note = \"{npc:257597}: {spell:3599}, your {item:5176} and the {item:263412}\", rewards = { items = { { item = 5176, itemName = \"Fire Totem\" }, { item = 263412, itemName = \"Totem of Charged Flames\" } } } },\n\t\t\t{ t = \"train\", class = true, zone = 1426, candidates = { { npc = 258098, npcName = \"Eldrun Stormbreaker\", map = 1455, x = 47.23, y = 13.71, z = 500.6, faction = \"A\", classes = { \"SHAMAN\" } }, { npc = 258113, npcName = \"Ingrid Dunwald\", map = 1426, x = 47.49, y = 51.95, z = 403.6, faction = \"A\", classes = { \"SHAMAN\" } }, { npc = 257446, npcName = \"Teo Hammerstorm\", map = 1426, x = 28.75, y = 66.22, z = 399, faction = \"A\", classes = { \"SHAMAN\" } } } },\n\t\t},\n\t},\n}",
		})
	end
	register()
end

