			author = "Polestar",
			version = 1,
			names = { ["area:108"] = "Sentinel Hill", ["area:144"] = "Thelsamar", ["area:146"] = "Stonewrought Dam", ["area:150"] = "Menethil Harbor", ["area:20"] = "Moonbrook", ["area:271"] = "Southshore", ["area:415"] = "Astranaar", ["area:442"] = "Auberdine", ["area:68"] = "Lake Everstill", ["area:69"] = "Lakeshire", ["area:71"] = "Stonewatch Falls", ["area:836"] = "Dun Algaz", ["area:919"] = "Stendel's Pond", ["item:265732"] = "Unfilled Brown Waterskin", ["item:265747"] = "Unfilled Red Waterskin", ["item:265772"] = "Unfilled Blue Waterskin", ["item:5177"] = "Water Totem", ["item:6637"] = "Water Sapta", ["item:7810"] = "Vial of Purest Water", ["item:7811"] = "Remaining Drops of Purest Water", ["item:7813"] = "Shard of Water", ["npc:258043"] = "Norric Lochthane", ["npc:258098"] = "Eldrun Stormbreaker", ["npc:258203"] = "Hervdana Saegrund", ["npc:544"] = "Murloc Nightcrawler", ["npc:5894"] = "Corrupt Minor Manifestation of Water", ["npc:5895"] = "Minor Manifestation of Water", ["object:147516"] = "Dark Iron", ["object:32362"] = "Mystic Ward", ["object:619896"] = "Forgotten Shrine", ["quest:94494"] = "Call of Water", ["quest:94616"] = "Water Sapta", ["spell:122"] = "Frost Nova", ["spell:5394"] = "Healing Stream Totem", ["spell:8056"] = "Frost Shock", ["zone:1432"] = "Loch Modan", ["zone:1436"] = "Westfall", ["zone:1437"] = "Wetlands", ["zone:1439"] = "Darkshore", ["zone:1440"] = "Ashenvale", ["zone:1455"] = "Ironforge" },
			written = { ["Back to {npc:258043} by {area:146} with the {item:7810}. He hands you the {item:6637} and the {item:7811}: keep both for {zone:1436}."] = "Back to Norric by Stonewrought Dam with the Vial of Purest Water. He hands you the Water Sapta and the Remaining Drops of Purest Water: keep both for Westfall.", ["Back to {npc:258043} with the {item:7813}. Keep the {item:5177} in your bags for good: every water totem needs it."] = "Back to Norric with the Shard of Water. Keep the Water Totem in your bags for good: every water totem needs it.", ["Fill the {item:265732} at the bottom of the waterfalls below {npc:258203}'s cave, where the fresh water meets the brackish. {object:147516} dwarves roam near the falls."] = "Fill the Unfilled Brown Waterskin at the bottom of the waterfalls below Hervdana's cave, where the fresh water meets the brackish. Dark Iron dwarves roam near the falls.", ["Fly to {area:108} and head south to {area:20}: {area:919} and the {object:619896} lie just north of it. Drink the {item:6637} by the shrine to see the {npc:5894} (level 22, {spell:8056} and {spell:122}; one spawn, back three minutes after a kill), defeat it for its bracers (always dropped), then place them and the {item:7811} on the {object:619896} (this, not {npc:258043}, ends the quest). Click the shrine again: the {npc:5895} rises beside it; speak to it before you walk off (if it is gone, abandon and take the quest again at the shrine). It gives you the {item:7813}."] = "Fly to Sentinel Hill and head south to Moonbrook: Stendel's Pond and the Forgotten Shrine lie just north of it. Drink the Water Sapta by the shrine to see the Corrupt Minor Manifestation of Water (level 22, Frost Shock and Frost Nova; one spawn, back three minutes after a kill), defeat it for its bracers (always dropped), then place them and the Remaining Drops of Purest Water on the Forgotten Shrine (this, not Norric, ends the quest). Click the shrine again: the Minor Manifestation of Water rises beside it; speak to it before you walk off (if it is gone, abandon and take the quest again at the shrine). It gives you the Shard of Water.", ["Only if the {quest:94616} is gone from your bags: {npc:258043} gives you another before you leave for {zone:1436}."] = "Only if the Water Sapta is gone from your bags: Norric gives you another before you leave for Westfall.", ["the {item:7810}, for {npc:258043}"] = "the Vial of Purest Water, for Norric", ["{area:71} pour out of {area:68} at the east end of Redridge (fly from {zone:1455} to {area:69}). Fill the {item:265747} at their foot, where the Murloc Nightcrawlers gather; pull the murlocs off the spot first. If the skin vanishes without counting, abandon the quest and take it again from {npc:258203} for a new one."] = "Stonewatch Falls pour out of Lake Everstill at the east end of Redridge (fly from Ironforge to Lakeshire). Fill the Unfilled Red Waterskin at their foot, where the Murloc Nightcrawlers gather; pull the murlocs off the spot first. If the skin vanishes without counting, abandon the quest and take it again from Hervdana for a new one.", ["{npc:258043}'s burrow hut stands on the north-western shore of the loch, below {area:146}, north of {area:144}."] = "Norric's burrow hut stands on the north-western shore of the loch, below Stonewrought Dam, north of Thelsamar.", ["{npc:258203}'s family lives in a cave beneath the southern falls of the {zone:1437}, east of {area:836}: not in a town. Through the Algaz tunnel north of {zone:1432}, then east off the road."] = "Hervdana's family lives in a cave beneath the southern falls of the Wetlands, east of Dun Algaz: not in a town. Through the Algaz tunnel north of Loch Modan, then east off the road." },
			stepCount = 13,
			stepsSrc = "return {\n\t{\n\t\ttitle = \"{npc:258098}\",\n\t\tnote = \"At 20 {npc:258098}, the shaman trainer in {zone:1455}'s {object:32362}, sends you to {npc:258043} in {zone:1432}.\",\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 20 },\n\t\t\t{ t = \"accept\", quest = 94494, title = \"Call of Water\", npc = 258098, npcName = \"Eldrun Stormbreaker\", minLevel = 20, qlvl = 20, map = 1455, x = 47.2, y = 13.55, z = 500.6, spotsPacked = \"47.2,13.6,500.6,15,16\" },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{npc:258043}\",\n\t\tnote = \"{npc:258043}'s burrow hut stands on the north-western shore of the loch, below {area:146}, north of {area:144}.\",\n\t\tgoals = {\n\t\t\t{ t = \"turnin\", quest = 94494, title = \"Call of Water\", npc = 258043, npcName = \"Norric Lochthane\", map = 1432, x = 41.8, y = 19.05, spotsPacked = \"41.8,19,,15,2\" },\n\t\t\t{ t = \"accept\", quest = 94495, title = \"Call of Water\", npc = 258043, npcName = \"Norric Lochthane\", minLevel = 20, qlvl = 22, pre = { 94494 }, preTitles = { [94494] = \"Call of Water\" }, map = 1432, x = 41.91, y = 19.17, spotsPacked = \"41.8,19,,15,2\" },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{npc:258203}\",\n\t\tnote = \"{npc:258203}'s family lives in a cave beneath the southern falls of the {zone:1437}, east of {area:836}: not in a town. Through the Algaz tunnel north of {zone:1432}, then east off the road.\",\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 21 },\n\t\t\t{ t = \"turnin\", quest = 94495, title = \"Call of Water\", npc = 258203, npcName = \"Hervdana Saegrund\", map = 1437, x = 65.7, y = 76.39, z = 28.3 },\n\t\t\t{ t = \"accept\", quest = 94497, title = \"Call of Water\", npc = 258203, npcName = \"Hervdana Saegrund\", minLevel = 20, qlvl = 22, pre = { 94495 }, preTitles = { [94495] = \"Call of Water\" }, map = 1437, x = 65.7, y = 76.39, z = 28.3 },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"The brown waterskin\",\n\t\tnote = \"Fill the {item:265732} at the bottom of the waterfalls below {npc:258203}'s cave, where the fresh water meets the brackish. {object:147516} dwarves roam near the falls.\",\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 22 },\n\t\t\t{ t = \"collect\", quest = 94497, title = \"Call of Water\", item = 265734, itemName = \"Full Brown Waterskin\", count = 1, oi = 1, map = 1437, x = 65.8, y = 76.5, f = \"e\", spotsPacked = \"64.95,74.91,,15\" },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{npc:258203}\",\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 21 },\n\t\t\t{ t = \"turnin\", quest = 94497, title = \"Call of Water\", npc = 258203, npcName = \"Hervdana Saegrund\", map = 1437, x = 65.7, y = 76.39, z = 28.3 },\n\t\t\t{ t = \"accept\", quest = 94499, title = \"Call of Water\", npc = 258203, npcName = \"Hervdana Saegrund\", minLevel = 20, qlvl = 22, pre = { 94497 }, preTitles = { [94497] = \"Call of Water\" }, map = 1437, x = 65.7, y = 76.39, z = 28.3 },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"The red waterskin\",\n\t\tnote = \"{area:71} pour out of {area:68} at the east end of Redridge (fly from {zone:1455} to {area:69}). Fill the {item:265747} at their foot, where the Murloc Nightcrawlers gather; pull the murlocs off the spot first. If the skin vanishes without counting, abandon the quest and take it again from {npc:258203} for a new one.\",\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 22 },\n\t\t\t{ t = \"collect\", quest = 94499, title = \"Call of Water\", item = 265748, itemName = \"Full Red Waterskin\", count = 1, oi = 1, map = 1433, x = 71.9, y = 60.3, f = \"e\", spotsPacked = \"74.97,60.7,,85\" },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{npc:258203}\",\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 22 },\n\t\t\t{ t = \"turnin\", quest = 94499, title = \"Call of Water\", npc = 258203, npcName = \"Hervdana Saegrund\", map = 1437, x = 65.7, y = 76.39, z = 28.3 },\n\t\t\t{ t = \"accept\", quest = 94500, title = \"Call of Water\", npc = 258203, npcName = \"Hervdana Saegrund\", minLevel = 20, qlvl = 23, pre = { 94499 }, preTitles = { [94499] = \"Call of Water\" }, map = 1437, x = 65.7, y = 76.39, z = 28.3 },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"The blue waterskin\",\n\t\tnote = \"Take the boat from {area:150} to {area:442} (it stops in {area:271} on the way), then fly or walk south through {zone:1439} to {area:415} in {zone:1440}. Fill the {item:265772} in the lake around the town, then the boat back to Menethil.\",\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 22 },\n\t\t\t{ t = \"collect\", quest = 94500, title = \"Call of Water\", item = 265773, itemName = \"Full Blue Waterskin\", count = 1, oi = 1, map = 1440, x = 34.5, y = 48, f = \"e\", spotsPacked = \"34.48,47.8,,21\" },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{npc:258203}\",\n\t\tgoals = {\n\t\t\t{ t = \"turnin\", quest = 94500, title = \"Call of Water\", npc = 258203, npcName = \"Hervdana Saegrund\", map = 1437, x = 65.7, y = 76.39, z = 28.3 },\n\t\t\t{ t = \"accept\", quest = 94501, title = \"Call of Water\", npc = 258203, npcName = \"Hervdana Saegrund\", minLevel = 20, qlvl = 23, pre = { 94500 }, preTitles = { [94500] = \"Call of Water\" }, map = 1437, x = 65.7, y = 76.39, z = 28.3, note = \"the {item:7810}, for {npc:258043}\" },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{npc:258043}\",\n\t\tnote = \"Back to {npc:258043} by {area:146} with the {item:7810}. He hands you the {item:6637} and the {item:7811}: keep both for {zone:1436}.\",\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 22 },\n\t\t\t{ t = \"turnin\", quest = 94501, title = \"Call of Water\", npc = 258043, npcName = \"Norric Lochthane\", map = 1432, x = 41.8, y = 19.05, spotsPacked = \"41.8,19,,15,2\", note = \"{npc:258043}: your {item:6637}\", rewards = { items = { { item = 6637, itemName = \"Water Sapta\" } } } },\n\t\t\t{ t = \"accept\", quest = 94502, title = \"Call of Water\", npc = 258043, npcName = \"Norric Lochthane\", minLevel = 20, qlvl = 23, pre = { 94501 }, preTitles = { [94501] = \"Call of Water\" }, map = 1432, x = 41.91, y = 19.17, spotsPacked = \"41.8,19,,15,2\" },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"Lost the {quest:94616}?\",\n\t\tnote = \"Only if the {quest:94616} is gone from your bags: {npc:258043} gives you another before you leave for {zone:1436}.\",\n\t\twhen = { { k = \"onquest\", q = { 94502 } }, { k = \"has\", neg = true, n = 1, item = 6637 } },\n\t\tgoals = {\n\t\t\t{ t = \"accept\", quest = 94616, title = \"Water Sapta\", npc = 258043, npcName = \"Norric Lochthane\", minLevel = 20, qlvl = 20, pre = { 94501 }, preTitles = { [94501] = \"Call of Water\" }, map = 1432, x = 41.91, y = 19.17, spotsPacked = \"41.8,19,,15,2\" },\n\t\t\t{ t = \"turnin\", quest = 94616, title = \"Water Sapta\", npc = 258043, npcName = \"Norric Lochthane\", map = 1432, x = 41.91, y = 19.17, spotsPacked = \"41.8,19,,15,2\", note = \"{npc:258043}: a new {quest:94616}\", repeatable = true },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{area:919}\",\n\t\tnote = \"Fly to {area:108} and head south to {area:20}: {area:919} and the {object:619896} lie just north of it. Drink the {item:6637} by the shrine to see the {npc:5894} (level 22, {spell:8056} and {spell:122}; one spawn, back three minutes after a kill), defeat it for its bracers (always dropped), then place them and the {item:7811} on the {object:619896} (this, not {npc:258043}, ends the quest). Click the shrine again: the {npc:5895} rises beside it; speak to it before you walk off (if it is gone, abandon and take the quest again at the shrine). It gives you the {item:7813}.\",\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 23 },\n\t\t\t{ t = \"use\", quest = 94502, title = \"Call of Water\", item = 6637, itemName = \"Water Sapta\", oi = 1, map = 1436, x = 45.6, y = 59.9, f = \"e\" },\n\t\t\t{ t = \"collect\", quest = 94502, title = \"Call of Water\", item = 7812, itemName = \"Corrupt Manifestation's Bracers\", count = 1, oi = 1, map = 1436, x = 45.6, y = 59.9, f = \"e\", spotsPacked = \"45.77,60,,31\", from = \"Corrupt Minor Manifestation of Water\", fromKind = \"npc\", fromId = 5894 },\n\t\t\t{ t = \"turnin\", quest = 94502, title = \"Call of Water\", object = 619896, objName = \"Forgotten Shrine\", map = 1436, x = 45.46, y = 59.98 },\n\t\t\t{ t = \"accept\", quest = 94503, title = \"Call of Water\", object = 619896, objName = \"Forgotten Shrine\", minLevel = 20, qlvl = 23, pre = { 94502 }, preTitles = { [94502] = \"Call of Water\" }, map = 1436, x = 45.46, y = 59.98 },\n\t\t\t{ t = \"turnin\", quest = 94503, title = \"Call of Water\", npc = 5895, npcName = \"Minor Manifestation of Water\", map = 1436, x = 46.4, y = 59.2, z = 30.8, f = \"e\", note = \"{npc:5895}, beside the shrine\" },\n\t\t\t{ t = \"accept\", quest = 94505, title = \"Call of Water\", npc = 5895, npcName = \"Minor Manifestation of Water\", minLevel = 20, qlvl = 23, pre = { 94503 }, preTitles = { [94503] = \"Call of Water\" }, map = 1436, x = 46.4, y = 59.2, z = 30.8, f = \"e\" },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{npc:258043}\",\n\t\tnote = \"Back to {npc:258043} with the {item:7813}. Keep the {item:5177} in your bags for good: every water totem needs it.\",\n\t\tgoals = {\n\t\t\t{ t = \"turnin\", quest = 94505, title = \"Call of Water\", npc = 258043, npcName = \"Norric Lochthane\", map = 1432, x = 41.8, y = 19.05, spotsPacked = \"41.8,19,,15,2\", note = \"{npc:258043}: {spell:5394} and your {item:5177}\", rewards = { items = { { item = 5177, itemName = \"Water Totem\" } } } },\n\t\t},\n\t},\n}",
		})
	end
	register()
end

