			zoneName = "Stormwind City",
			author = "Polestar",
			version = 1,
			names = { ["area:1098"] = "Manor Mistmantle", ["area:146"] = "Stonewrought Dam", ["area:42"] = "Darkshire", ["area:836"] = "Dun Algaz", ["item:2788"] = "Black Claw Stout", ["item:3556"] = "Dread Mage Hat", ["npc:1270"] = "Fetid Corpse", ["npc:1435"] = "Zardeth of the Black Claw", ["npc:1439"] = "Lord Baurles K. Wishock", ["npc:1733"] = "Zggi", ["npc:315"] = "Stalvan Mistmantle", ["object:147516"] = "Dark Iron", ["object:2084"] = "Musquash Root", ["object:2101"] = "Mage Quarter", ["object:2117"] = "Stormwind Keep", ["object:2164"] = "Slaughtered Lamb", ["object:321"] = "Tear of Tilloa", ["quest:335"] = "A Noble Brew", ["quest:397"] = "You Have Served Us Well", ["zone:1431"] = "Duskwood", ["zone:1437"] = "Wetlands" },
			stepCount = 5,
			stepsSrc = "return {\n\t{\n\t\ttitle = \"{npc:1435}\",\n\t\tnote = \"At 25 {npc:1435}, in the cellar of the {object:2164} in the {object:2101} (beside the warlock trainers), wants two ingredients for a brew. Do it when your leveling takes you to {zone:1431} and the {zone:1437}.\",\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 29 },\n\t\t\t{ t = \"accept\", quest = 335, title = \"A Noble Brew\", npc = 1435, npcName = \"Zardeth of the Black Claw\", minLevel = 25, qlvl = 30, map = 1453, x = 40.01, y = 85.2, z = 101.6, spotsPacked = \"40,85.2,101.6,15,2\" },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{object:321}\",\n\t\tnote = \"{area:1098} stands in the north-east of {zone:1431}, north of {area:42}. The {object:321} is a small white flower low in the grass of the fenced garden beside Stalvan's house: hard to see, so sweep the garden with your mouse. Fetid Corpses (level 29) wander the grounds and come quickly: at 25, send your voidwalker at the nearest one, grab the flower and leave. {npc:315} (32) is inside the house; leave him alone.\",\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 29 },\n\t\t\t{ t = \"collect\", quest = 335, title = \"A Noble Brew\", item = 2779, itemName = \"Tear of Tilloa\", count = 1, oi = 1, map = 1431, x = 78.35, y = 35.95, z = 35.4, f = \"e\", spotsPacked = \"78.3,35.9,35.4,15,3\", from = \"Tear of Tilloa\", fromKind = \"object\", fromId = 321, group = { kind = \"elite\", lvl = 60, near = true, rank = 1 } },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{object:2084}\",\n\t\tnote = \"The root grows at the water's edge in the pool below the small falls east of {area:836}, beside the {object:147516} cave below the {area:146}: a tall, spiky wooden root, not at the foot of the dam itself.\",\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 30 },\n\t\t\t{ t = \"collect\", quest = 335, title = \"A Noble Brew\", item = 2784, itemName = \"Musquash Root\", count = 1, oi = 2, map = 1437, x = 64.66, y = 75.22, z = 8.4, f = \"e\", from = \"Musquash Root\", fromKind = \"object\", fromId = 2084, group = { kind = \"elite\", lvl = 32, near = true, rank = 1 } },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{quest:335}\",\n\t\tnote = \"Back to Zardeth. He brews the {item:2788} and gives it to you for {npc:1439} in the Hall of Petitioners, the first hall on the right inside {object:2117}.\",\n\t\tgoals = {\n\t\t\t{ t = \"turnin\", quest = 335, title = \"A Noble Brew\", npc = 1435, npcName = \"Zardeth of the Black Claw\", map = 1453, x = 40.01, y = 85.2, z = 101.6, spotsPacked = \"40,85.2,101.6,15,2\" },\n\t\t\t{ t = \"accept\", quest = 336, title = \"A Noble Brew\", npc = 1435, npcName = \"Zardeth of the Black Claw\", minLevel = 25, qlvl = 30, pre = { 335 }, preTitles = { [335] = \"A Noble Brew\" }, map = 1453, x = 39.94, y = 85.34, z = 101.6, spotsPacked = \"40,85.2,101.6,15,2\" },\n\t\t\t{ t = \"turnin\", quest = 336, title = \"A Noble Brew\", npc = 1439, npcName = \"Lord Baurles K. Wishock\", map = 1453, x = 77.75, y = 48.71, z = 108.6, note = \"{npc:1439}, {object:2117}\" },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{quest:397}\",\n\t\tnote = \"Back to Zardeth once more: he offers warlocks a reward, which his imp {npc:1733}, standing beside him, hands over.\",\n\t\tgoals = {\n\t\t\t{ t = \"accept\", quest = 397, title = \"You Have Served Us Well\", npc = 1435, npcName = \"Zardeth of the Black Claw\", minLevel = 25, qlvl = 30, pre = { 336 }, preTitles = { [336] = \"A Noble Brew\" }, map = 1453, x = 40.08, y = 85.06, z = 101.6, spotsPacked = \"40,85.2,101.6,15,2\" },\n\t\t\t{ t = \"turnin\", quest = 397, title = \"You Have Served Us Well\", npc = 1733, npcName = \"Zggi\", map = 1453, x = 40.06, y = 85.21, z = 101.6, note = \"{npc:1733}: {item:3556}\" },\n\t\t},\n\t},\n}",
		})
	end
	register()
end

-- Source: forever/class/warlock/felhunter-alliance.guide
do
	local function register()
		Polestar.RegisterGuide({
			id = "forever/class/warlock/felhunter-alliance",
			pack = "guides",
			title = "Felhunter (Alliance)",
			faction = "Alliance",
			classes = { "WARLOCK" },
			minLevel = 30,
			maxLevel = 33,
			category = "Class",
			folder = "Warlock",
			keywords = { "Summon Felhunter", "Tome of the Cabal", "Seeking Strahad", "Strahad Farsan", "Krom Stoutarm", "Moldy Tome", "Tattered Manuscript", "Damaged Chest", "Rod of Channeling", "Reconstructed Tome", "Dragonmaw Bonewarder", "Dragonmaw Shadowwarder", "Angerfang Encampment", "The Binding", "Box of Souls", "Warlock", "class pet" },
			reward = { { spell = 691, spellName = "Summon Felhunter" }, { item = 22244, itemName = "Box of Souls" } },
			why = "The felhunter, the demon to bring against spellcasters, and a {item:22244} for your shards.",
			zone = 1413,
			zoneName = "The Barrens",
			author = "Polestar",
			version = 1,
			names = { ["area:1036"] = "Angerfang Encampment", ["area:150"] = "Menethil Harbor", ["area:271"] = "Southshore", ["area:287"] = "Hillsbrad", ["area:35"] = "Booty Bay", ["area:392"] = "Ratchet", ["area:484"] = "Freewind Post", ["area:836"] = "Dun Algaz", ["item:22244"] = "Box of Souls", ["item:6931"] = "Moldy Tome", ["item:6997"] = "Tattered Manuscript", ["item:7006"] = "Reconstructed Tome", ["npc:6120"] = "Lago Blackwrench", ["npc:6122"] = "Gakin the Darkbinder", ["npc:6251"] = "Strahad Farsan", ["npc:6266"] = "Menara Voidrender", ["npc:6294"] = "Krom Stoutarm", ["object:2101"] = "Mage Quarter", ["object:2164"] = "Slaughtered Lamb", ["object:32356"] = "Hall of Explorers", ["object:32383"] = "Forlorn Cavern", ["object:92423"] = "Damaged Chest", ["quest:1758"] = "Tome of the Cabal", ["quest:1795"] = "The Binding", ["quest:1798"] = "Seeking Strahad", ["quest:1802"] = "Tome of the Cabal", ["quest:1804"] = "Tome of the Cabal", ["spell:691"] = "Summon Felhunter", ["zone:1413"] = "Barrens", ["zone:1441"] = "Thousand Needles", ["zone:1453"] = "Stormwind", ["zone:1455"] = "Ironforge" },
			written = { ["Back to {npc:6251} in {area:392}. When you accept, he draws the summoning circle and his acolytes channel a greater circle over it: wait inside the tower until both are done. Then use the {quest:1804} on the circle. The felhunter (level 30, not elite) silences and eats mana, and it vanishes after two minutes: have your voidwalker out, open with your damage over time at once and let the voidwalker tank. If you die or it wins, abandon {quest:1795} and take it again from {npc:6251}. Keep the tome: {npc:6251} takes it back."] = "Back to Strahad in Ratchet. When you accept, he draws the summoning circle and his acolytes channel a greater circle over it: wait inside the tower until both are done. Then use the Tome of the Cabal on the circle. The felhunter (level 30, not elite) silences and eats mana, and it vanishes after two minutes: have your voidwalker out, open with your damage over time at once and let the voidwalker tank. If you die or it wins, abandon The Binding and take it again from Strahad. Keep the tome: Strahad takes it back.", ["Back to {npc:6294}"] = "Back to Krom", ["{npc:6294} pieces the tome together and gives you the {item:7006}: keep it, {npc:6251} takes it with the rods."] = "Krom pieces the tome together and gives you the Reconstructed Tome: keep it, Strahad takes it with the rods." },
			stepCount = 9,
			stepsSrc = "return {\n\t{\n\t\ttitle = \"{quest:1798} ({zone:1453})\",\n\t\tnote = \"At 30 {npc:6122}, in the cellar of the {object:2164} in the {object:2101}, sends you to {npc:6251} in {area:392}.\",\n\t\tonly = { races = { \"Human\" } },\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 30 },\n\t\t\t{ t = \"accept\", quest = 1798, title = \"Seeking Strahad\", npc = 6122, npcName = \"Gakin the Darkbinder\", minLevel = 30, qlvl = 30, closedBy = { 1758 }, endNpcs = { 6251 }, xp = 600, preTitles = { [1758] = \"Tome of the Cabal\" }, map = 1453, x = 39.2, y = 85.34, z = 101.5, spotsPacked = \"39.2,85.3,101.5,15,3\" },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{quest:1798} ({zone:1455})\",\n\t\tnote = \"At 30 {npc:6120}, in the {object:32383}, sends you to {npc:6251} in {area:392}.\",\n\t\tonly = { races = { \"Gnome\" } },\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 30 },\n\t\t\t{ t = \"accept\", quest = 1798, title = \"Seeking Strahad\", npc = 6120, npcName = \"Lago Blackwrench\", minLevel = 30, qlvl = 30, closedBy = { 1758 }, endNpcs = { 6251 }, xp = 600, preTitles = { [1758] = \"Tome of the Cabal\" }, map = 1455, x = 47.82, y = 9.69, z = 501.5, spotsPacked = \"47.8,9.7,501.5,15,3\" },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{npc:6251}\",\n\t\tnote = \"{area:392} is a neutral goblin port on the {zone:1413} coast: the boat from {area:35} docks there. {npc:6251} stands on the hill above the town, behind the engineers' hut, by his little tower; {npc:6266} and two acolytes are with him. He sends you to {npc:6294} in {zone:1455}.\",\n\t\tgoals = {\n\t\t\t{ t = \"turnin\", quest = 1798, title = \"Seeking Strahad\", npc = 6251, npcName = \"Strahad Farsan\", map = 1413, x = 62.58, y = 35.31, z = 40.5 },\n\t\t\t{ t = \"accept\", quest = 1758, title = \"Tome of the Cabal\", npc = 6251, npcName = \"Strahad Farsan\", minLevel = 30, qlvl = 30, crumbs = { 1798 }, preTitles = { [1798] = \"Seeking Strahad\" }, map = 1413, x = 62.58, y = 35.31, z = 40.5 },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{npc:6294}\",\n\t\tnote = \"{npc:6294} is in the library of the {object:32356}. He wants two lost pieces of the {quest:1758}: one on the {area:287} coast, one in {zone:1441}.\",\n\t\tgoals = {\n\t\t\t{ t = \"turnin\", quest = 1758, title = \"Tome of the Cabal\", npc = 6294, npcName = \"Krom Stoutarm\", map = 1455, x = 74.38, y = 9.72, z = 503.5, spotsPacked = \"74.4,9.7,503.5,15,6\" },\n\t\t\t{ t = \"accept\", quest = 1802, title = \"Tome of the Cabal\", npc = 6294, npcName = \"Krom Stoutarm\", minLevel = 30, qlvl = 30, pre = { 1758 }, preTitles = { [1758] = \"Tome of the Cabal\" }, map = 1455, x = 74.26, y = 9.74, z = 503.5, spotsPacked = \"74.4,9.7,503.5,15,6\" },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{item:6931}\",\n\t\tnote = \"The tome is a small grey-blue book lying in the sand of a murloc camp on the shore south-west of {area:271}, near the water's edge. Six or seven murlocs guard it and more lurk underwater: they come in groups, so Fear one and keep your voidwalker on the rest. Walk down to the water to click it; from the hillside the crates block the cursor.\",\n\t\tgoals = {\n\t\t\t{ t = \"collect\", quest = 1802, title = \"Tome of the Cabal\", item = 6931, itemName = \"Moldy Tome\", count = 1, oi = 1, map = 1424, x = 27.81, y = 72.79, z = 0.5, f = \"e\", spotsPacked = \"27.67,72.71,0.5,0;27.95,72.86,0.5,0\", note = \"{item:6931}, from the {quest:1802} on the sand\", from = \"Tome of the Cabal\", fromKind = \"object\", fromId = 92013 },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{item:6997}\",\n\t\tnote = \"The centaur cave opens in the cliffs north of {area:484}, a Horde town: keep clear of its guards. Inside, keep right at each fork, cross the pool by the small waterfall, and open the small dark box against the wall beside a larger chest: the larger one is the wrong one. You can open it only while on the quest. The centaurs respawn behind you on the way out.\",\n\t\tgoals = {\n\t\t\t{ t = \"collect\", quest = 1802, title = \"Tome of the Cabal\", item = 6997, itemName = \"Tattered Manuscript\", count = 1, oi = 2, map = 1441, x = 43.44, y = 32.61, z = -49.1, f = \"e\", note = \"{item:6997}, in the {object:92423}\", from = \"Damaged Chest\", fromKind = \"object\", fromId = 92423 },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"Back to {npc:6294}\",\n\t\tnote = \"{npc:6294} pieces the tome together and gives you the {item:7006}: keep it, {npc:6251} takes it with the rods.\",\n\t\tgoals = {\n\t\t\t{ t = \"turnin\", quest = 1802, title = \"Tome of the Cabal\", npc = 6294, npcName = \"Krom Stoutarm\", map = 1455, x = 74.38, y = 9.72, z = 503.5, spotsPacked = \"74.4,9.7,503.5,15,6\" },\n\t\t\t{ t = \"accept\", quest = 1804, title = \"Tome of the Cabal\", npc = 6294, npcName = \"Krom Stoutarm\", minLevel = 30, qlvl = 30, pre = { 1802 }, preTitles = { [1802] = \"Tome of the Cabal\" }, map = 1455, x = 74.26, y = 9.74, z = 503.5, spotsPacked = \"74.4,9.7,503.5,15,6\" },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"Rods of Channeling\",\n\t\tnote = \"The Dragonmaw hold {area:1036} in the hills east of the road from {area:150} to {area:836}. Only the casters drop the rods, four kills in five: the Bonewarders (level 27, with skeleton pets) and Shadowwarders (28). A steep path north of the central spirit healer leads up into the camp past most of the warriors.\",\n\t\tgoals = {\n\t\t\t{ t = \"collect\", quest = 1804, title = \"Tome of the Cabal\", item = 6930, itemName = \"Rod of Channeling\", count = 3, oi = 1, map = 1437, x = 52.38, y = 52.64, f = \"e\", spotsPacked = \"53.1,54.2,,32,4,,29;50.6,50.9,52.1,34,3;51.7,49,54.3,18,2;49,46.7,52.3,59,10,,29;46.1,46.4,,38,4;45.6,42.9,51.9,15,2\", lvl = 28, note = \"Rods of Channeling, from the Dragonmaw casters\", from = \"Dragonmaw Shadowwarder\", fromKind = \"npc\", fromAlso = \"Dragonmaw Bonewarder\", fromId = 1038, fromAlsoId = 1057, fromNpcs = { { npc = 1038, npcName = \"Dragonmaw Shadowwarder\" }, { npc = 1057, npcName = \"Dragonmaw Bonewarder\" } } },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{quest:1795}\",\n\t\tnote = \"Back to {npc:6251} in {area:392}. When you accept, he draws the summoning circle and his acolytes channel a greater circle over it: wait inside the tower until both are done. Then use the {quest:1804} on the circle. The felhunter (level 30, not elite) silences and eats mana, and it vanishes after two minutes: have your voidwalker out, open with your damage over time at once and let the voidwalker tank. If you die or it wins, abandon {quest:1795} and take it again from {npc:6251}. Keep the tome: {npc:6251} takes it back.\",\n\t\tgoals = {\n\t\t\t{ t = \"turnin\", quest = 1804, title = \"Tome of the Cabal\", npc = 6251, npcName = \"Strahad Farsan\", map = 1413, x = 62.58, y = 35.31, z = 40.5 },\n\t\t\t{ t = \"accept\", quest = 1795, title = \"The Binding\", npc = 6251, npcName = \"Strahad Farsan\", minLevel = 30, qlvl = 30, pre = { 1805, 1804 }, preTitles = { [1804] = \"Tome of the Cabal\", [1805] = \"Tome of the Cabal\" }, map = 1413, x = 62.58, y = 35.31, z = 40.5 },\n\t\t\t{ t = \"use\", item = 6999, itemName = \"Tome of the Cabal\", map = 1413, x = 62.6, y = 35.3, f = \"e\", note = \"{quest:1804}, on the circle\" },\n\t\t\t{ t = \"kill\", quest = 1795, title = \"The Binding\", target = \"Summoned Felhunter\", npc = 6268, count = 1, oi = 1, map = 1413, x = 62.6, y = 35.31, f = \"e\" },\n\t\t\t{ t = \"turnin\", quest = 1795, title = \"The Binding\", npc = 6251, npcName = \"Strahad Farsan\", map = 1413, x = 62.58, y = 35.31, z = 40.5, note = \"{npc:6251}: {spell:691}\" },\n\t\t},\n\t},\n}",
		})
	end
	register()
end

