= \"{quest:1706}\",\n\t\tonly = { races = { \"Human\", \"Skyborne\" } },\n\t\tgoals = {\n\t\t\t{ t = \"turnin\", quest = 1705, title = \"Burning Blood\", npc = 1416, npcName = \"Grimand Elmore\", map = 1453, x = 59.62, y = 34.03, z = 95.4, spotsPacked = \"59.6,34,95.4,15,3\" },\n\t\t\t{ t = \"accept\", quest = 1706, title = \"Grimand's Armor\", npc = 1416, npcName = \"Grimand Elmore\", minLevel = 20, qlvl = 30, pre = { 1705 }, preTitles = { [1705] = \"Burning Blood\" }, map = 1453, x = 59.49, y = 34.01, z = 95.4, spotsPacked = \"59.6,34,95.4,15,3\" },\n\t\t\t{ t = \"turnin\", quest = 1706, title = \"Grimand's Armor\", npc = 1416, npcName = \"Grimand Elmore\", map = 1453, x = 59.49, y = 34.01, z = 95.4, spotsPacked = \"59.6,34,95.4,15,3\", rewards = { items = { { item = 6971, itemName = \"Fire Hardened Coif\" } } } },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{quest:1703}\",\n\t\tnote = \"{quest:1703} works on the south side of the {area:1660} in {zone:1457}. He wants 20 {quest:1710}.\",\n\t\tonly = { races = { \"NightElf\" } },\n\t\tgoals = {\n\t\t\t{ t = \"turnin\", quest = 1703, title = \"Mathiel\", npc = 6142, npcName = \"Mathiel\", map = 1457, x = 59.25, y = 45.46, z = 1330.9, spotsPacked = \"59.2,45.5,1330.9,15,3\" },\n\t\t\t{ t = \"level\", level = 29 },\n\t\t\t{ t = \"accept\", quest = 1710, title = \"Sunscorched Shells\", npc = 6142, npcName = \"Mathiel\", minLevel = 20, qlvl = 30, pre = { 1782 }, crumbs = { 1703 }, preTitles = { [1703] = \"Mathiel\", [1782] = \"Furen's Armor\" }, map = 1457, x = 59.33, y = 45.29, z = 1330.9, spotsPacked = \"59.2,45.5,1330.9,15,3\" },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{quest:1710}\",\n\t\tnote = \"The shells lie on the ground under the wyvern nests at {area:482} in western {zone:1441}, deeper into the gorge. Only nine exist and each returns 3 minutes after you pick it, so you will wait; some shell-like things there cannot be looted. Highperch Wyverns (level 28-31) guard them and sometimes come several at once: the guide waits for le