			stepCount = 20,
			stepsSrc = "return {\n\t{\n\t\ttitle = \"{npc:252377} in {area:16638}\",\n\t\tnote = \"At 10, {npc:252377} stands with the trainers by {area:16638}'s west gate. A cultist, {npc:257196}, holds her family's shield at the {area:16629}.\",\n\t\tonly = { races = { \"Skyborne\" } },\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 10 },\n\t\t\t{ t = \"accept\", quest = 94003, title = \"The Skybreaker Bulwark\", npc = 252377, npcName = \"Seena Skybreaker\", minLevel = 10, qlvl = 10, map = 2521, x = 59.82, y = 72.85, z = 675.3 },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{npc:257196}\",\n\t\tnote = \"Head north-west from {area:16638} to the {area:16629}. {npc:257196} stands west of the shrine's approach, among the cult's Guardians, Spiritcallers and Blademasters: pull them one at a time before you take him. He drops the {item:263993}.\",\n\t\tonly = { races = { \"Skyborne\" } },\n\t\tgoals = {\n\t\t\t{ t = \"kill\", target = \"Zaal Stormshield\", npc = 257196, map = 2521, x = 56.66, y = 50.4, z = 772.3 },\n\t\t\t{ t = \"collect\", quest = 94003, title = \"The Skybreaker Bulwark\", item = 263993, itemName = \"Skybreaker Bulwark\", count = 1, oi = 1, map = 2521, x = 56.66, y = 50.4, z = 772.3, note = \"{item:263993}, from {npc:257196}\", from = \"Zaal Stormshield\", fromKind = \"npc\", fromId = 257196, fromNpcs = { { npc = 257196, npcName = \"Zaal Stormshield\" } } },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{quest:94003}\",\n\t\tnote = \"Back to {npc:252377} in {area:16638}. She teaches {spell:71} and gives you the {item:275290}, a shield to use it with. {npc:6090}'s road below still gives a weapon, once you reach {zone:1453}.\",\n\t\tonly = { races = { \"Skyborne\" } },\n\t\tgoals = {\n\t\t\t{ t = \"turnin\", quest = 94003, title = \"The Skybreaker Bulwark\", npc = 252377, npcName = \"Seena Skybreaker\", map = 2521, x = 59.82, y = 72.85, z = 675.3, note = \"{npc:252377}: {spell:71}\", rewards = { items = { { item = 275290, itemName = \"Stormforged Protector\" } } } },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{quest:1679}\",\n\t\tnote = \"At 10, {npc:1229}, the warrior trainer in {area:131}, sends you to {quest:1679} in {zone:1455}. Any Alliance warrior may take one of the three roads, never two: in {zone:1453} at 10 anyway? {npc:5480}'s {quest:1638} is the quickest stance (one fight in a tavern), with a Haggard's weapon after it.\",\n\t\tonly = { races = { \"Dwarf\", \"Gnome\" } },\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 10 },\n\t\t\t{ t = \"accept\", quest = 1679, title = \"Muren Stormpike\", npc = 1229, npcName = \"Granis Swiftaxe\", minLevel = 10, qlvl = 10, closedBy = { 1678, 1638, 1684, 1639, 1683 }, endNpcs = { 6114 }, xp = 85, preTitles = { [1638] = \"A Warrior's Training\", [1639] = \"Bartleby the Drunk\", [1678] = \"Vejrek\", [1683] = \"Vorlus Vilehoof\", [1684] = \"Elanaria\" }, map = 1426, x = 47.29, y = 52.62, z = 399.7 },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{quest:1679} in {zone:1455}\",\n\t\tnote = \"{quest:1679} stands in the {object:32390} in the {object:32359}.\",\n\t\tonly = { races = { \"Dwarf\", \"Gnome\" } },\n\t\tgoals = {\n\t\t\t{ t = \"turnin\", quest = 1679, title = \"Muren Stormpike\", npc = 6114, npcName = \"Muren Stormpike\", map = 1455, x = 70.65, y = 90.26, z = 510.4, spotsPacked = \"70.6,90.3,510.4,15,4\" },\n\t\t\t{ t = \"accept\", quest = 1678, title = \"Vejrek\", npc = 6114, npcName = \"Muren Stormpike\", minLevel = 10, qlvl = 11, closedBy = { 1639, 1683 }, endNpcs = { 6114 }, xp = 1100, crumbs = { 1679 }, preTitles = { [1639] = \"Bartleby the Drunk\", [1679] = \"Muren Stormpike\", [1683] = \"Vorlus Vilehoof\" }, map = 1455, x = 70.85, y = 90.05, z = 510.4, spotsPacked = \"70.6,90.3,510.4,15,4\" },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{quest:1678}\",\n\t\tnote = \"{quest:1678} (level 11, a lone troll) waits at his hut on a hill south of {area:135}, near the mountains at the top of a short ramp, with no other trolls around; the hut at the front of {area:135} is the wrong one. He fights in {spell:71} and sunders your armor; {spell:6343} slows him. His head always drops; he returns about 8 minutes after dying.\",\n\t\tonly = { races = { \"Dwarf\", \"Gnome\" } },\n\t\tgoals = {\n\t\t\t{ t = \"collect\", quest = 1678, title = \"Vejrek\", item = 6799, itemName = \"Vejrek's Head\", count = 1, oi = 1, map = 1426, x = 27.83, y = 57.96, z = 426.6, f = \"e\", from = \"Vejrek\", fromKind = \"npc\", fromId = 6113, fromNpcs = { { npc = 6113, npcName = \"Vejrek\" } } },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{quest:1680}\",\n\t\tnote = \"Back to {npc:6114} for {spell:71}, then to {quest:1680} at the {object:32372} in the middle of {zone:1455}.\",\n\t\tonly = { races = { \"Dwarf\", \"Gnome\" } },\n\t\tgoals = {\n\t\t\t{ t = \"turnin\", quest = 1678, title = \"Vejrek\", npc = 6114, npcName = \"Muren Stormpike\", map = 1455, x = 70.65, y = 90.26, z = 510.4, spotsPacked = \"70.6,90.3,510.4,15,4\", note = \"{npc:6114}: {spell:71}\" },\n\t\t\t{ t = \"accept\", quest = 1680, title = \"Tormus Deepforge\", npc = 6114, npcName = \"Muren Stormpike\", minLevel = 10, qlvl = 11, pre = { 1683, 1678, 1639 }, closedBy = { 1681 }, endNpcs = { 6031 }, xp = 90, preTitles = { [1639] = \"Bartleby the Drunk\", [1678] = \"Vejrek\", [1681] = \"Ironband's Compound\", [1683] = \"Vorlus Vilehoof\" }, map = 1455, x = 70.85, y = 90.05, z = 510.4, spotsPacked = \"70.6,90.3,510.4,15,4\" },\n\t\t\t{ t = \"turnin\", quest = 1680, title = \"Tormus Deepforge\", npc = 6031, npcName = \"Tormus Deepforge\", map = 1455, x = 48.6, y = 43.38, z = 498.9, spotsPacked = \"48.6,43,498.9,15,5\" },\n\t\t\t{ t = \"accept\", quest = 1681, title = \"Ironband's Compound\", npc = 6031, npcName = \"Tormus Deepforge\", minLevel = 10, qlvl = 11, pre = { 1683, 1678, 1639 }, crumbs = { 1680 }, preTitles = { [1639] = \"Bartleby the Drunk\", [1678] = \"Vejrek\", [1680] = \"Tormus Deepforge\", [1683] = \"Vorlus Vilehoof\" }, map = 1455, x = 48.6, y = 43.38, z = 498.9, spotsPacked = \"48.6,43,498.9,15,5\" },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{quest:1681}\",\n\t\tnote = \"{quest:1681} lies in eastern {zone:1426}, below {area:212} on its south side. Dark Iron Spies (level 8-10) stand along the way, far enough apart to pull one at a time. {object:85562} is in the basement of the southernmost house; {npc:6124} (level 11) stands by it and charges on sight. The box always holds the ore and refills 15 minutes after opening.\",\n\t\tonly = { races = { \"Dwarf\", \"Gnome\" } },\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 11 },\n\t\t\t{ t = \"collect\", quest = 1681, title = \"Ironband's Compound\", item = 6800, itemName = \"Umbral Ore\", count = 1, oi = 1, map = 1426, x = 77.9, y = 62.3, z = 400.8, f = \"e\", note = \"{item:6800}, from {object:85562}\", from = \"Ironband's Strongbox\", fromKind = \"object\", fromId = 85562 },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{quest:1682}\",\n\t\tonly = { races = { \"Dwarf\", \"Gnome\" } },\n\t\tgoals = {\n\t\t\t{ t = \"turnin\", quest = 1681, title = \"Ironband's Compound\", npc = 6031, npcName = \"Tormus Deepforge\", map = 1455, x = 48.63, y = 42.98, z = 498.9, spotsPacked = \"48.6,43,498.9,15,5\" },\n\t\t\t{ t = \"accept\", quest = 1682, title = \"Grey Iron Weapons\", npc = 6031, npcName = \"Tormus Deepforge\", minLevel = 10, qlvl = 10, pre = { 1681 }, preTitles = { [1681] = \"Ironband's Compound\" }, map = 1455, x = 48.73, y = 43.03, z = 498.9, spotsPacked = \"48.6,43,498.9,15,5\" },\n\t\t\t{ t = \"turnin\", quest = 1682, title = \"Grey Iron Weapons\", npc = 6031, npcName = \"Tormus Deepforge\", map = 1455, x = 48.73, y = 43.03, z = 498.9, spotsPacked = \"48.6,43,498.9,15,5\", rewards = { choices = { { item = 6978, itemName = \"Umbral Axe\" }, { item = 6982, itemName = \"Umbral Mace\" }, { item = 6981, itemName = \"Umbral Dagger\" }, { item = 6984, itemName = \"Umbral Sword\" } } } },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{quest:1684}\",\n\t\tnote = \"At 10, {npc:3598}, the warrior trainer in {area:186}, or {npc:2151}, who patrols the road west of {area:186}, sends you to {quest:1684} on the {area:1660} in {zone:1457}. Any Alliance warrior may take one of the three roads, never two: in {zone:1453} at 10 anyway? {npc:5480}'s {quest:1638} teaches the same stance after one fight in a tavern.\",\n\t\tonly = { races = { \"NightElf\" } },\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 10 },\n\t\t\t{ t = \"accept\", quest = 1684, title = \"Elanaria\", npc = 3598, npcName = \"Kyra Windblade\", minLevel = 10, qlvl = 10, closedBy = { 1638, 1679, 1639, 1678, 1683 }, endNpcs = { 4088 }, xp = 85, preTitles = { [1638] = \"A Warrior's Training\", [1639] = \"Bartleby the Drunk\", [1678] = \"Vejrek\", [1679] = \"Muren Stormpike\", [1683] = \"Vorlus Vilehoof\" }, map = 1438, x = 56.14, y = 59.26, z = 1308.9 },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{quest:1684} in {zone:1457}\",\n\t\tnote = \"{quest:1684} stands on the {area:1660}.\",\n\t\tonly = { races = { \"NightElf\" } },\n\t\tgoals = {\n\t\t\t{ t = \"turnin\", quest = 1684, title = \"Elanaria\", npc = 4088, npcName = \"Elanaria\", map = 1457, x = 57.39, y = 35, z = 1330.9, spotsPacked = \"57.4,35,1330.9,15,3\" },\n\t\t\t{ t = \"accept\", quest = 1683, title = \"Vorlus Vilehoof\", npc = 4088, npcName = \"Elanaria\", minLevel = 10, qlvl = 10, closedBy = { 1639, 1678 }, endNpcs = { 4088 }, xp = 850, preTitles = { [1639] = \"Bartleby the Drunk\", [1678] = \"Vejrek\" }, map = 1457, x = 57.32, y = 34.78, z = 1330.9, spotsPacked = \"57.4,35,1330.9,15,3\" },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{quest:1683}\",\n\t\tnote = \"{quest:1683} (level 10, a satyr) stands at a hidden moonwell up a hillside west of {area:186}. The trail is hard to spot: it starts behind a Gnarlpine camp and climbs in switchbacks lined with lamp posts. The furbolgs below can come in groups. His horn always drops; he returns 5 minutes after dying.\",\n\t\tonly = { races = { \"NightElf\" } },\n\t\tgoals = {\n\t\t\t{ t = \"collect\", quest = 1683, title = \"Vorlus Vilehoof\", item = 6805, itemName = \"Horn of Vorlus\", count = 1, oi = 1, map = 1438, x = 47.25, y = 63.6, z = 1402.8, f = \"e\", from = \"Vorlus Vilehoof\", fromKind = \"npc\", fromId = 6128, fromNpcs = { { npc = 6128, npcName = \"Vorlus Vilehoof\" } } },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{quest:1686}\",\n\t\tonly = { races = { \"NightElf\" } },\n\t\tgoals = {\n\t\t\t{ t = \"turnin\", quest = 1683, title = \"Vorlus Vilehoof\", npc = 4088, npcName = \"Elanaria\", map = 1457, x = 57.39, y = 35, z = 1330.9, spotsPacked = \"57.4,35,1330.9,15,3\", note = \"{npc:4088}: {spell:71}\" },\n\t\t\t{ t = \"accept\", quest = 1686, title = \"The Shade of Elura\", npc = 4088, npcName = \"Elanaria\", minLevel = 10, qlvl = 10, pre = { 1683, 1678, 1639 }, preTitles = { [1639] = \"Bartleby the Drunk\", [1678] = \"Vejrek\", [1683] = \"Vorlus Vilehoof\" }, map = 1457, x = 57.32, y = 34.78, z = 1330.9, spotsPacked = \"57.4,35,1330.9,15,3\" },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"Elunite under {area:442}\",\n\t\tnote = \"Take the boat from {area:702} to {area:442}. The wreck lies underwater just south of {area:442}'s southern pier, where the Menethil boat docks. Open Crates of Elunite on the sea floor around the wreck, by a huge sunken turtle, toward the beach and under the pier until you have eight; every crate holds ore and comes back in 3-5 minutes. The grey {npc:6133} (level 11) drifts around the middle of the wreck and always drops the medallion: target it when you see it, so you can find it after surfacing for air. Watch your breath; Threshers can join in.\",\n\t\tonly = { races = { \"NightElf\" } },\n\t\tgoals = {\n\t\t\t{ t = \"collect\", quest = 1686, title = \"The Shade of Elura\", item = 6808, itemName = \"Elunite Ore\", count = 8, oi = 1, map = 1439, x = 32.45, y = 44.52, f = \"e\", spotsPacked = \"31.07,44.62,-37,0;31.33,43.93,-39.8,0;31.41,43.32,-54.4,0;31.51,44.28,-35.3,0;31.61,44.83,-36.7,0;31.72,42.81,-40.6,0;31.74,45.96,-14.4,0;31.82,44.14,-33.2,0;31.85,43.62,-36.7,0;32,46.34,-13.6,0;32.21,44.42,-20.7,0;32.23,42.84,-37,0;32.3,46.39,-13.6,0;32.32,42.36,-36.3,0;32.47,43.46,-19.6,0;32.52,42.71,-36.9,0;32.67,46.44,-13.9,0;32.84,43.67,-18.5,0;32.95,46.7,-13.9,0;33.13,46.31,-13.8,0;33.24,43.89,-20.6,0;33.36,45.32,-8.8,0;33.58,44.23,-18.9,0;33.65,45.59,-12.6,0;33.73,43.83,-19.1,0;33.84,44.44,-17.9,0;33.88,45.27,-13.6,0\", note = \"{item:6808}, from Crates of Elunite\", from = \"Crate of Elunite\", fromKind = \"object\", fromId = 86492 },\n\t\t\t{ t = \"collect\", quest = 1686, title = \"The Shade of Elura\", item = 6809, itemName = \"Elura's Medallion\", count = 1, oi = 2, map = 1439, x = 31.64, y = 44.86, z = -36.1, f = \"e\", note = \"{item:6809}, from the {npc:6133}\", from = \"Shade of Elura\", fromKind = \"npc\", fromId = 6133, fromNpcs = { { npc = 6133, npcName = \"Shade of Elura\" } } },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{quest:1692}\",\n\t\tnote = \"Back on the {area:1660}: {npc:4088} hands you the {item:6812}; {npc:6142} works on the far, south side of the same terrace, easy to miss.\",\n\t\tonly = { races = { \"NightElf\" } },\n\t\tgoals = {\n\t\t\t{ t = \"turnin\", quest = 1686, title = \"The Shade of Elura\", npc = 4088, npcName = \"Elanaria\", map = 1457, x = 57.39, y = 35, z = 1330.9, spotsPacked = \"57.4,35,1330.9,15,3\" },\n\t\t\t{ t = \"accept\", quest = 1692, title = \"Smith Mathiel\", npc = 4088, npcName = \"Elanaria\", minLevel = 10, qlvl = 10, pre = { 1686 }, preTitles = { [1686] = \"The Shade of Elura\" }, map = 1457, x = 57.32, y = 34.78, z = 1330.9, spotsPacked = \"57.4,35,1330.9,15,3\" },\n\t\t\t{ t = \"turnin\", quest = 1692, title = \"Smith Mathiel\", npc = 6142, npcName = \"Mathiel\", map = 1457, x = 59.03, y = 45.23, z = 1330.9, spotsPacked = \"59.2,45.5,1330.9,15,3\" },\n\t\t\t{ t = \"accept\", quest = 1693, title = \"Weapons of Elunite\", npc = 6142, npcName = \"Mathiel\", minLevel = 10, qlvl = 10, pre = { 1692 }, preTitles = { [1692] = \"Smith Mathiel\" }, map = 1457, x = 59.03, y = 45.23, z = 1330.9, spotsPacked = \"59.2,45.5,1330.9,15,3\" },\n\t\t\t{ t = \"turnin\", quest = 1693, title = \"Weapons of Elunite\", npc = 6142, npcName = \"Mathiel\", map = 1457, x = 59.03, y = 45.23, z = 1330.9, spotsPacked = \"59.2,45.5,1330.9,15,3\", rewards = { choices = { { item = 6966, itemName = \"Elunite Axe\" }, { item = 6968, itemName = \"Elunite Hammer\" }, { item = 6969, itemName = \"Elunite Dagger\" }, { item = 6967, itemName = \"Elunite Sword\" } } } },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{quest:1638}\",\n\t\tnote = \"At 10, {npc:913}, the warrior trainer by the inn in {area:87}, sends you to {npc:6089} in {zone:1453}; {npc:5480}, the warrior trainer in {zone:1453}'s {object:2100}, offers it too.\",\n\t\tonly = { races = { \"Human\", \"Skyborne\" } },\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 10 },\n\t\t\t{ t = \"accept\", quest = 1638, title = \"A Warrior's Training\", npc = 913, npcName = \"Lyria Du Lac\", minLevel = 10, qlvl = 10, closedBy = { 1679, 1684, 1678, 1683, 1639 }, endNpcs = { 6089 }, xp = 85, preTitles = { [1639] = \"Bartleby the Drunk\", [1678] = \"Vejrek\", [1679] = \"Muren Stormpike\", [1683] = \"Vorlus Vilehoof\", [1684] = \"Elanaria\" }, map = 1429, x = 40.99, y = 65.88, z = 57.9 },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{npc:6090}\",\n\t\tnote = \"{npc:6089} and {npc:6090} are in the Pig and Whistle tavern in {object:2100}; {npc:6090} is the drunk at the far end of the bar. {npc:6090} (level 10) hits harder than his level, so start at full health; he gives up at low health instead of dying. If he wins, he disappears for about three minutes: keep the quest and talk to him again when he is back. A Dwarf, Gnome or Night Elf who took {quest:1638} from {npc:5480} instead of their home road is led through {zone:1453} from here.\",\n\t\twhen = { { k = \"turnedin\", neg = true, q = 1679 }, { k = \"turnedin\", neg = true, q = 1684 } },\n\t\tgoals = {\n\t\t\t{ t = \"turnin\", quest = 1638, title = \"A Warrior's Training\", npc = 6089, npcName = \"Harry Burlguard\", map = 1453, x = 76.89, y = 53.28, z = 103 },\n\t\t\t{ t = \"accept\", quest = 1639, title = \"Bartleby the Drunk\", npc = 6089, npcName = \"Harry Burlguard\", minLevel = 10, qlvl = 10, closedBy = { 1678, 1683 }, endNpcs = { 6090 }, xp = 85, preTitles = { [1678] = \"Vejrek\", [1683] = \"Vorlus Vilehoof\" }, map = 1453, x = 76.89, y = 53.28, z = 103 },\n\t\t\t{ t = \"turnin\", quest = 1639, title = \"Bartleby the Drunk\", npc = 6090, npcName = \"Bartleby\", map = 1453, x = 76.62, y = 52.83, z = 102.9 },\n\t\t\t{ t = \"accept\", quest = 1640, title = \"Beat Bartleby\", npc = 6090, npcName = \"Bartleby\", minLevel = 10, qlvl = 10, pre = { 1639, 1678, 1683 }, preTitles = { [1639] = \"Bartleby the Drunk\", [1678] = \"Vejrek\", [1683] = \"Vorlus Vilehoof\" }, map = 1453, x = 76.62, y = 52.83, z = 102.9 },\n\t\t\t{ t = \"kill\", quest = 1640, title = \"Beat Bartleby\", target = \"Bartleby\", npc = 6090, oi = 1, map = 1453, x = 76.62, y = 52.83, z = 102.9, note = \"{quest:1640}\" },\n\t\t\t{ t = \"turnin\", quest = 1640, title = \"Beat Bartleby\", npc = 6090, npcName = \"Bartleby\", map = 1453, x = 76.62, y = 52.83, z = 102.9 },\n\t\t\t{ t = \"accept\", quest = 1665, title = \"Bartleby's Mug\", npc = 6090, npcName = \"Bartleby\", minLevel = 10, qlvl = 10, pre = { 1640 }, preTitles = { [1640] = \"Beat Bartleby\" }, map = 1453, x = 76.62, y = 52.83, z = 102.9 },\n\t\t\t{ t = \"turnin\", quest = 1665, title = \"Bartleby's Mug\", npc = 6089, npcName = \"Harry Burlguard\", map = 1453, x = 76.89, y = 53.28, z = 103, note = \"{npc:6089}: {spell:71}\" },\n\t\t\t{ t = \"accept\", quest = 1666, title = \"Marshal Haggard\", npc = 6089, npcName = \"Harry Burlguard\", minLevel = 10, qlvl = 10, pre = { 1665 }, preTitles = { [1665] = \"Bartleby's Mug\" }, map = 1453, x = 76.89, y = 53.28, z = 103 },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{npc:294}\",\n\t\tnote = \"{npc:294}'s manor stands at the south-east edge of the {area:88} in eastern Elwynn, at the end of a short road that does not join the main one.\",\n\t\twhen = { { k = \"turnedin\", neg = true, q = 1679 }, { k = \"turnedin\", neg = true, q = 1684 } },\n\t\tgoals = {\n\t\t\t{ t = \"turnin\", quest = 1666, title = \"Marshal Haggard\", npc = 294, npcName = \"Marshal Haggard\", map = 1429, x = 84.5, y = 69.34, z = 54.1 },\n\t\t\t{ t = \"accept\", quest = 1667, title = \"Dead-tooth Jack\", npc = 294, npcName = \"Marshal Haggard\", minLevel = 10, qlvl = 10, pre = { 1666 }, preTitles = { [1666] = \"Marshal Haggard\" }, map = 1429, x = 84.5, y = 69.34, z = 54.1 },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{quest:1667}\",\n\t\tnote = \"{npc:6093} (level 11) camps in the far south-east of Elwynn. A guard stands beside him and Defias and wolves are spread around the camp (now and then a rarer guard too): clear them one at a time, then kill Jack. He always drops {item:6783}; open {object:85563} in the crates by him for {item:6782}. Jack returns 3 minutes after dying, the box 1 minute after opening.\",\n\t\twhen = { { k = \"turnedin\", neg = true, q = 1679 }, { k = \"turnedin\", neg = true, q = 1684 } },\n\t\tgoals = {\n\t\t\t{ t = \"collect\", item = 6783, itemName = \"Dead-tooth's Key\", map = 1429, x = 89.36, y = 79.03, z = 41.6, f = \"e\", note = \"from {npc:6093}\", from = \"Dead-Tooth Jack\", fromKind = \"npc\", fromId = 6093, fromNpcs = { { npc = 6093, npcName = \"Dead-Tooth Jack\" } } },\n\t\t\t{ t = \"collect\", quest = 1667, title = \"Dead-tooth Jack\", item = 6782, itemName = \"Marshal Haggard's Badge\", count = 1, oi = 1, map = 1429, x = 89.28, y = 78.82, z = 41.5, f = \"e\", note = \"{item:6782}, from {object:85563}\", from = \"Dead-tooth's Strongbox\", fromKind = \"object\", fromId = 85563, group = { kind = \"elite\", lvl = 12, near = true, rank = 1 } },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"Back to {npc:294}\",\n\t\twhen = { { k = \"turnedin\", neg = true, q = 1679 }, { k = \"turnedin\", neg = true, q = 1684 } },\n\t\tgoals = {\n\t\t\t{ t = \"turnin\", quest = 1667, title = \"Dead-tooth Jack\", npc = 294, npcName = \"Marshal Haggard\", map = 1429, x = 84.5, y = 69.34, z = 54.1, rewards = { choices = { { item = 6979, itemName = \"Haggard's Axe\" }, { item = 6983, itemName = \"Haggard's Hammer\" }, { item = 6980, itemName = \"Haggard's Dagger\" }, { item = 6985, itemName = \"Haggard's Sword\" } } } },\n\t\t},\n\t},\n}",
		})
	end
	register()
end

