			names = { ["area:2918"] = "Champions' Hall", ["item:18243"] = "Black Battlestrider", ["item:18244"] = "Black War Ram", ["npc:12783"] = "Lieutenant Karter", ["npc:14332"] = "Black War Steed", ["object:2100"] = "Old Town", ["skill:762"] = "Riding", ["spell:10907"] = "Mechanostrider Piloting", ["spell:1299382"] = "Rank Points", ["spell:22723"] = "Black War Tiger", ["spell:824"] = "Horse Riding", ["spell:826"] = "Ram Riding", ["spell:828"] = "Tiger Riding", ["zone:1453"] = "Stormwind" },
			stepCount = 2,
			stepsSrc = "return {\n\t{\n\t\ttitle = \"PvP rank 11\",\n\t\tnote = \"{spell:1299382} come from battlegrounds, PvP quests and the season's weekly tasks, with a weekly cap; Commander (rank 11) unlocks the Black War mounts. The Player vs. Player tab of your character pane shows your rank and what you may buy. {skill:762} one at full speed needs Journeyman {skill:762} (level 60). Polestar cannot read your rank, so this step waits for level 60 and Journeyman {skill:762}.\",\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 60 },\n\t\t\t{ t = \"skill\", skill = \"Riding\", skillLine = 762, level = 150 },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{npc:12783}\",\n\t\tnote = \"{npc:12783} sells the mounts in {zone:1453}'s {object:2100} by the {area:2918}, beside the other honor quartermasters. The Forever client lists each at 100g. Each one also needs its kind's riding: Humans ride the steed, Night Elves the tiger, Gnomes the battlestrider, Dwarves the ram. A Skyborne, or anyone choosing another race's mount, first needs that riding from its trainer (Exalted with the race's city).\",\n\t\tgoals = {\n\t\t\t{ t = \"vendor\", npc = 12783, npcName = \"Lieutenant Karter\", map = 1453, x = 70.6, y = 55.9, z = 105.3, f = \"e\" },\n\t\t\t{ t = \"buy\", npc = 12783, npcName = \"Lieutenant Karter\", item = 18241, itemName = \"Black War Steed Bridle\", map = 1453, x = 70.6, y = 55.9, z = 105.3, f = \"e\", optional = true, note = \"{npc:14332}, {spell:824}, 100g\" },\n\t\t\t{ t = \"buy\", npc = 12783, npcName = \"Lieutenant Karter\", item = 18242, itemName = \"Reins of the Black War Tiger\", map = 1453, x = 70.6, y = 55.9, z = 105.3, f = \"e\", optional = true, note = \"{spell:22723}, {spell:828}, 100g\" },\n\t\t\t{ t = \"buy\", npc = 12783, npcName = \"Lieutenant Karter\", item = 18243, itemName = \"Black Battlestrider\", map = 1453, x = 70.6, y = 55.9, z = 105.3, f = \"e\", optional = true, note = \"{item:18243}, {spell:10907}, 100g\" },\n\t\t\t{ t = \"buy\", npc = 12783, npcName = \"Lieutenant Karter\", item = 18244, itemName = \"Black War Ram\", map = 1453, x = 70.6, y = 55.9, z = 105.3, f = \"e\", optional = true, note = \"{item:18244}, {spell:826}, 100g\" },\n\t\t},\n\t},\n}",
