title = \"Morrowgrain Research\", npc = 3516, npcName = \"Arch Druid Fandral Staghelm\", minLevel = 47, qlvl = 50, pre = { 3764 }, preTitles = { [3764] = \"Un'Goro Soil\" }, map = 1457, x = 35.06, y = 9.55, z = 1367, spotsPacked = \"34.8,8.9,1367,15,8\", note = \"{quest:3781}, +10\" },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{area:1658}\",\n\t\twhen = { { k = \"done\", label = \"dn-morrowgrain\" } },\n\t\tgoals = {\n\t\t\t{ t = \"goto\", text = \"{area:1658}\", area = 1658, map = 1457, x = 35.8, y = 11.6, f = \"e\" },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{faction:69}: {quest:3781}\",\n\t\tnote = \"{npc:9047}, beside Fandral in the {area:1658}, takes the soil. {npc:4217} sells the {item:11020} and Packets of Tharlendris Seeds. With a seed packet and 2 {quest:3764} in your bags, use the pouch to grow an {item:11024} and open it: about one casing in three holds {item:11040} (1 to 5), the rest other herbs. The pouch works once every 10 minutes, so use it whenever it is ready while you do other things.\",\n\t\twhen = { { k = \"done\", label = \"dn-morrowgrain\" } },\n\t\tgoals = {\n\t\t\t{ t = \"turnin\", quest = 3781, title = \"Morrowgrain Research\", npc = 4217, npcName = \"Mathrengyl Bearwalker\", map = 1457, x = 35.37, y = 8.4, z = 1340.1 },\n\t\t\t{ t = \"accept\", quest = 3785, title = \"Morrowgrain Research\", npc = 4217, npcName = \"Mathrengyl Bearwalker\", minLevel = 47, qlvl = 50, pre = { 3781 }, preTitles = { [3781] = \"Morrowgrain Research\" }, map = 1457, x = 35.37, y = 8.4, z = 1340.1, note = \"{quest:3781}, +100\" },\n\t\t\t{ t = \"buy\", npc = 4217, npcName = \"Mathrengyl Bearwalker\", item = 11020, itemName = \"Evergreen Pouch\", map = 1457, x = 35.37, y = 8.4, z = 1340.1 },\n\t\t\t{ t = \"buy\", npc = 4217, npcName = \"Mathrengyl Bearwalker\", item = 11022, itemName = \"Packet of Tharlendris Seeds\", count = 10, map = 1457, x = 35.37, y = 8.4, z = 1340.1 },\n\t\t\t{ t = \"collect\", quest = 3785, title = \"Morrowgrain Research\", item = 11040, itemName = \"Morrowgrain\", count = 10, oi = 1, map = 1457, x = 35.4, y = 8.4, f = \"e\", note = \"{item:11040}: grow it here and open the casings\" },\n\t\t\t{ t = \"turnin\", quest = 3785, title = \"Morrowgrain Research\", npc = 4217, npcName = \"Mathrengyl Bearwalker\", map = 1457, x = 35.37, y = 8.4, z = 1340.1 },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{quest:3803}\",\n\t\tnote = \"Every 10 {item:11040}: 50 reputation at {npc:4217}. Keep the pouch and buy seeds as you go. It is slow: about 9 casings, 90 minutes of pouch waits, 18 {quest:3764} and 9 seed packets for each hand-in, a little over 30 reputation an hour, so run it beside the {item:14047}. {npc:7879} at {area:1116} in {zone:1444} takes {item:11040} at the same rate, 25 for 5, after his own quest.\",\n\t\twhen = { { k = \"done\", label = \"dn-morrowgrain\" } },\n\t\tgoals = {\n\t\t\t{ t = \"goto\", text = \"{area:1658}\", area = 1658, map = 1457, x = 35.8, y = 11.6, f = \"e\", optional = true },\n\t\t\t{ t = \"collect\", item = 11040, itemName = \"Morrowgrain\", count = 10, map = 1457, x = 35.4, y = 8.4, f = \"e\", optional = true },\n\t\t\t{ t = \"turnin\", quest = 3803, title = \"Morrowgrain to Darnassus\", npc = 4217, npcName = \"Mathrengyl Bearwalker\", minLevel = 47, qlvl = 55, pre = { 3785 }, map = 1457, x = 35.37, y = 8.4, z = 1340.1, optional = true, note = \"{npc:4217}: {quest:3803}, +50\", direct = true },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{quest:7801} to Honored\",\n\t\tnote = \"{quest:7801}: 50 reputation for 20 {item:14047}, as often as you like. After the four first donations a Human, Dwarf or Gnome stands at Friendly 700 of 6,000, so Honored is 5,300 away: 106 turn-ins, 2,120 {item:14047} (Night Elves start 900 higher: 88 turn-ins; Skyborne start at Neutral 500, so 7,900 away: 158, two fewer after Exploring the Alliance). {quest:4183} and the {item:11040} chain above take 8 turn-ins off, and every 10 {item:11040} you hand in counts as one more; each hub you did takes 20 to 28 more off. More quests pay {faction:69}, in full while they are no more than 5 levels below you: the rest of {zone:1439} (about 3,400 more), {area:415} in {zone:1440} (about 3,900) and Feathermoon in {zone:1444} (about 1,700). Every city gain also gives a quarter as much to the other three Alliance cities (not counted here). Hand in all your {item:14047} at once.\",\n\t\tgoals = {\n\t\t\t{ t = \"collect\", item = 14047, itemName = \"Runecloth\", count = 20, optional = true, candidates = candidateLists[1] },\n\t\t\t{ t = \"turnin\", quest = 7801, title = \"Additional Runecloth\", npc = 14725, npcName = \"Raedon Duskstriker\", minLevel = 50, qlvl = 60, pre = { 7800 }, map = 1457, x = 63.6, y = 22.99, z = 1333.1, spotsPacked = \"63.7,22.7,1333.1,15,3\", optional = true, direct = true },\n\t\t\t{ t = \"rep\", faction = 69, factionName = \"Darnassus\", standing = 6 },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{quest:7801} to Revered\",\n\t\tnote = \"Honored: in Classic Darnassus's vendors take 10% off for you, Lelanai's nightsabers (20g, the swift ones 200g) included; Forever has not settled it, and guide sites report 5% at Friendly rising to 20% at Exalted. Honored to Revered is 12,000 reputation: 240 turn-ins, 4,800 {item:14047}.\",\n\t\tgoals = {\n\t\t\t{ t = \"collect\", item = 14047, itemName = \"Runecloth\", count = 20, optional = true, candidates = candidateLists[1] },\n\t\t\t{ t = \"turnin\", quest = 7801, title = \"Additional Runecloth\", npc = 14725, npcName = \"Raedon Duskstriker\", minLevel = 50, qlvl = 60, pre = { 7800 }, map = 1457, x = 63.6, y = 22.99, z = 1333.1, spotsPacked = \"63.7,22.7,1333.1,15,3\", optional = true, direct = true },\n\t\t\t{ t = \"rep\", faction = 69, factionName = \"Darnassus\", standing = 7 },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{quest:7801} to Exalted\",\n\t\tnote = \"Revered to Exalted is 21,000 reputation: 420 turn-ins, 8,400 {item:14047}. At Exalted, Lelanai at the {area:1658} in {faction:69} sells her nightsabers to other races in Classic; the Saber and Swift Saber guides cover them.\",\n\t\tgoals = {\n\t\t\t{ t = \"collect\", item = 14047, itemName = \"Runecloth\", count = 20, optional = true, candidates = candidateLists[1] },\n\t\t\t{ t = \"turnin\", quest = 7801, title = \"Additional Runecloth\", npc = 14725, npcName = \"Raedon Duskstriker\", minLevel = 50, qlvl = 60, pre = { 7800 }, map = 1457, x = 63.6, y = 22.99, z = 1333.1, spotsPacked = \"63.7,22.7,1333.1,15,3\", optional = true, direct = true },\n\t\t\t{ t = \"rep\", faction = 69, factionName = \"Darnassus\", standing = 8 },\n\t\t},\n\t},\n}",
		})
	end
