			stepCount = 13,
			stepsSrc = "return {\n\t{\n\t\ttitle = \"Skyborne: the recipes now\",\n\t\tnote = \"Alliance Skyborne start Friendly with the {faction:2740}, and their arrival quests The Magical City of Dalaran and Exploring the Alliance pay 100 more each, so {npc:32287} sells you the Azure recipes at once (10g each, they need skill 175). He stands upstairs in the building with the {faction:2740} banners in {area:279}, past the Sky Enclave. Buy the ones for your profession.\",\n\t\tonly = { races = { \"Skyborne\" } },\n\t\tgoals = {\n\t\t\t{ t = \"vendor\", npc = 32287, npcName = \"Archmage Alvareaux\", map = 1416, x = 13.85, y = 63.18, z = 102.5 },\n\t\t\t{ t = \"buy\", npc = 32287, npcName = \"Archmage Alvareaux\", item = 276984, itemName = \"Plans: Azure Skyforged Helm\", map = 1416, x = 13.85, y = 63.18, z = 102.5, optional = true, note = \"{item:276984} ({skill:164})\" },\n\t\t\t{ t = \"buy\", npc = 32287, npcName = \"Archmage Alvareaux\", item = 276985, itemName = \"Plans: Azure Skyforged Pauldrons\", map = 1416, x = 13.85, y = 63.18, z = 102.5, optional = true, note = \"{item:276985} ({skill:164})\" },\n\t\t\t{ t = \"buy\", npc = 32287, npcName = \"Archmage Alvareaux\", item = 276986, itemName = \"Pattern: Azure Gustwoven Hood\", map = 1416, x = 13.85, y = 63.18, z = 102.5, optional = true, note = \"{item:276986} ({skill:165})\" },\n\t\t\t{ t = \"buy\", npc = 32287, npcName = \"Archmage Alvareaux\", item = 276987, itemName = \"Pattern: Azure Gustwoven Spaulders\", map = 1416, x = 13.85, y = 63.18, z = 102.5, optional = true, note = \"{item:276987} ({skill:165})\" },\n\t\t\t{ t = \"buy\", npc = 32287, npcName = \"Archmage Alvareaux\", item = 276988, itemName = \"Pattern: Azure Windraveled Cover\", map = 1416, x = 13.85, y = 63.18, z = 102.5, optional = true, note = \"{item:276988} ({skill:165})\" },\n\t\t\t{ t = \"buy\", npc = 32287, npcName = \"Archmage Alvareaux\", item = 276989, itemName = \"Pattern: Azure Windraveled Drapes\", map = 1416, x = 13.85, y = 63.18, z = 102.5, optional = true, note = \"{item:276989} ({skill:165})\" },\n\t\t\t{ t = \"buy\", npc = 32287, npcName = \"Archmage Alvareaux\", item = 276990, itemName = \"Pattern: Azure Stormsewn Cowl\", map = 1416, x = 13.85, y = 63.18, z = 102.5, optional = true, note = \"{item:276990} ({skill:197})\" },\n\t\t\t{ t = \"buy\", npc = 32287, npcName = \"Archmage Alvareaux\", item = 276991, itemName = \"Pattern: Azure Stormsewn Epaulets\", map = 1416, x = 13.85, y = 63.18, z = 102.5, optional = true, note = \"{item:276991} ({skill:197})\" },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{quest:92432}\",\n\t\tnote = \"{npc:247264} of the {faction:2740} waits in {area:271}. He sends you to {npc:246748}'s image by the shore of {area:1338}, outside {area:279}'s walls. The {faction:2740} quests start at level 24 to 30 and pay full reputation at any level in Forever.\",\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 30 },\n\t\t\t{ t = \"accept\", quest = 92432, title = \"An Alarming Request\", npc = 247264, npcName = \"Emissary Jacques\", minLevel = 30, qlvl = 33, map = 1424, x = 48.26, y = 59.96, z = 13.4 },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{npc:246748}'s image\",\n\t\tgoals = {\n\t\t\t{ t = \"turnin\", quest = 92432, title = \"An Alarming Request\", npc = 269127, npcName = \"Image of Archmage Modera\", map = 1421, x = 68.62, y = 45.18, z = 37.2, f = \"e\" },\n\t\t\t{ t = \"accept\", quest = 92458, title = \"Heart of Disruption\", npc = 269127, npcName = \"Image of Archmage Modera\", minLevel = 24, qlvl = 33, pre = { 92432 }, closedBy = { 96984 }, endNpcs = { 269127 }, xp = 9400, preTitles = { [92432] = \"An Alarming Request\", [96984] = \"Heart of Disruption\" }, map = 1421, x = 68.62, y = 45.18, z = 37.2, f = \"e\", note = \"you get the {item:277507} with it\" },\n\t\t\t{ t = \"accept\", quest = 92457, title = \"Starving Arcane\", npc = 269127, npcName = \"Image of Archmage Modera\", minLevel = 24, qlvl = 33, pre = { 92432 }, preTitles = { [92432] = \"An Alarming Request\" }, map = 1421, x = 68.62, y = 45.18, z = 37.2, f = \"e\", group = { kind = \"dungeon\", map = 2959, name = \"City of Dalaran\" } },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"The City of Dalaran\",\n\t\tnote = \"The City of Dalaran is a dungeon for levels 28 to 33: go in through the sewers with the key Modera gave you. The arcane elementals throughout the city count for {quest:92457}. The {npc:246020}, the last boss, waits in the Purple Parlor above the Violet Citadel (a portal by {npc:246748} in the Citadel takes you up) and drops the {item:251961}. Beta players saw every kill in the dungeon pay {faction:2740} reputation, the bosses the most. Group of five advised below level 35.\",\n\t\tgoals = {\n\t\t\t{ t = \"kill\", quest = 92457, title = \"Starving Arcane\", target = \"Seeking Remnant\", npc = 247003, count = 8, oi = 1, map = 1416, x = 8.5, y = 59.3, group = { kind = \"dungeon\", map = 2959, name = \"City of Dalaran\" } },\n\t\t\t{ t = \"kill\", quest = 92457, title = \"Starving Arcane\", target = \"Saturated Remnant\", npc = 247001, count = 8, oi = 2, map = 1416, x = 8.5, y = 59.3, group = { kind = \"dungeon\", map = 2959, name = \"City of Dalaran\" } },\n\t\t\t{ t = \"kill\", quest = 92457, title = \"Starving Arcane\", target = \"Mana Echo\", npc = 246600, count = 8, oi = 3, map = 1416, x = 8.5, y = 59.3, group = { kind = \"dungeon\", map = 2959, name = \"City of Dalaran\" } },\n\t\t\t{ t = \"collect\", quest = 92458, title = \"Heart of Disruption\", item = 251961, itemName = \"Arcane Mote\", count = 1, oi = 1, map = 1416, x = 8.5, y = 59.3, note = \"{item:251961}, from the {npc:246020}\", from = \"Shade of the Archmage\", fromKind = \"npc\", fromRank = 1, fromId = 246020, fromNpcs = { { npc = 246020, npcName = \"Shade of the Archmage\" } }, group = { kind = \"elite\", rank = 1 } },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"Back to Modera's image\",\n\t\tgoals = {\n\t\t\t{ t = \"turnin\", quest = 92458, title = \"Heart of Disruption\", npc = 269127, npcName = \"Image of Archmage Modera\", map = 1421, x = 68.62, y = 45.18, z = 37.2, f = \"e\" },\n\t\t\t{ t = \"turnin\", quest = 92457, title = \"Starving Arcane\", npc = 269127, npcName = \"Image of Archmage Modera\", map = 1421, x = 68.62, y = 45.18, z = 37.2, f = \"e\", group = { kind = \"dungeon\", map = 2959, name = \"City of Dalaran\" } },\n\t\t\t{ t = \"accept\", quest = 92459, title = \"Friend of the Kirin Tor\", npc = 269127, npcName = \"Image of Archmage Modera\", minLevel = 24, qlvl = 33, pre = { 92458 }, preTitles = { [92458] = \"Heart of Disruption\" }, map = 1421, x = 68.62, y = 45.18, z = 37.2, f = \"e\" },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{npc:252085}\",\n\t\tnote = \"{npc:252085} waits in the Violet Citadel in {area:279}.\",\n\t\tgoals = {\n\t\t\t{ t = \"turnin\", quest = 92459, title = \"Friend of the Kirin Tor\", npc = 252085, npcName = \"Archmage Celindra\", map = 1416, x = 14.16, y = 60.01, z = 110.9, spotsPacked = \"14.2,60,110.9,15,2\" },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{quest:96800}\",\n\t\tnote = \"{npc:264265} in {area:279} wants a book back from {npc:6487}, the last boss of the {area:796}'s Library (levels 33 to 41), in {zone:1420}.\",\n\t\tgoals = {\n\t\t\t{ t = \"level\", level = 33 },\n\t\t\t{ t = \"accept\", quest = 96800, title = \"Past Due\", npc = 264265, npcName = \"Magus Olvek\", minLevel = 30, qlvl = 38, map = 1416, x = 9.8, y = 62.03, z = 102.4, spotsPacked = \"9.6,62.8,102.4,21,7\", group = { kind = \"dungeon\", map = 189, name = \"Scarlet Monastery\" } },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{npc:6487}\",\n\t\tnote = \"The {area:796} stands in the north-east of {zone:1420}; Doan waits at the end of the Library wing. Group of five advised below level 40.\",\n\t\tgoals = {\n\t\t\t{ t = \"collect\", quest = 96800, title = \"Past Due\", item = 273169, itemName = \"The Lost Magic of the Runemasters\", count = 1, oi = 1, map = 1420, x = 82.6, y = 33.8, note = \"{item:273169}, from {npc:6487}\", group = { kind = \"dungeon\", map = 189, name = \"Scarlet Monastery\" } },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"Back to {npc:264265}\",\n\t\tgoals = {\n\t\t\t{ t = \"turnin\", quest = 96800, title = \"Past Due\", npc = 264265, npcName = \"Magus Olvek\", map = 1416, x = 9.64, y = 62.8, z = 102.4, spotsPacked = \"9.6,62.8,102.4,21,7\", group = { kind = \"dungeon\", map = 189, name = \"Scarlet Monastery\" } },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"City of Dalaran runs to Friendly\",\n\t\tnote = \"The quests leave a non-Skyborne at about 320 of the 3,000 Friendly needs. The rest comes from kills in the City of Dalaran dungeon: run it until Friendly. How much each kill pays is not in the game's data; the bosses pay the most. At 60 you clear it alone.\",\n\t\tgoals = {\n\t\t\t{ t = \"rep\", faction = 2740, factionName = \"Kirin Tor\", standing = 5 },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{npc:32287}: the Azure recipes\",\n\t\tnote = \"{npc:32287} sells the Azure helm and shoulder recipes at Friendly, 10g each (skill 175). He stands upstairs in the building with the {faction:2740} banners in {area:279}. Buy the ones for your profession.\",\n\t\tgoals = {\n\t\t\t{ t = \"vendor\", npc = 32287, npcName = \"Archmage Alvareaux\", map = 1416, x = 13.85, y = 63.18, z = 102.5 },\n\t\t\t{ t = \"buy\", npc = 32287, npcName = \"Archmage Alvareaux\", item = 276984, itemName = \"Plans: Azure Skyforged Helm\", map = 1416, x = 13.85, y = 63.18, z = 102.5, optional = true, note = \"{item:276984} ({skill:164})\" },\n\t\t\t{ t = \"buy\", npc = 32287, npcName = \"Archmage Alvareaux\", item = 276985, itemName = \"Plans: Azure Skyforged Pauldrons\", map = 1416, x = 13.85, y = 63.18, z = 102.5, optional = true, note = \"{item:276985} ({skill:164})\" },\n\t\t\t{ t = \"buy\", npc = 32287, npcName = \"Archmage Alvareaux\", item = 276986, itemName = \"Pattern: Azure Gustwoven Hood\", map = 1416, x = 13.85, y = 63.18, z = 102.5, optional = true, note = \"{item:276986} ({skill:165})\" },\n\t\t\t{ t = \"buy\", npc = 32287, npcName = \"Archmage Alvareaux\", item = 276987, itemName = \"Pattern: Azure Gustwoven Spaulders\", map = 1416, x = 13.85, y = 63.18, z = 102.5, optional = true, note = \"{item:276987} ({skill:165})\" },\n\t\t\t{ t = \"buy\", npc = 32287, npcName = \"Archmage Alvareaux\", item = 276988, itemName = \"Pattern: Azure Windraveled Cover\", map = 1416, x = 13.85, y = 63.18, z = 102.5, optional = true, note = \"{item:276988} ({skill:165})\" },\n\t\t\t{ t = \"buy\", npc = 32287, npcName = \"Archmage Alvareaux\", item = 276989, itemName = \"Pattern: Azure Windraveled Drapes\", map = 1416, x = 13.85, y = 63.18, z = 102.5, optional = true, note = \"{item:276989} ({skill:165})\" },\n\t\t\t{ t = \"buy\", npc = 32287, npcName = \"Archmage Alvareaux\", item = 276990, itemName = \"Pattern: Azure Stormsewn Cowl\", map = 1416, x = 13.85, y = 63.18, z = 102.5, optional = true, note = \"{item:276990} ({skill:197})\" },\n\t\t\t{ t = \"buy\", npc = 32287, npcName = \"Archmage Alvareaux\", item = 276991, itemName = \"Pattern: Azure Stormsewn Epaulets\", map = 1416, x = 13.85, y = 63.18, z = 102.5, optional = true, note = \"{item:276991} ({skill:197})\" },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"City of Dalaran runs to Exalted\",\n\t\tnote = \"Nothing is sold at Honored or Revered in the game's data. Friendly to Exalted is 39,000 reputation, all from City of Dalaran kills. In Classic most dungeon kills stop paying at Honored or Revered; whether these do is not known yet.\",\n\t\tgoals = {\n\t\t\t{ t = \"rep\", faction = 2740, factionName = \"Kirin Tor\", standing = 8 },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"The {item:285327}\",\n\t\tnote = \"{npc:32287} and {npc:28776}, the tabard vendor in {area:279}, sell the {item:285327} at Exalted for 25g.\",\n\t\tgoals = {\n\t\t\t{ t = \"buy\", npc = 32287, npcName = \"Archmage Alvareaux\", item = 285327, itemName = \"Kirin Tor Tabard\", map = 1416, x = 13.85, y = 63.18, z = 102.5 },\n\t\t},\n\t},\n}",
		})
	end
	register()
end

