 npc = 1749, npcName = \"Lady Katrana Prestor\", oi = 1, text = \"Speak with {npc:1749}\", map = 1453, x = 79.87, y = 38.44, z = 122.8, spotsPacked = \"80.1,38.3,122.8,15,4\" },\n\t\t\t{ t = \"turnin\", quest = 4185, title = \"The True Masters\", npc = 1748, npcName = \"Highlord Bolvar Fordragon\", map = 1453, x = 79.8, y = 38.51, z = 122.6, spotsPacked = \"79.9,38.6,122.6,15,7\" },\n\t\t\t{ t = \"accept\", quest = 4186, title = \"The True Masters\", npc = 1748, npcName = \"Highlord Bolvar Fordragon\", minLevel = 48, qlvl = 54, pre = { 4185 }, preTitles = { [4185] = \"The True Masters\" }, map = 1453, x = 79.8, y = 38.51, z = 122.6, spotsPacked = \"79.9,38.6,122.6,15,7\", note = \"{quest:4184}, +100\" },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{area:69}: Solomon again\",\n\t\tnote = \"With a group the chain goes on into {area:1584}: {npc:9023}, Jail Break! and The Great Masquerade back in {faction:72} pay about 750 {faction:72} more, Maxwell's Mission (Lower {area:1583}) 250, Delivery to Ridgewell 135. Order Must Be Restored ({npc:11878} in the {zone:1423}) pays 200, The Key to {area:2057} 200; Onyxia's head 400 and Nefarian's 200 when the raids open.\",\n\t\tgoals = {\n\t\t\t{ t = \"turnin\", quest = 4186, title = \"The True Masters\", npc = 344, npcName = \"Magistrate Solomon\", map = 1433, x = 24.82, y = 44.37, z = 67.6, spotsPacked = \"24.8,44.4,67.6,15,3\" },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{quest:7796} to Honored\",\n\t\tnote = \"{quest:7796}: 50 reputation for 20 {item:14047}, as often as you like. After the four first donations a non-Human stands at Friendly 700 of 6,000, so Honored is 5,300 away: 106 turn-ins, 2,120 {item:14047} (Humans start 900 higher: 88 turn-ins; a Skyborne's Exploring the Alliance paid 100, two fewer). The level 52-58 quests above take 23 turn-ins off; every Elwynn hub you did takes 20 to 30 more off. More quest hubs pay {faction:72}, in full while they are no more than 5 levels below you: {zone:1436} (about 2,500 in all), Redridge's {area:69} (about 3,000) and {zone:1431}'s {area:42} (about 2,900). Every city gain also gives a quarter as much to the other three Alliance cities (not counted here). Hand in all your {item:14047} at once.\",\n\t\tgoals = {\n\t\t\t{ t = \"collect\", item = 14047, itemName = \"Runecloth\", count = 20, optional = true, candidates = candidateLists[1] },\n\t\t\t{ t = \"turnin\", quest = 7796, title = \"Additional Runecloth\", npc = 14722, npcName = \"Clavicus Knavingham\", minLevel = 50, qlvl = 60, pre = { 7795 }, map = 1453, x = 53.86, y = 81.41, z = 97.4, spotsPacked = \"53.9,81.4,97.4,15,2\", optional = true, direct = true },\n\t\t\t{ t = \"rep\", faction = 72, factionName = \"Stormwind\", standing = 6 },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{quest:7796} to Revered\",\n\t\tnote = \"Honored: in Classic Stormwind's vendors take 10% off for you, {npc:384}'s horses (20g, the swift ones 200g) included; Forever has not settled it, and guide sites report 5% at Friendly rising to 20% at Exalted. Honored to Revered is 12,000 reputation: 240 turn-ins, 4,800 {item:14047}.\",\n\t\tgoals = {\n\t\t\t{ t = \"collect\", item = 14047, itemName = \"Runecloth\", count = 20, optional = true, candidates = candidateLists[1] },\n\t\t\t{ t = \"turnin\", quest = 7796, title = \"Additional Runecloth\", npc = 14722, npcName = \"Clavicus Knavingham\", minLevel = 50, qlvl = 60, pre = { 7795 }, map = 1453, x = 53.82, y = 81.26, z = 97.4, spotsPacked = \"53.9,81.4,97.4,15,2\", optional = true, direct = true },\n\t\t\t{ t = \"rep\", faction = 72, factionName = \"Stormwind\", standing = 7 },\n\t\t},\n\t},\n\t{\n\t\ttitle = \"{quest:7796} to Exalted\",\n\t\tnote = \"Revered to Exalted is 21,000 reputation: 420 turn-ins, 8,400 {item:14047}. At Exalted, {npc:384} at {area:88} sells her horses to other races in Classic; the Horse and Swift Horse guides cover them.\",\n\t\tgoals = {\n\t\t\t{ t = \"collect\", item = 14047, itemName = \"Runecloth\", count = 20, optional = true, candidates = candidateLists[1] },\n\t\t\t{ t = \"turnin\", quest = 7796, title = \"Additional Runecloth\", npc = 14722, npcName = \"Clavicus Knavingham\", minLevel = 50, qlvl = 60, pre = { 7795 }, map = 1453, x = 53.82, y = 81.26, z = 97.4, spotsPacked = \"53.9,81.4,97.4,15,2\", optional = true, direct = true },\n\t\t\t{ t = \"rep\", faction = 72, factionName = \"Stormwind\", standing = 8 },\n\t\t},\n\t},\n}",
		})
	end
	register()
end

